  // 칸의 기본 글. 갈래 없는 칸은 어느 갈래로 물어도 같다. 그 갈래에 없는 칸은 undefined.
  function promptDefaultText(id, branch = 'common') {
    if (Object.prototype.hasOwnProperty.call(PROMPT_TEXT, id)) return PROMPT_TEXT[id];
    if (id === 'axis.guide') return axisGuideForAnalysis();
    if (id === 'axis.sexual') return sexAxisGuideForAnalysis();
    if (id === 'axis.sexualMotive') return sexMotiveGuideForAnalysis();
    if (PROMPT_DIRECTOR_IDS.has(id)) return promptDirectorText(promptPolicyFor(branch === 'common' ? 'nsfw' : branch))[id];
    return undefined;
  }
  function promptOverridesNow() {
    const value = configCache?.promptOverrides;
    return isPlainObject(value) ? value : {};
  }
  // 덮어쓰기 적용: 그 갈래의 글 → (NSFW+는 NSFW 글) → 공통 글 → 기본 글. 빈 글은 덮어쓰지 않은 것으로 본다.
  function promptSectionText(id, branch = 'common', overrides = promptOverridesNow()) {
    const base = promptDefaultText(id, branch);
    if (base === undefined) return undefined;
    const own = isPlainObject(overrides?.[id]) ? overrides[id] : null;
    if (!own) return base;
    const candidates = branch === 'common' ? [own.common] : branch === 'plus' ? [own.plus, own.nsfw, own.common] : [own[branch], own.common];
    const pick = candidates.find(text => typeof text === 'string' && text.length);
    return pick === undefined ? base : pick;
  }
  // 칸의 갈래 모양: 'common'(갈래마다 같음) · 'split'(SFW·NSFW 다름) · 'plus'(NSFW+도 다름) · 'nsfwOnly'(SFW에 없음) · 'plusOnly'(SFW에 없고 NSFW+가 다름, 2026-10-29 수단 대상)
  function promptSectionKind(id) {
    if (!PROMPT_SECTION_INDEX.has(id) || !PROMPT_DIRECTOR_IDS.has(id)) return 'common';
    const sfw = promptDefaultText(id, 'sfw'), nsfw = promptDefaultText(id, 'nsfw'), plus = promptDefaultText(id, 'plus');
    if (sfw === undefined) return plus !== nsfw ? 'plusOnly' : 'nsfwOnly';
    if (sfw === nsfw && nsfw === plus) return 'common';
    return plus !== nsfw ? 'plus' : 'split';
  }
  
  // 고친 글에서 빠진 자료 자리(기본 글에는 있는데 고친 글에 없는 것)
  function promptSlotsMissing(id, text) {
    const wanted = PROMPT_SECTION_INDEX.get(id)?.slots || [];
    return wanted.filter(slot => !String(text || '').includes(`{{${slot}}}`));
  }
  // 장 조립: 참조 칸은 그 칸(또는 그 장)의 글, suffix·shared 칸은 빼고, gap 칸 앞에는 빈 줄.
  function promptAssemble(pageId, branch = 'common', overrides = promptOverridesNow()) {
    const page = PROMPT_PAGE_INDEX.get(pageId);
    if (!page) return '';
    const parts = [];
    for (const section of page.sections) {
      if (section.part) continue;
      const id = section.ref || section.id;
      const text = section.ref && PROMPT_PAGE_INDEX.has(id) ? promptAssemble(id, branch, overrides) : promptSectionText(id, branch, overrides);
      if (text === undefined) continue;
      parts.push((section.gap ? '\n' : '') + text);
    }
    return parts.join(page.sep);
  }
  // 장면 판단에 실제로 보내는 지시문: 본문 + 같은 프로필 덧말 + (코코에몬) + (빠진 턴) + (계획만 다시)
  function promptDirectorInstruction(policy = contentPolicyFor(null), extra = {}) {
    const branch = promptBranchOf(policy);
    return promptAssemble('director', branch)
      + '\n' + promptSectionText('director.sameProfile', branch)
      + (extra.koco ? '\n' + promptSectionText('director.koco', branch) : '')
      + (extra.missed ? '\n' + promptSectionText('director.missed', branch) : '')
      + (extra.planOnly ? '\n' + promptSectionText('emergency.planOnly', branch) : '');
  }
  function promptAxisSystem() { return promptAssemble('axis', 'common'); }
  // 성적 축 호출 지시문(2026-10-22): 역할·변형 규칙 + 성적 축 넷·동기 유형 채점판 + 답 규칙 + 성적 축 출력 틀 + 덧말. 여덟 축 채점 바로 뒤에 같은 자료로 부른다.
  function promptAxisSexualSystem() {
    return ['axis.role', 'axis.variant', 'axis.sexual', 'axis.sexualMotive', 'axis.answers', 'axis.sexualOutput'].map(id => promptSectionText(id, 'common')).join('\n\n')
      + '\n' + promptSectionText('axis.sexualOnlyNote', 'common');
  }
  function promptProfileSystem() { return promptAssemble('profile', 'common'); }
  function promptKoreanSystem() { return promptSectionText('korean.body', 'common'); }
  // 설정값 정리: 아는 칸·갈래만, 글은 한도까지, 빈 글은 뺀다
  function normalizePromptOverrides(value) {
    const result = {};
    if (!isPlainObject(value)) return result;
    for (const [id, branches] of Object.entries(value)) {
      if (!PROMPT_SECTION_INDEX.has(id) || !isPlainObject(branches)) continue;
      const entry = {};
      for (const branch of PROMPT_BRANCHES) {
        const text = branches[branch];
        if (typeof text === 'string' && text.length) entry[branch] = text.slice(0, PROMPT_TEXT_LIMIT);
      }
      if (Object.keys(entry).length) result[id] = entry;
    }
    return result;
  }
  function normalizePromptPresets(value) {
    if (!Array.isArray(value)) return [];
    const result = [], seen = new Set();
    for (const item of value) {
      if (!isPlainObject(item)) continue;
      const name = String(item.name || '').trim().slice(0, 60);
      if (!name || seen.has(name)) continue;
      seen.add(name);
      result.push({ name, overrides: normalizePromptOverrides(item.overrides) });
      if (result.length >= 20) break;
    }
    return result;
  }
  function normalizePromptCardOrder(value) {
    const ids = PROMPT_PAGES.map(page => page.id);
    const unique = [...new Set(Array.isArray(value) ? value.filter(id => ids.includes(id)) : [])];
    return unique.length ? [...unique, ...ids.filter(id => !unique.includes(id))] : [];
  }
  
  // 프리셋 파일 읽기: {kind:'erosync-prompts', presets:[{name, overrides}], current:{name, overrides}} 또는 {name, overrides}. 자료로만 읽는다(아는 칸·갈래만, 글 한도).
  

  function axisGuideForAnalysis() {
    const lines = [
      'THE EROSYNC AXIS DOCTRINE',
      'Each axis answers one question that the scene director must answer when this character acts first. Score how the character does it, not whether it happens.',
      '',
      'Common rules:',
      '1. Values decide how, not whether. Action probability is a separate setting; the values decide when, by which path, how far, and in front of whom the character acts once it acts first.',
      '2. One clue, one axis. Use each sentence of the source for one axis only. Descriptions that converge on the dark core ("cold", "manipulative", "holds grudges") are split by question and written in one place only: the will to pay back (retaliation), the ceiling of harm (extremity), or the path (directness). Never turn "clings" into "persistent" (obsessiveness is not goalPersistence), and never take an act done in a burst of anger as evidence for the ceiling of means (that is spontaneity).',
      '3. Answer first, then score. For each axis, answer its question for this character, attach evidence, then read the value from the bands and give a confidence.',
      '4. Every axis gets a judgment about this character, never a report on the source. Read the whole character (its description, role, speech, relationships, world and genre) and write what this character does, even where the source leaves it implicit; then read the value from the bands. The strength of the support goes into confidence only: a direct description 60-100, an inference from personality or role 30-59, a reading of the overall impression alone 0-29. Never move the value toward the middle to express uncertainty, and never answer that the source gives no clue.',
      'A range missing from a band table (for example 21-40 when only 0-20 and 41-60 are listed) lies between its neighbors.',
    ];
    for (const axis of AXIS_KEYS) {
      const item = AXIS_DEFINITIONS[axis];
      lines.push('', `## ${axis}: ${item.scoringQuestion || item.question}${axis === 'retaliation' ? ' (stored as retaliation.level)' : ''}`, item.definition, 'Bands:');
      // 구간 셋째 칸은 채점할 때만 쓰는 안내다(장면 판단 사용판에는 넣지 않는다).
      for (const [range, text, scoringNote] of item.bands) lines.push(`- ${range}: ${text}${scoringNote ? ` ${scoringNote}` : ''}`);
      lines.push(`Raise for: ${item.up}`, `Lower for: ${item.down}`, `Never use as a clue: ${item.never}`);
      if (item.dispositional) lines.push(item.dispositional);
    }
    lines.push('', 'Splitting a description that touches two axes:', ...AXIS_OVERLAP_RULES.map(rule => `- ${rule}`));
    return lines.join('\n');
  }

  // ---------- 성적 축 넷·성적 동기 유형 (2026-10-22, Erosync.Sexual-Axes.Work-Plan.md 1·2절) ----------
  // 정의학 문서 6·7절의 번역이다. 어긋나면 문서가 기준이다. 채점은 1단계 축 채점 호출에 "성적 축" 묶음(sexualAxes·sexualMotive)으로 함께 들어가고,
  // 값은 baseProfile에 eroticInterest(기존 키, level)·sexualSpontaneity·sexualOpenness·sexualMomentum(숫자)·sexualMotive(유형)로 저장된다.
  // 답·근거·신뢰도·한글은 axisAnswers에 같은 키로 들어간다. 미분석이면 숫자 필드가 없다(8축과 같다). SFW 봇도 채점·저장하고 화면과 장면 판단에서만 가린다.

  // 채점판: 1단계 지시문의 "성적 축" 칸(axis.sexual). 8축 채점판과 같은 모양(정의·구간·단서·겹침)이다.
  function sexAxisGuideForAnalysis() {
    const lines = [
      'SEXUAL AXES (scored in a separate pass right after the eight axes, from the same source, in the same answer-evidence-value-confidence form)',
      'Four sexual dispositions decide whether and when this is a character who goes toward sex; the eight axes decide how a character moves. The common rules of the eight axes apply here too (one clue one axis, answer first then score, every axis gets a judgment about the character), with five more:',
      ...SEX_AXIS_COMMON_RULES.map((rule, index) => `${index + 1}. ${rule}`),
      'The band cut points (0-19, 20-39, 40-59, 60-79, 80-100) are design conventions, not research cut points; the averages and shares quoted in the bands are Western-sample defaults. A range missing from a band table lies between its neighbors. Judge every sexual axis for this character as rule 4 of the eight axes says: read the whole character and write what it does; the strength of the support goes into confidence, never into a middle value, and "the source gives no clue" is not an answer. eroticInterest is scored here, under sexualAxes, and replaces the profile\'s eroticInterest level.',
    ];
    for (const axis of SEX_AXIS_KEYS) {
      const item = SEX_AXIS_DEFINITIONS[axis];
      lines.push('', `## ${axis}: ${item.scoringQuestion || item.question}`, item.definition, 'Bands:');
      // 구간 셋째 칸은 채점할 때만 쓰는 안내다(장면 판단 사용판에는 넣지 않는다).
      for (const [range, text, scoringNote] of item.bands) lines.push(`- ${range}: ${text}${scoringNote ? ` ${scoringNote}` : ''}`);
      lines.push(`Raise for: ${item.up}`, `Lower for: ${item.down}`);
      if (item.stateOnly) lines.push(`Treat as a scene state, not a clue: ${item.stateOnly}`);
      lines.push(`Never use as a clue: ${item.never}`);
    }
    lines.push('', 'Splitting a description that touches a sexual axis and another axis:', ...SEX_AXIS_OVERLAP_RULES.map(rule => `- ${rule}`));
    return lines.join('\n');
  }

  // 채점판: 1단계 지시문의 "성적 동기 유형" 칸(axis.sexualMotive).
  function sexMotiveGuideForAnalysis() {
    const lines = [
      'SEXUAL MOTIVE TYPE (one primary type, one optional secondary type)',
      'Why this character has sex, and so which moment it reads as the time. Four types: pleasure, intimacy, instrumental, reassurance. Everyone scores on every motive, so pick the one that dominates as primary and, when a second clearly shows, a secondary. Detect from the shape of the profile (which reason dominates), the character\'s own stated reasons and how it is the morning after, not from the level of endorsement. Sexual eagerness or frequency is not a marker of the pleasure type: attachment anxiety raises every motive except physical pleasure. "To please my partner" is a common reason and not by itself the reassurance type; "I did not want to disappoint" and "I felt I owed it" are its duty versions. The intimacy and reassurance types use the same words ("to feel loved", "closeness"), so divide them by function, not by the surface feeling: when interest rises after the partner grows distant, after a rejection cue, when the partner insists or when self-esteem is low, it is the reassurance type. Never assign the intimacy type by gender: love and commitment reasons show no sex difference, and gender signals exist only for physical-attraction and opportunity reasons (higher in men) and partner-demand and compliance reasons (higher in women). Coping (sex to escape a bad mood after a breakup, a betrayal or heavy stress) is a state, not a type: note it in evidence when present.',
    ];
    for (const type of SEX_MOTIVE_TYPES) {
      const item = SEX_MOTIVE_DEFINITIONS[type];
      lines.push('', `## ${type}`, item.definition, `Detect from: ${item.cues}`, `Goes: ${item.goes}`, `Holds back: ${item.holds}`);
    }
    lines.push('', 'Return sexualMotive in each character object beside sexualAxes, as the schema below shows: primary (one of pleasure, intimacy, instrumental, reassurance), secondary (the same set, or empty), evidence (at most two short verbatim quotes), confidence (0-100).');
    return lines.join('\n');
  }

  // 사용판: 장면 판단 지시문의 "성적 축 사용판" 칸(axis.sexualDirector, NSFW·NSFW+). SFW에는 없다(undefined → 조립에서 빠진다).
  function sexAxisGuideForDirector(policy = contentPolicyFor(null)) {
    if (policy?.contentMode === 'sfw') return undefined;
    const lines = [
      `- Sexual axes. A candidate may carry four more values from 0 to 100 (eroticInterest, sexualSpontaneity, sexualOpenness, sexualMomentum) and a sexualMotive. They decide whether and when this character goes toward sex; the eight axes decide how. Read each value with its axisAnswers entry when present; a confidence under 30 means the analyst read the value from the character's overall impression rather than a direct description, so use it as an estimate the scene may override, not as a firm trait. Five rules:`,
      ...SEX_AXIS_COMMON_RULES.map((rule, index) => `  ${index + 1}. ${rule}`),
    ];
    for (const axis of SEX_AXIS_KEYS) {
      const item = SEX_AXIS_DEFINITIONS[axis];
      lines.push(`- ${axis} (${item.question}) ${item.director}`);
      for (const [range, band] of item.bands) lines.push(`  ${range}: ${band}`);
    }
    lines.push(`- sexualMotive says why this character has sex: which moment it reads as the time (goes) and when it holds back. It is primary plus an optional secondary; read it with its evidence. It also guides how many sexual targets the character keeps and how desire moves after fulfillment: intimacy-type and highly obsessive characters converge on one target while pleasure-type and highly spontaneous ones keep several; after fulfillment desire dips a little and climbs back for the intimacy type, drops further and sways toward new stimulation for the pleasure type, folds when the purpose is done for the instrumental type, and jumps again at the next insecurity for the reassurance type. The value you see is the current one for this chat; it may already differ from the analysis.`);
    for (const type of SEX_MOTIVE_TYPES) {
      const item = SEX_MOTIVE_DEFINITIONS[type];
      lines.push(`  ${type}: ${item.definition} Goes: ${item.goes} Holds back: ${item.holds}`);
    }
    lines.push(`- Coping is a state, not a type: for a while after a loss, a breakup or heavy stress, pleasure-type characters go more easily and reassurance-type characters also go "to soothe the mood"; it fades with time. An unresolved open conflict lowers relational motives for everyone.`);
    return lines.join('\n');
  }

  function normalizeSexualMotive(value) {
    if (!isPlainObject(value)) return null;
    const primary = String(value.primary || '').trim().toLowerCase();
    if (!SEX_MOTIVE_TYPES.includes(primary)) return null;
    const secondaryRaw = String(value.secondary || '').trim().toLowerCase();
    const secondary = SEX_MOTIVE_TYPES.includes(secondaryRaw) && secondaryRaw !== primary ? secondaryRaw : '';
    return { primary, secondary, evidence: normalizeStringList(value.evidence, 4, 300), confidence: Math.round(clampNumber(value.confidence, 0)) };
  }

  

  // 성적 축이 채점됐는가: 새 숫자 셋이 모두 있을 때.
  

  // 1단계 응답 한 인물분의 성적 묶음(sexualAxes·sexualMotive)을 저장할 필드와 답으로 바꾼다. 둘 다 없으면 null.
  // 0~1 소수로만 답했으면 100을 곱해 읽는다(8축과 같다). eroticInterest는 기존 모양 {level, confidence, notes}로 쓴다.
  function sexualAxisFields(item) {
    const block = isPlainObject(item?.sexualAxes) ? item.sexualAxes : null;
    const motive = normalizeSexualMotive(item?.sexualMotive);
    if (!block && !motive) return null;
    const fields = {}, answers = {};
    if (block) {
      const given = SEX_AXIS_KEYS.map(axis => isPlainObject(block[axis]) ? block[axis].value : undefined);
      const numbers = given.map(value => typeof value === 'number' ? value : typeof value === 'string' && value.trim() ? Number(value) : NaN);
      const finite = numbers.filter(Number.isFinite);
      const fractional = finite.length > 0 && finite.every(value => value >= 0 && value <= 1) && finite.some(value => value > 0 && value < 1);
      SEX_AXIS_KEYS.forEach((axis, index) => {
        const entry = block[axis];
        if (!isPlainObject(entry)) return;
        const value = optionalTrait(fractional && Number.isFinite(numbers[index]) ? numbers[index] * 100 : given[index]);
        if (axis === 'eroticInterest') {
          if (value !== undefined) fields.eroticInterest = { level: value, confidence: Math.round(clampNumber(entry.confidence, 0)), notes: truncate(entry.answer, 500) };
        } else if (value !== undefined) fields[axis] = value;
        answers[axis] = { answer: entry.answer, evidence: entry.evidence, confidence: entry.confidence };
      });
    }
    if (motive) fields.sexualMotive = motive;
    return { fields, answers, complete: SEX_AXIS_KEYS.every(axis => Number.isFinite(sexAxisValueOf(fields, axis))) && !!motive };
  }


  // 성적 축 호출의 답을 1단계 결과(entry.fields)에 합친다. 성적 필드는 덮고, 답은 여덟 축 답 옆에 더한다.
  function mergeSexualFields(entry, sexual) {
    if (!entry || !sexual) return false;
    Object.assign(entry.fields, sexual.fields);
    const merged = normalizeAxisAnswers({ ...(isPlainObject(entry.fields.axisAnswers) ? entry.fields.axisAnswers : {}), ...sexual.answers });
    if (merged) entry.fields.axisAnswers = merged;
    return true;
  }
  // 성적 축 호출: 여덟 축 채점이 끝난 후보(건너뜀 아님)마다 같은 자료로 성적 축 넷·동기 유형을 받아 entries에 합친다. 두 사람씩 부른다.
  // 실패해도 던지지 않는다(중지·오래된 작업만 던진다): 성적 축은 미분석으로 남아 홈 "성적 축 채우기"에 잡힌다. 돌려주는 값: 합친 사람 수.
  async function scoreSexualAxesForGroup({ group, targetList, promptHead, sourceText, axisNote = '', entries, config, requestGuard = null, label, fence = null, onProgress = null }) {
    const scored = (group || []).filter(candidate => { const entry = entries?.get?.(candidate); return entry && !entry.skip; });
    if (!scored.length) return 0;
    const chunks = axisCallChunks(scored);
    let merged = 0;
    for (const [chunkIndex, chunk] of chunks.entries()) {
      const chunkLabel = `${label}${chunks.length > 1 ? `.${chunkIndex + 1}` : ''}`;
      const chunkIds = new Set(chunk.map(candidate => candidate.id));
      const body = ['TARGET CHARACTERS:', JSON.stringify((targetList || []).filter(item => chunkIds.has(item.id)), null, 2), '', 'BOUNDED SOURCE EXCERPTS:', sourceText];
      try {
        onProgress?.(chunk.map(candidate => candidate.name || candidate.id).join(', '));
        const raw = await runJsonTask(promptAxisSexualSystem() + axisNote, truncate([...promptHead, ...body].join('\n'), config.analysisProfileBatchChars + 8000), config, 'profile', chunkLabel, { requestGuard, webSearch: true });
        if (fence) assertBackgroundFence(fence, `${chunkLabel} model return`);
        for (const candidate of chunk) {
          const sexual = sexualAxisFields(sexualAxesReplyItem(raw, candidate));
          if (sexual && mergeSexualFields(entries.get(candidate), sexual)) merged += 1;
        }
      } catch (error) {
        if (isStaleLifecycleError(error) || (fence && !backgroundFenceIsCurrent(fence))) throw error;
        requestGuard?.throwIfAborted(chunkLabel);
        if (analysisRuntime.cancelRequested) throw error;
        warn(`${chunkLabel} skipped:`, error?.message || error);
      }
    }
    return merged;
  }

  // 사용판: 장면 판단 지시문에 들어가는 정의학(공통 규칙·축마다 사용 문단·구간). 단서표는 넣지 않는다.
  // NSFW에서는 개방성에 친밀·성적 행동을 덧붙이고, NSFW+에서는 극단성 높은 끝의 문단을 붙인다.


  // 분석 1단계(축 채점) 지시문. 같은 묶음을 2단계(프로필 작성)보다 먼저 한 번 더 보낸다.
  // 지시문 등록부(2026-10-15): 기본 글. 실제 호출은 덮어쓰기를 적용한 등록부 함수를 거친다.
  
  // 지시문 등록부(2026-10-15): 기본 글. 실제 호출은 덮어쓰기를 적용한 등록부 함수를 거친다.
  
  // 지시문 등록부(2026-10-15): 기본 글. 실제 호출은 덮어쓰기를 적용한 등록부 함수를 거친다.
  

  // 1단계 답(축마다 답 문장·근거·신뢰도)을 저장 모양으로 정리한다. 답도 근거도 없는 축은 빼고, 남는 축이 없으면 undefined.
  // 1단계 답(축마다 답 문장·근거·신뢰도)을 저장 모양으로 정리한다. 답도 근거도 없는 축은 빼고, 남는 축이 없으면 undefined.
  // answerKo(2026-10-12): 영어 답을 화면용으로 다시 쓴 한글. 영어 답이 있을 때만 붙고, AI 입력에는 쓰지 않는다.
  // 성적 축(2026-10-22): 성적 축 넷(eroticInterest·sexualSpontaneity·sexualOpenness·sexualMomentum)의 답도 같은 모양으로 여기에 든다.
  function normalizeAxisAnswers(value) {
    if (!isPlainObject(value)) return undefined;
    const result = {};
    for (const axis of [...AXIS_KEYS, ...SEX_AXIS_KEYS]) {
      const item = value[axis];
      if (!isPlainObject(item)) continue;
      const answer = truncate(item.answer, 400).trim();
      const evidence = normalizeStringList(item.evidence, 4, 300);
      if (!answer && !evidence.length) continue;
      result[axis] = { answer, evidence, confidence: Math.round(clampNumber(item.confidence, 0)) };
      const answerKo = answer ? truncate(item.answerKo, 400).trim() : '';
      if (answerKo) result[axis].answerKo = answerKo;
    }
    return Object.keys(result).length ? result : undefined;
  }

  // ---------- 8축 답 한글 설명(2026-10-12): 영어 답을 다 쓴 뒤 화면용 한글로 다시 쓴다 ----------
  // 1단계 호출에 함께 넣으면 출력 한도(기본 5,000토큰, 한 호출 4명)에서 잘릴 수 있어 따로 부른다.
  // 입력은 저장된 영어 답뿐이다(원문 자료·근거는 보내지 않음). 결과는 화면에만 쓰고 장면 판단·2단계·메인 모델에는 보내지 않는다.
  // 8축 한글 설명 지시문(기본 글)은 지시문 등록부(21-prompts-registry.js, korean.body)에 있다. 실제 호출은 promptKoreanSystem()이 덮어쓰기를 적용한다.
  

  // 답 읽기(2026-10-12 보완, 너그럽게): 실제 모델이 모양을 조금 바꿔도 꺼낸다.
  // 인물 목록 = characters·results·profiles·items·data 배열, 최상위 배열, 인물 하나짜리 객체, 또는 id를 키로 한 객체.
  // 인물 맞추기 = id → 이름 → (하나도 못 맞췄고 수가 같으면) 순서. 축 = 영어 키·한국어 축 이름(주도성 등). 값 = 글자 또는 한 겹 묶인 객체.
  // 성적 축(2026-10-22): 성적 축 넷의 답도 같은 호출로 한글을 만든다(키·한국어 이름 모두 받는다).
  const AXIS_KOREAN_ALL_KEYS = Object.freeze([...AXIS_KEYS, ...SEX_AXIS_KEYS]);
  const AXIS_KOREAN_LABELS = Object.freeze(Object.fromEntries([...AXIS_KEYS.map(axis => [AXIS_DEFINITIONS[axis].label, axis]), ...SEX_AXIS_KEYS.map(axis => [SEX_AXIS_DEFINITIONS[axis].label, axis])]));
  function axisKoreanAxisOf(key) {
    const name = String(key || '').trim();
    return AXIS_KOREAN_ALL_KEYS.find(axis => axis.toLowerCase() === name.toLowerCase()) || AXIS_KOREAN_LABELS[name] || (name.toLowerCase() === 'retaliation.level' ? 'retaliation' : '');
  }
  function axisKoreanReplyList(raw) {
    if (Array.isArray(raw)) return raw.filter(isPlainObject);
    if (!isPlainObject(raw)) return [];
    for (const key of ['characters', 'results', 'profiles', 'items', 'data']) if (Array.isArray(raw[key])) return raw[key].filter(isPlainObject);
    if (isPlainObject(raw.axes) || isPlainObject(raw.answers) || Object.keys(raw).some(axisKoreanAxisOf)) return [raw];
    return Object.entries(raw).filter(([, value]) => isPlainObject(value)).map(([key, value]) => ({ id: key, ...value }));
  }
  function axisKoreanAxes(hit) {
    if (!isPlainObject(hit)) return {};
    const container = isPlainObject(hit.axes) ? hit.axes : isPlainObject(hit.answers) ? hit.answers : isPlainObject(hit.axisAnswers) ? hit.axisAnswers : hit;
    const result = {};
    for (const [key, value] of Object.entries(container)) {
      const axis = axisKoreanAxisOf(key);
      const text = axis ? truncate(axisKoreanText(value), 400).trim() : '';
      if (text && /[가-힣]/.test(text)) result[axis] = text;
    }
    return result;
  }
  function axisKoreanMatch(group, raw) {
    const list = axisKoreanReplyList(raw);
    const same = (left, right) => { const a = String(left ?? '').normalize('NFC').trim().toLowerCase(); return !!a && a === String(right ?? '').normalize('NFC').trim().toLowerCase(); };
    const used = new Set(), matched = new Map();
    const take = (item, hit) => { if (hit) { used.add(hit); matched.set(item.id, hit); } };
    for (const item of group) take(item, list.find(value => !used.has(value) && same(value.id, item.id)));
    for (const item of group) if (!matched.has(item.id)) take(item, list.find(value => !used.has(value) && (same(value.name, item.name) || same(value.id, item.name))));
    if (!matched.size && list.length === group.length) group.forEach((item, index) => take(item, list[index]));
    return matched;
  }


  // 한글이 빠진 축의 영어 답. 없으면 null.
  function axisKoreanItem(root, variantKey) {
    const answers = axisKoreanBaseRecords(root, variantKey)[0]?.axisAnswers;
    if (!isPlainObject(answers)) return null;
    const axes = {};
    for (const axis of AXIS_KOREAN_ALL_KEYS) if (answers[axis]?.answer && !answers[axis].answerKo) axes[axis] = String(answers[axis].answer);
    return Object.keys(axes).length ? { id: root.id, name: root.name || root.id, axes } : null;
  }

  // 현재 봇·변형에서 한글을 채울 인물(홈 "한글 설명 채우기" 단추).
  

  // 한글 저장: 영어 답이 보낼 때와 같은 축에만 넣는다(그 사이 재채점됐으면 버림).
  async function saveAxisKorean(results, variantKey, fence) {
    if (!results.size) return 0;
    const transaction = await mutateProfileRegistry('axis korean', fresh => {
      let written = 0;
      for (const [id, axes] of results) {
        for (const base of axisKoreanBaseRecords(fresh.profiles?.[id], variantKey)) {
          if (!isPlainObject(base.axisAnswers)) continue;
          for (const [axis, entry] of Object.entries(axes)) {
            const stored = base.axisAnswers[axis];
            if (isPlainObject(stored) && truncate(stored.answer, 400).trim() === entry.answer) { stored.answerKo = entry.ko; written += 1; }
          }
        }
      }
      return written;
    }, { fence, writeRegistry: false });
    return transaction.outcome || 0;
  }


  // 한글 다시 쓰기 실행(채우기 단추·개별 재분석·분석 묶음이 함께 씀). items = [{ id, name, axes: { 축: 영어 답 } }].
  // size명씩 부르고, 여러 명 호출에서 못 건진 사람은 한 명씩 다시 보낸다. 오류·빈 답이 두 번 이어지면 나머지는 부르지 않는다
  // (키·연결·모양 문제). 건진 사람마다 onFilled(item, { 축: 한글 })을 부른다. 저장은 부르는 쪽이 한다.
  // 돌려주는 값: { total, done, failed, stopped, reason } — reason은 실패 이유 한 마디(상태 줄·홈 경고에 씀).
  async function axisKoreanRun(items, { config, requestGuard = null, fence = null, size = 1, onGroup = null, afterGroup = null, onFilled }) {
    const summary = { total: items.length, done: 0, failed: 0, stopped: false, reason: '' };
    if (!items.length) return summary;
    const filled = new Set();
    const stopNow = () => analysisRuntime.cancelRequested || requestGuard?.aborted;
    let failures = 0, calls = 0;
    const note = error => {
      if (summary.reason) return;
      const status = clampInt(error?.status || error?.statusCode || error?.httpStatus, 0, 0, 999);
      summary.reason = status ? `HTTP ${status}` : truncate(String(error?.message || error || '오류').split('\n')[0], 60);
    };
    // 한 번 부르고 건진 사람 수를 돌려준다. 못 건지면(빈 답·모양 다름) 실패로 센다.
    const ask = async group => {
      calls += 1;
      const raw = await runJsonTask(promptKoreanSystem(), `CHARACTERS:\n${JSON.stringify(group.map(item => ({ id: item.id, name: item.name, axes: item.axes })))}`,
        config, 'profile', `axis korean ${calls}`, { requestGuard });
      if (fence) assertBackgroundFence(fence, 'axis korean model return');
      const matched = axisKoreanMatch(group, raw);
      let saved = 0;
      for (const item of group) {
        const got = axisKoreanAxes(matched.get(item.id));
        const axes = {};
        for (const axis of Object.keys(item.axes)) if (got[axis]) axes[axis] = got[axis];
        if (Object.keys(axes).length) { onFilled(item, axes); filled.add(item.id); saved += 1; }
      }
      return saved;
    };
    const attempt = async group => {
      try {
        const saved = await ask(group);
        if (saved) failures = 0;
        else { failures += 1; if (!summary.reason) summary.reason = '응답 형식'; }
      } catch (error) {
        if (isStaleLifecycleError(error) || (fence && !backgroundFenceIsCurrent(fence))) throw error;
        if (stopNow()) { summary.stopped = true; return; }
        warn('axis korean call failed:', error?.message || error);
        note(error);
        failures += 1;
      }
    };
    for (let index = 0; index < items.length && failures < 2; index += size) {
      if (stopNow()) { summary.stopped = true; break; }
      const group = items.slice(index, index + size);
      onGroup?.(group, index);
      await attempt(group);
      // 여러 명을 보낸 호출에서 못 건진 사람은 한 명씩 다시 보낸다.
      if (group.length > 1) {
        for (const item of group.filter(member => !filled.has(member.id))) {
          if (summary.stopped || failures >= 2) break;
          if (stopNow()) { summary.stopped = true; break; }
          await attempt([item]);
        }
      }
      if (summary.stopped) break;
      if (afterGroup) await afterGroup();
    }
    summary.done = filled.size;
    // 중지면 남은 사람은 실패가 아니라 그대로 남은 것(채우기 단추에 잡힘). 연달아 실패해 멈췄으면 부르지 않은 사람도 실패로 센다.
    summary.failed = summary.stopped ? 0 : items.length - filled.size;
    if (summary.failed && !summary.reason) summary.reason = '응답 형식';
    return summary;
  }

  // 저장된 인물의 한글 채우기(채우기 단추·개별 재분석·축 재채점). ids 가운데 한글이 빠진 축만.
  // 실패·중지는 분석 결과에 영향이 없다(영어는 이미 저장됨). 저장은 24명마다와 끝에 한 번(저장 자료 전체를 다시 쓰므로 자주 하지 않음).
  async function fillAxisKorean({ scope, variantKey, ids, config, requestGuard = null, fence = null }) {
    const store = await loadProfileStore();
    const items = [...new Set(ids || [])].map(id => axisKoreanItem(store.profiles?.[id], variantKey)).filter(Boolean);
    if (!items.length) return { total: 0, done: 0, failed: 0, stopped: false, reason: '' };
    const writeFence = fence || { ...captureBackgroundFence(scope), enforceLifecycleEpoch: true };
    const pending = new Map();
    const flush = async () => {
      if (!pending.size) return;
      const batch = new Map(pending);
      pending.clear();
      await saveAxisKorean(batch, variantKey, writeFence);
    };
    const summary = await axisKoreanRun(items, {
      config, requestGuard, fence: writeFence, size: axisKoreanGroupSize(config),
      onGroup: (group, index) => updateAnalysisRuntime({ detail: `한글 설명 ${index + group.length} / ${items.length} · ${group.map(item => item.name).join(', ')}` }),
      afterGroup: async () => { if (pending.size >= 24) await flush(); },
      onFilled: (item, axes) => pending.set(item.id, Object.fromEntries(Object.entries(axes).map(([axis, ko]) => [axis, { answer: item.axes[axis], ko }]))),
    });
    await flush();
    return summary;
  }

  // 분석 묶음 하나의 1단계 답에 한글을 붙인다(그 자리에서 answerKo를 채우고, 저장은 묶음 저장이 함께 한다).
  // group = 이 묶음의 후보, axisEntries = 1단계 결과(Map 후보 → { skip, fields }).
  async function axisKoreanForBatch(group, axisEntries, config, requestGuard = null, fence = null) {
    const items = [];
    for (const candidate of group || []) {
      const entry = axisEntries?.get?.(candidate);
      const answers = entry && !entry.skip ? entry.fields?.axisAnswers : null;
      if (!isPlainObject(answers)) continue;
      const axes = {};
      for (const axis of AXIS_KOREAN_ALL_KEYS) if (answers[axis]?.answer) axes[axis] = String(answers[axis].answer);
      if (Object.keys(axes).length) items.push({ id: String(candidate.id), name: candidate.name || String(candidate.id), axes, answers });
    }
    return await axisKoreanRun(items, {
      config, requestGuard, fence, size: axisKoreanGroupSize(config),
      onFilled: (item, axes) => { for (const [axis, ko] of Object.entries(axes)) if (isPlainObject(item.answers[axis])) item.answers[axis].answerKo = ko; },
    });
  }


  // 홈 "한글 설명 채우기 N명": 이미 분석된 인물의 영어 답으로 한글만 만든다(재분석 아님).
  

  // 저장 프로필에서 정의학 축(값·보복 세부·답)만 뽑는다. 1단계가 실패했을 때 같은 변형의 기존 값을 이어 쓰는 데 쓴다.


  // 2단계(프로필 작성) 응답에서 축을 걷어 낸다. 축은 1단계만 정한다.


  // 1단계 응답 한 인물분을 저장할 축 필드로 바꾼다. 0~1 소수로만 답했으면(모두 1 이하이고 0과 1 사이 값이 있음) 100을 곱해 읽는다.
  // 1단계 응답 한 인물분을 저장할 축 필드로 바꾼다. 0~1 소수로만 답했으면(모두 1 이하이고 0과 1 사이 값이 있음) 100을 곱해 읽는다.
  // 성적 축(2026-10-22): 같은 인물분의 sexualAxes·sexualMotive도 함께 읽어 필드와 답에 넣는다. complete는 여덟 축 기준 그대로다
  // (성적 축이 빠져도 여덟 축이 다 왔으면 적용하고, 성적 축은 미분석으로 남아 홈 "성적 축 채우기"에 잡힌다).
  function axisScoringEntry(item) {
    if (String(item?.skip || '').trim()) return { skip: true, complete: false, fields: {} };
    const axes = isPlainObject(item?.axes) ? item.axes : {};
    const given = AXIS_KEYS.map(axis => isPlainObject(axes[axis]) ? axes[axis].value : undefined);
    const numbers = given.map(value => typeof value === 'number' ? value : typeof value === 'string' && value.trim() ? Number(value) : NaN);
    const finite = numbers.filter(Number.isFinite);
    const fractional = finite.length > 0 && finite.every(value => value >= 0 && value <= 1) && finite.some(value => value > 0 && value < 1);
    const fields = {}, answers = {};
    AXIS_KEYS.forEach((axis, index) => {
      const entry = axes[axis];
      if (!isPlainObject(entry)) return;
      const value = optionalTrait(fractional && Number.isFinite(numbers[index]) ? numbers[index] * 100 : given[index]);
      if (axis === 'retaliation') {
        fields.retaliation = { ...(value === undefined ? {} : { level: value }), confidence: entry.confidence, triggers: entry.triggers, preferredMethods: entry.preferredMethods, evidence: entry.evidence };
      } else if (value !== undefined) fields[axis] = value;
      answers[axis] = { answer: entry.answer, evidence: entry.evidence, confidence: entry.confidence };
    });
    const sexual = sexualAxisFields(item);
    if (sexual) { Object.assign(fields, sexual.fields); Object.assign(answers, sexual.answers); }
    const axisAnswers = normalizeAxisAnswers(answers);
    if (axisAnswers) fields.axisAnswers = axisAnswers;
    return { skip: false, complete: AXIS_KEYS.every(axis => Number.isFinite(axisValueOf(fields, axis))), fields };
  }

  // 기존 프로필에서 축 필드만 꺼낸다(1단계가 실패한 묶음이 같은 변형의 이전 축을 그대로 둘 때). 성적 축 숫자 셋과 동기 유형도 함께 간다.
  function pickAxisFields(profile) {
    const source = isPlainObject(profile) ? profile : {};
    const fields = {};
    for (const axis of AXIS_SCALAR_KEYS) if (Number.isFinite(source[axis])) fields[axis] = source[axis];
    if (isPlainObject(source.retaliation)) fields.retaliation = safeClone(source.retaliation);
    if (isPlainObject(source.axisAnswers)) fields.axisAnswers = safeClone(source.axisAnswers);
    for (const axis of SEX_AXIS_SCALAR_KEYS) if (Number.isFinite(source[axis])) fields[axis] = source[axis];
    if (isPlainObject(source.sexualMotive)) fields.sexualMotive = safeClone(source.sexualMotive);
    return fields;
  }

  // 2단계(프로필 작성) 응답에서 축을 걷어 낸다. 축은 1단계만 정한다. 성적 축 숫자 셋과 동기 유형도 2단계가 돌려줘도 쓰지 않는다
  // (eroticInterest는 2단계 값을 두되, 1단계가 채점했으면 그 값이 덮는다).
  function withoutAxisFields(eroticProfile) {
    const copy = isPlainObject(eroticProfile) ? { ...eroticProfile } : {};
    for (const key of [...AXIS_KEYS, 'axisAnswers', ...SEX_AXIS_SCALAR_KEYS, 'sexualMotive']) delete copy[key];
    return copy;
  }

  // 2단계 입력에 넣는 1단계 답. TARGET CHARACTERS 앞에 둔다(뒤쪽 자료 발췌가 잘려도 답은 남는다). 성적 축 답과 동기 유형도 함께 넣는다
  // (2단계의 성적 관심도 메모·섹드립·유혹 방식이 1단계 답과 어긋나지 않게).
  function axisAnswersBlock(group, entries) {
    const list = group.map(candidate => {
      const entry = entries?.get(candidate);
      if (!entry || entry.skip) return null;
      const axes = {};
      for (const axis of AXIS_KEYS) {
        const value = axisValueOf(entry.fields, axis), answer = entry.fields.axisAnswers?.[axis]?.answer || '';
        if (Number.isFinite(value) || answer) axes[axis] = { ...(Number.isFinite(value) ? { value } : {}), ...(answer ? { answer } : {}) };
      }
      const sexualAxes = {};
      for (const axis of SEX_AXIS_KEYS) {
        const value = sexAxisValueOf(entry.fields, axis), answer = entry.fields.axisAnswers?.[axis]?.answer || '';
        if (Number.isFinite(value) || answer) sexualAxes[axis] = { ...(Number.isFinite(value) ? { value } : {}), ...(answer ? { answer } : {}) };
      }
      const motive = isPlainObject(entry.fields.sexualMotive) ? { primary: entry.fields.sexualMotive.primary, ...(entry.fields.sexualMotive.secondary ? { secondary: entry.fields.sexualMotive.secondary } : {}) } : null;
      if (!Object.keys(axes).length && !Object.keys(sexualAxes).length && !motive) return null;
      return { id: candidate.id, axes, ...(Object.keys(sexualAxes).length ? { sexualAxes } : {}), ...(motive ? { sexualMotive: motive } : {}) };
    }).filter(Boolean);
    return list.length
      ? `AXIS ANSWERS (from the separate axis pass; already stored; do not return or change these values):\n${JSON.stringify(list)}`
      : 'AXIS ANSWERS: unavailable';
  }

  // 1단계 응답을 후보별로 나눈다. characters 목록이 없으면 단계 실패로 본다.
  // 값이 하나도 없는 인물분(빈 axes)은 채점되지 않은 것으로 보고 넣지 않는다.
  function axisScoringEntries(raw, group) {
    if (!isPlainObject(raw) || !Array.isArray(raw.characters)) {
      throw Object.assign(new Error('축 채점 응답에 characters 목록이 없습니다.'), { code: 'EROSYNC_AXIS_RESULT_INVALID' });
    }
    const items = raw.characters.filter(isPlainObject);
    const entries = new Map();
    for (const candidate of group) {
      const ids = new Set([candidate.id, ...(candidate.candidateIds || [])].map(id => String(id || '').toLowerCase()));
      let item = items.find(value => ids.has(String(value.id || '').toLowerCase()));
      if (!item) {
        const names = new Set([candidate.name, ...(candidate.aliases || [])].map(name => String(name || '').trim().toLowerCase()).filter(Boolean));
        const matches = items.filter(value => names.has(String(value.name || '').trim().toLowerCase()));
        if (matches.length === 1) item = matches[0];
      }
      if (!item) continue;
      const entry = axisScoringEntry(item);
      if (entry.skip || AXIS_KEYS.some(axis => Number.isFinite(axisValueOf(entry.fields, axis)))) entries.set(candidate, entry);
    }
    return entries;
  }

  // 2단계 입력에 넣는 1단계 답. TARGET CHARACTERS 앞에 둔다(뒤쪽 자료 발췌가 잘려도 답은 남는다).


  // 지시문 등록부(2026-10-15): 기본 글. 실제 호출은 덮어쓰기를 적용한 등록부 함수를 거친다.
  

  // 지시문 등록부(2026-10-15): 기본 글. 실제 호출은 덮어쓰기를 적용한 등록부 함수를 거친다.
  

  // 지시문 등록부(2026-10-15): 기본 글. 실제 호출은 덮어쓰기를 적용한 등록부 함수를 거친다.
  


  // 장면 판단 지시문. NSFW판은 0.8.5 지시문에 극단성 규칙·개방성/집착성 재정의·성격 변화 항목만 더한 것이고,
  // SFW판은 같은 뼈대에서 성적 부분을 뺀 것이다. 두 판이 어긋나지 않도록 한 곳에서 만든다. NSFW+ 문단은 켰을 때만 들어간다.
  // 장면 판단 지시문 본문(등록부 조립, 2026-10-15). 실제 호출은 promptDirectorInstruction이 덧말까지 붙여 보낸다.
  

  // 비하인드 지시문: 본문의 {{languageRule}} 자리에 언어 설정에 맞는 한 문장
  function buildBehindSystemPrompt(language) {
    const key = language === 'en' ? 'en' : language === 'auto' ? 'auto' : 'ko';
    return promptSectionText('behind.body', 'common').split('{{languageRule}}').join(promptSectionText(`behind.lang.${key}`, 'common'));
  }

  // 메인 주입 문구: 머리말 + 행동마다 계획 줄 양식(자료 자리는 지금 값 — 행동 인물·대상·모드·세기·스타일·목표·접근·다음 움직임·행동 프로필 요약)
  function composeInjection(decision, registry, profileStore, state, botOverride = null) {
    if (decision.type !== 'ACT' || decision.actions.length === 0) return '';
    const policy = contentPolicyFor(botOverride);
    const lines = [INJECTION_START, promptSectionText('inject.head', 'common')];
    const template = promptSectionText('inject.action', 'common');
    for (let index = 0; index < decision.actions.length; index += 1) {
      const action = decision.actions[index];
      const actor = registry.entities[action.actor];
      const target = action.target === 'user' ? { name: 'user' } : registry.entities[action.target];
      const goalType = action.goal ? normalizeGoalType(action.goal.type) : '';
      const profileSummary = selectedProfileSummary(profileStore.profiles[action.actor], state, action.actor, action.target, action, policy);
      lines.push('');
      lines.push(promptFill(template, {
        index: index + 1,
        actor: actor?.name || action.actor,
        target: target?.name || action.target,
        mode: directorModeName(action.mode, policy),
        // 의도(2026-10-22, 성적 목표 대상 6절): 목표를 향한 한 칸(lead)일 때만 줄이 들어가고, 분위기만(play, 기본)이면 줄이 빠진다(전과 같은 문구). 거절 넘김이 봇 설정 확률에 막힌 턴은 제약 한 줄.
        intent: action.intent === 'lead' ? 'a step toward the goal (leading somewhere, not mood only)' : '',
        constraint: action.refusalOverrideWithheld ? 'This turn the actor does not override the target\'s refusal; it uses ordinary means (persuasion, waiting, a different approach).' : '',
        intensity: action.intensity,
        style: action.style || '',
        goalCategory: ['sexual_intercourse', 'retaliation'].includes(goalType) ? goalType : '',
        goal: action.goal ? action.goal.objective || action.goal.type || '' : '',
        approach: action.goal?.currentApproach || '',
        nextMove: action.goal?.nextMove || '',
        profileBlock: profileSummary ? `Actor behavior profile:\n${profileSummary}` : '',
      }));
    }
    lines.push(INJECTION_END);
    return truncate(lines.join('\n'), MAX_INJECTION_CHARS);
  }

  



  const CHARACTER_TEXT_KEYS = [
    'name', 'description', 'desc', 'personality', 'scenario', 'firstMessage', 'first_message',
    'systemPrompt', 'system_prompt', 'postHistoryInstructions', 'creatorNotes', 'creator_notes',
    'exampleDialogue', 'example_dialogue', 'mes_example', 'note', 'characterNote', 'character_note',
  ];

  function collectSelectedFields(record, label) {
    if (!record || typeof record !== 'object') return '';
    const lines = [];
    for (const key of CHARACTER_TEXT_KEYS) {
      const value = record[key];
      if (typeof value === 'string' && value.trim()) lines.push(`[${label}.${key}]\n${value.trim()}`);
    }
    return lines.join('\n\n');
  }

  function buildCharacterSource(character) {
    const roots = [
      ['character', character],
      ['character.data', character?.data],
      ['character.character', character?.character],
      ['character.customData', character?.customData],
    ];
    const parts = [];
    for (const [label, value] of roots) {
      const text = collectSelectedFields(value, label);
      if (text) parts.push(text);
    }
    if (parts.length === 0 && character) {
      try { parts.push(`[character.fallback]\n${JSON.stringify(character)}`); } catch (_) {}
    }
    return parts.join('\n\n');
  }

  function loreEntryToText(entry, index, contentOverride) {
    if (!entry || typeof entry !== 'object') return '';
    const fields = ['name', 'title', 'comment', 'key', 'keys', 'content', 'text', 'prompt', 'data', 'description'];
    const contentFields = new Set(['content', 'text', 'data', 'prompt', 'description']);
    const hasContentOverride = typeof contentOverride === 'string';
    let overrideWritten = false;
    const lines = [`[Lore Entry ${index + 1}]`];
    for (const field of fields) {
      if (hasContentOverride && contentFields.has(field)) {
        if (!overrideWritten && contentOverride.trim()) {
          lines.push(`${field}: ${contentOverride.trim()}`);
          overrideWritten = true;
        }
        continue;
      }
      const value = entry[field];
      if (typeof value === 'string' && value.trim()) {
        lines.push(`${field}: ${contentFields.has(field) ? value.trim() : truncate(value.trim(), 8000)}`);
      } else if (Array.isArray(value) && value.length > 0) {
        lines.push(`${field}: ${truncate(value.join(', '), 8000)}`);
      } else if (isPlainObject(value)) {
        const nested = collectSelectedFields(value, field);
        if (nested) lines.push(nested);
      }
    }
    return lines.length > 1 ? lines.join('\n') : '';
  }
























  // 조건 안의 CBS 태그를 안쪽부터 푼다(리스가 안쪽 태그를 먼저 풀고 바깥 태그를 보는 것과 같다).
  // 아는 것: `? 계산식`, getvar, getglobalvar, 비교·논리 함수. 모르는 태그가 있으면 null(미해결).
  function cbsResolveInline(text, context, depth = 0) {
    if (depth > 32) return null;
    let output = '', cursor = 0, start;
    const source = String(text);
    while ((start = source.indexOf('{{', cursor)) >= 0) {
      output += source.slice(cursor, start);
      const end = cbsTagEnd(source, start);
      if (end < 0) return null;
      const inner = cbsResolveInline(source.slice(start + 2, end - 2), context, depth + 1);
      if (inner === null) return null;
      let value = null;
      if (inner.startsWith('? ')) value = String(cbsCalcString(inner.slice(2), context));
      else {
        const parts = rosterParser.splitTemplateArgs(inner);
        if (!parts) return null;
        const fn = String(parts.shift() || '').trim().toLowerCase(), args = parts;
        if ((fn === 'getvar' || fn === 'getglobalvar') && args.length === 1) value = fn === 'getvar' ? cbsChatVarValue(args[0].trim(), context) : cbsGlobalChatVarValue(args[0].trim(), context);
        else if (fn === 'not' && args.length === 1) value = args[0].trim() === '1' ? '0' : '1';
        else if (args.length === 2) {
          const [a, b] = args.map(part => part.trim());
          const operations = {
            equal: () => a === b, notequal: () => a !== b, not_equal: () => a !== b,
            greater: () => Number(a) > Number(b), less: () => Number(a) < Number(b),
            greaterequal: () => Number(a) >= Number(b), greater_equal: () => Number(a) >= Number(b),
            lessequal: () => Number(a) <= Number(b), less_equal: () => Number(a) <= Number(b),
            and: () => a === '1' && b === '1', or: () => a === '1' || b === '1',
          };
          if (Object.prototype.hasOwnProperty.call(operations, fn)) value = operations[fn]() ? '1' : '0';
        }
      }
      if (value === null) return null;
      output += value;
      cursor = end;
    }
    return output + source.slice(cursor);
  }

  // `{{#if …}}`·`{{#if_pure …}}` 조건에 계산식이 있을 때: 안쪽부터 풀고 첫 토큰이 1·true이면 참(리스 blockStartMatcher와 같다).
  // 계산식이 없는 조건은 null을 돌려 아래의 기존 방식으로 넘긴다. 채팅 자료를 아예 못 읽은 자리에서는 평가하지 않는다.
  function cbsIfCalcCondition(condition, context) {
    const text = String(condition || '');
    if (!/^\{\{#(?:if_pure|if)\b/i.test(text) || !/\{\{\?\s/.test(text)) return null;
    if (context && context.chatAvailable === false) return null;
    const inner = text.replace(/^\{\{#(?:if_pure|if)\s*/i, '').replace(/\}\}\s*$/, '');
    const resolved = cbsResolveInline(inner, context);
    if (resolved === null) return null;
    const first = resolved.trim().split(/\s+/)[0] || '';
    return first === '1' || first === 'true';
  }

  function evaluateCbsCondition(condition, variableContext) {
    if (/^\{\{#when\b/i.test(condition)) return evaluateWhenCondition(condition, variableContext).value;
    const calc = cbsIfCalcCondition(condition, variableContext);
    if (calc !== null) return calc;
    const matches = [...String(condition || '').matchAll(/\{\{(getglobalvar|getvar)::([^{}]+)\}\}/gi)];
    if (matches.length !== 1) return null;
    const type = matches[0][1].toLowerCase();
    const name = String(matches[0][2] || '').trim();
    const variables = type === 'getglobalvar' ? variableContext?.globalVariables : variableContext?.chatVariables;
    if (!variables || typeof variables !== 'object' || !Object.prototype.hasOwnProperty.call(variables, name)) return null;
    const actual = variables[name];
    let expression = String(condition || '')
      .replace(/^\{\{#(?:if_pure|if)\s*/i, '')
      .replace(/\}\}\s*$/, '')
      .replace(matches[0][0], '__VALUE__')
      .trim();
    if (expression === '__VALUE__') return cbsValueTruthy(actual);
    if (/^!\s*__VALUE__$/.test(expression) || /^not\s+__VALUE__$/i.test(expression)) return !cbsValueTruthy(actual);
    const comparison = expression.match(/^__VALUE__\s*(===|==|!==|!=|>=|<=|>|<)\s*(.+)$/);
    if (!comparison) return null;
    const expected = parseCbsLiteral(comparison[2]);
    const leftNumber = Number(actual);
    const rightNumber = Number(expected);
    const numeric = Number.isFinite(leftNumber) && Number.isFinite(rightNumber) && String(actual).trim() !== '' && String(expected).trim() !== '';
    const left = numeric ? leftNumber : String(actual ?? '');
    const right = numeric ? rightNumber : String(expected ?? '');
    if (comparison[1] === '==' || comparison[1] === '===') return left === right;
    if (comparison[1] === '!=' || comparison[1] === '!==') return left !== right;
    if (comparison[1] === '>=') return left >= right;
    if (comparison[1] === '<=') return left <= right;
    if (comparison[1] === '>') return left > right;
    if (comparison[1] === '<') return left < right;
    return null;
  }



  // Risu #when operators are consumed right-to-left. Unknown reads stay unknown.
  function evaluateWhenCondition(condition, variableContext) {
    let mode = 'normal';
    const truth = value => value === '1' || value === 'true';
    const read = (global, name) => {
      if (name === null || name === undefined) return null;
      const vars = global ? variableContext?.globalVariables : variableContext?.chatVariables;
      if (!vars || typeof vars !== 'object') return null;
      const key = Object.prototype.hasOwnProperty.call(vars, name) ? name
        : !global && Object.prototype.hasOwnProperty.call(vars, `$${name}`) ? `$${name}` : null;
      return key === null || vars[key] === undefined ? null : String(vars[key]);
    };
    const atom = (text, depth = 0) => {
      if (text === undefined || text === null || depth > 32) return null;
      let output = '', cursor = 0, start;
      while ((start = text.indexOf('{{', cursor)) >= 0) {
        output += text.slice(cursor, start);
        const end = cbsTagEnd(text, start);
        if (end < 0) return null;
        const parts = rosterParser.splitTemplateArgs(text.slice(start + 2, end - 2));
        if (!parts) return null;
        const fn = parts.shift().toLowerCase(), args = parts.map(part => atom(part, depth + 1));
        if (args.some(value => value === null)) return null;
        let value = null;
        if ((fn === 'getvar' || fn === 'getglobalvar') && args.length === 1) value = read(fn === 'getglobalvar', args[0]);
        else if (fn === 'not' && args.length === 1) value = args[0] === '1' ? '0' : '1';
        else if (args.length === 2) {
          const [a, b] = args;
          const operations = {
            equal: () => a === b, notequal: () => a !== b, not_equal: () => a !== b,
            greater: () => Number(a) > Number(b), less: () => Number(a) < Number(b),
            greaterequal: () => Number(a) >= Number(b), greater_equal: () => Number(a) >= Number(b),
            lessequal: () => Number(a) <= Number(b), less_equal: () => Number(a) <= Number(b),
            and: () => a === '1' && b === '1', or: () => a === '1' || b === '1',
          };
          if (Object.prototype.hasOwnProperty.call(operations, fn)) value = operations[fn]() ? '1' : '0';
        }
        if (value === null) return null;
        output += value; cursor = end;
      }
      return output + text.slice(cursor);
    };
    const inner = condition.slice(2, -2);
    if (/^#when\s/i.test(inner)) {
      const value = atom(inner.replace(/^#when\s+/i, '').trim());
      return { value: value === null ? null : truth(value), mode };
    }
    const rawParts = rosterParser.splitTemplateArgs(inner);
    if (!rawParts || !/^#when$/i.test(rawParts.shift())) return { value: null, mode };
    const stack = rawParts.map(part => atom(part));
    while (stack.length > 1) {
      const right = stack.pop(), operator = stack.pop();
      if (operator === 'keep' || operator === 'legacy') { mode = operator; stack.push(right); continue; }
      if (right === null || operator === null) return { value: null, mode };
      let value;
      if (operator === 'not') value = !truth(right);
      else if (operator === 'var' || operator === 'toggle') {
        const found = read(operator === 'toggle', operator === 'toggle' ? `toggle_${right}` : right);
        if (found === null) return { value: null, mode };
        value = truth(found);
      } else {
        let left = stack.pop();
        if (left === null || left === undefined) return { value: null, mode };
        if (['vis', 'visnot', 'tis', 'tisnot'].includes(operator)) {
          const global = operator.startsWith('t');
          left = read(global, global ? `toggle_${left}` : left);
          if (left === null) return { value: null, mode };
          value = operator.endsWith('not') ? left !== right : left === right;
        } else if (operator === 'and') value = truth(left) && truth(right);
        else if (operator === 'or') value = truth(left) || truth(right);
        else if (operator === 'is') value = left === right;
        else if (operator === 'isnot') value = left !== right;
        else if (operator === '>') value = parseFloat(left) > parseFloat(right);
        else if (operator === '<') value = parseFloat(left) < parseFloat(right);
        else if (operator === '>=') value = parseFloat(left) >= parseFloat(right);
        else if (operator === '<=') value = parseFloat(left) <= parseFloat(right);
        else return { value: null, mode };
      }
      stack.push(value ? '1' : '0');
    }
    return { value: stack.length === 1 && stack[0] !== null ? truth(stack[0]) : null, mode };
  }



  function findCbsConditionalClose(source, openEnd, openStart = null) {
    if (openStart === null) {
      const openings = /\{\{#(?:if_pure|if|when)\b/gi;
      let match;
      while ((match = openings.exec(source)) && match.index < openEnd) {
        if (cbsTagEnd(source, match.index) === openEnd) { openStart = match.index; break; }
      }
    }
    return openStart === null ? null : rosterParser.conditionalBoundary(source, openStart);
  }

  function prepareConditionalLoreContent(rawContent, variableContext, options = {}) {
    const raw = String(rawContent || '');
    const diagnostics = {
      mode: 'none',
      globalToggleNames: [],
      excludedGlobalBlocks: 0,
      preservedGetvarBlocks: 0,
      evaluatedBlocks: 0,
      unresolvedBlocks: 0,
    };
    const toggleNames = new Set();
    const process = (source, depth = 0) => {
      if (depth > 128) { diagnostics.unresolvedBlocks += 1; return source; }
      const out = [], openings = /\{\{#(?:if_pure|if|when)\b/gi;
      let cursor = 0, match;
      while ((match = openings.exec(source))) {
      const openStart = match.index;
      out.push(source.slice(cursor, openStart));
      const openEnd = cbsTagEnd(source, openStart);
      const boundary = openEnd < 0 ? null : findCbsConditionalClose(source, openEnd, openStart);
      if (!boundary) { diagnostics.unresolvedBlocks += 1; out.push(match[0]); cursor = openings.lastIndex; continue; }
      const condition = source.slice(openStart, openEnd);
      const { globalNames, hasGlobal, hasChat } = rosterParser.conditionalReferences(condition);
      globalNames.forEach((name) => toggleNames.add(name));
      const when = boundary.kind === 'when' ? evaluateWhenCondition(condition, variableContext) : null;
      if (when && boundary.elseStart >= 0) {
        const multiline = source.slice(openEnd, boundary.closeStart).includes('\n');
        const lineStart = Math.max(openEnd, source.lastIndexOf('\n', boundary.elseStart - 1) + 1);
        const nextLine = source.indexOf('\n', boundary.elseEnd);
        const lineEnd = nextLine < 0 ? boundary.closeStart : Math.min(nextLine, boundary.closeStart);
        if (when.mode === 'legacy' || (multiline && source.slice(lineStart, lineEnd).trim() !== '{{:else}}')) {
          boundary.elseStart = -1; boundary.elseEnd = -1;
        }
      }
      const thenText = source.slice(openEnd, boundary.elseStart >= 0 ? boundary.elseStart : boundary.closeStart);
      const elseText = boundary.elseStart >= 0 ? source.slice(boundary.elseEnd, boundary.closeStart) : '';
      const evaluated = when ? when.value : evaluateCbsCondition(condition, variableContext);
      let selected;
      if (evaluated !== null) {
        diagnostics.evaluatedBlocks += 1;
        selected = evaluated ? thenText : elseText;
      } else if (hasGlobal) {
        diagnostics.unresolvedBlocks += 1;
        if (options.includeGlobalToggles === true) selected = thenText;
        else {
          diagnostics.excludedGlobalBlocks += 1;
          selected = elseText;
        }
      } else {
        diagnostics.unresolvedBlocks += 1;
        if (hasChat) diagnostics.preservedGetvarBlocks += 1;
        selected = boundary.elseStart >= 0 ? `${thenText}\n${elseText}` : thenText;
      }
      out.push(process(selected, depth + 1));
      cursor = openings.lastIndex = boundary.closeEnd;
      }
      out.push(source.slice(cursor));
      return out.join('');
    };
    const profileRaw = process(raw);
    diagnostics.globalToggleNames = [...toggleNames].sort();
    diagnostics.mode = diagnostics.evaluatedBlocks > 0 && diagnostics.unresolvedBlocks === 0
      ? 'evaluated'
      : diagnostics.unresolvedBlocks > 0 ? 'fallback' : 'none';
    return {
      rawContent: raw,
      content: stripCbsTemplateTags(raw),
      profileContent: stripCbsTemplateTags(profileRaw),
      diagnostics,
    };
  }










  function analysisSourcesEquivalent(bundle, inventory) {
    if (inventory?.analysisWorkflow === 'selected_lore' && bundle?.selectedLoreScope?.selectedEntries?.length) {
      // A selected source that only changed position is the same analysis input.
      const rows = selectedLoreRows(bundle.selectedLoreScope, inventory);
      return rows.length > 0 && rows.every(row => row.available && !!row.savedHash && row.savedHash === row.hash);
    }
    if (!bundle?.sourceDocuments?.length || inventory.partial || (inventory.warnings || []).some(w => /읽기 실패|API를 사용할 수 없습니다/.test(w))) return false;
    const before = analysisSourceRows(bundle.sourceDocuments), after = analysisSourceRows(inventory.documents);
    if (before.length && after.length && before.every(row => row.semanticHash) && after.every(row => row.semanticHash)) {
      const key = row => JSON.stringify([row.semanticLabel, row.semanticHash]);
      const previous = new Set(before.map(key)), current = new Set(after.map(key));
      return previous.size === current.size && [...previous].every(value => current.has(value));
    }
    return before.length > 0 && after.length > 0 && before.every(a => after.some(b => sameAnalysisDocument(a, b)))
      && after.every(b => before.some(a => sameAnalysisDocument(a, b)));
  }

  function sourceChangeSummary(bundle, inventory) {
    if (inventory?.analysisWorkflow === 'selected_lore' && bundle?.selectedLoreScope?.selectedEntries?.length) {
      return selectedLoreRows(bundle.selectedLoreScope, inventory).filter(row => !row.available || !row.savedHash || row.savedHash !== row.hash)
        .map(row => row.title).slice(0, 40);
    }
    const before = analysisSourceRows(bundle?.sourceDocuments), after = analysisSourceRows(inventory.documents);
    if (before.every(row => row.semanticHash) && after.every(row => row.semanticHash)) {
      const key = row => JSON.stringify([row.semanticLabel, row.semanticHash]);
      const previous = new Set(before.map(key)), current = new Set(after.map(key));
      return [...new Set([...after.filter(row => !previous.has(key(row))).map(row => row.label),
        ...before.filter(row => !current.has(key(row))).map(row => row.label)])].filter(Boolean).slice(0, 40);
    }
    return [...new Set([...after.filter(b => !before.some(a => sameAnalysisDocument(a, b))).map(b => b.label),
      ...before.filter(a => !after.some(b => sameAnalysisDocument(a, b))).map(a => a.label)])].filter(Boolean).slice(0, 40);
  }

  async function collectSourceInventory(character, scope, options = {}) {
    if (options.force === true && typeof invalidateUiInventory === 'function') invalidateUiInventory(scope?.sourceBundleKey || '');
    const requestGuard = options.requestGuard || null;
    requestGuard?.throwIfAborted('source inventory');
    const documents = [];
    const seen = new Map();
    const rosterEntries = [];
    const rosterSeen = new Map();
    const buildState = {
      totalChars: 0,
      duplicates: 0,
      partial: false,
      deferredDocuments: 0,
      deferredChars: 0,
      limitReason: '',
      maxSourceChars: clampInt(options.maxSourceChars, 0, 0, 100000000),
    };
    const warnings = [];
    const excludedExternalSources = [];
    const conditionalDiagnostics = {
      entriesWithConditions: 0,
      evaluatedBlocks: 0,
      excludedGlobalBlocks: 0,
      preservedGetvarBlocks: 0,
      unresolvedBlocks: 0,
      globalToggleNames: [],
      globalVariableCount: 0,
      chatVariableCount: 0,
      includeGlobalToggles: false,
    };
    const conditionalToggleNames = new Set();
    const recordConditionalDiagnostics = (prepared) => {
      const diagnostic = prepared?.diagnostics;
      if (!diagnostic || diagnostic.mode === 'none') return;
      conditionalDiagnostics.entriesWithConditions += 1;
      conditionalDiagnostics.evaluatedBlocks += diagnostic.evaluatedBlocks || 0;
      conditionalDiagnostics.excludedGlobalBlocks += diagnostic.excludedGlobalBlocks || 0;
      conditionalDiagnostics.preservedGetvarBlocks += diagnostic.preservedGetvarBlocks || 0;
      conditionalDiagnostics.unresolvedBlocks += diagnostic.unresolvedBlocks || 0;
      for (const name of diagnostic.globalToggleNames || []) conditionalToggleNames.add(name);
    };
    const blockedModuleTexts = new Set();
    const blockModuleText = (value) => {
      const normalized = normalizedModuleText(value);
      if (normalized) blockedModuleTexts.add(normalized);
    };
    const add = (value) => addSourceDocument(documents, seen, buildState, value);
    const addRoster = (value) => addRosterSourceEntry(rosterEntries, rosterSeen, value);
    const identity = scope?.identity || characterIdentity(character);
    const cardSource = buildCharacterSource(character);
    if (cardSource) add({ kind: 'character_card', label: `${identity.name} 캐릭터 카드`, originId: identity.id, text: cardSource });

    const chat = scope?.chat || null;
    let variableContext = buildConditionalVariableContext(null, character, chat);
    let includeGlobalToggles = false;
    const addLoreCollection = (collection, kind, labelPrefix) => {
      const entries = asObjectArray(collection);
      for (let index = 0; index < entries.length; index += 1) {
        if (index % 25 === 0) requestGuard?.throwIfAborted('source inventory');
        const entry = entries[index];
        if (isLoreDisabled(entry)) continue;
        const content = loreContent(entry);
        if (!content) continue;
        const rawRendered = loreEntryToText(entry, index);
        if (kind === 'aggregate_lore' && (blockedModuleTexts.has(normalizedModuleText(content)) || blockedModuleTexts.has(normalizedModuleText(rawRendered)))) continue;
        const externalSource = externalLoreSource(entry, content);
        if (externalSource) {
          excludedExternalSources.push({ kind, originId: String(entry.id || entry._id || entry.uid || `${labelPrefix}_${index + 1}`), label: sourceDocumentLabel(entry, `${labelPrefix} ${index + 1}`), source: externalSource });
          blockModuleText(content);
          blockModuleText(rawRendered);
          continue;
        }
        const prepared = prepareConditionalLoreContent(content, variableContext, { includeGlobalToggles });
        if (!rosterSeen.has(fnv1a(prepared.rawContent))) recordConditionalDiagnostics(prepared);
        const label = sourceDocumentLabel(entry, `${labelPrefix} ${index + 1}`);
        const originId = String(entry.id || entry._id || entry.uid || `${labelPrefix}_${index + 1}`);
        addRoster({ entry, prepared, kind, label, originId });
        if (!prepared.profileContent) continue;
        const rendered = loreEntryToText(entry, index, prepared.profileContent);
        add({
          kind,
          label,
          originId,
          text: rendered,
        });
      }
    };

    let db = null;
    let variableDb = null;
    if (typeof R.getDatabase === 'function') {
      try {
        const dbPromise = R.getDatabase(['modules', 'enabledModules', 'moduleIntergration', 'moduleIntegration', 'personas', 'selectedPersona']);
        db = requestGuard ? await requestGuard.wait(dbPromise, 'active module inventory') : await dbPromise;
      } catch (error) {
        requestGuard?.throwIfAborted('active module inventory');
        warnings.push(`활성 모듈 목록 읽기 실패: ${error?.message || error}`);
      }
    } else {
      warnings.push('이 RisuAI 환경에서는 활성 모듈 데이터베이스 API를 사용할 수 없습니다.');
    }
    if (typeof R.getDatabase === 'function') {
      try {
        const variablePromise = R.getDatabase(['globalChatVariables', 'globalVariables', 'globalVars', 'variables', 'scriptstate', 'templateDefaultVariables']);
        variableDb = requestGuard ? await requestGuard.wait(variablePromise, 'conditional variable inventory') : await variablePromise;
      } catch (error) {
        requestGuard?.throwIfAborted('conditional variable inventory');
      }
    }
    const personas = Array.isArray(db?.personas) ? db.personas : [];
    const selectedPersonaValue = db?.selectedPersona;
    const personaIndex = Number.isInteger(Number(selectedPersonaValue))
      ? Number(selectedPersonaValue)
      : personas.findIndex((item) => String(item?.id || '') === String(selectedPersonaValue || ''));
    const persona = personas[personaIndex >= 0 ? personaIndex : 0] || null;
    const activeModules = activeModuleList(db || {}, character, chat, persona);
    const botOverridePromise = options.botOverride ? Promise.resolve(options.botOverride) : getBotOverride(scope?.sourceBundleKey || safeKeyPart(identity.id, safeKeyPart(identity.name, 'character')));
    const botOverride = requestGuard ? await requestGuard.wait(botOverridePromise, 'module analysis selection') : await botOverridePromise;
    includeGlobalToggles = botOverride?.rosterDiscovery?.includeGlobalToggles === true;
    variableContext = buildConditionalVariableContext(variableDb, character, chat);
    conditionalDiagnostics.globalVariableCount = Object.keys(variableContext.globalVariables).length;
    conditionalDiagnostics.chatVariableCount = Object.keys(variableContext.chatVariables).length;
    conditionalDiagnostics.includeGlobalToggles = includeGlobalToggles;
    for (const source of [character?.globalLore, character?.lorebook, character?.loreBook, character?.data?.globalLore, character?.data?.lorebook]) {
      addLoreCollection(source, 'character_lore', '캐릭터 로어');
    }
    for (const source of [chat?.localLore, chat?.globalLore, chat?.lore, chat?.lorebook, chat?.data?.localLore]) {
      addLoreCollection(source, 'chat_lore', '채팅 로어');
    }
    const moduleSelection = resolveModuleAnalysisSelection(activeModules, botOverride?.analysisModules || {});
    warnings.push(...moduleSelection.warnings);
    if (moduleSelection.unresolvedExclusions.length > 0) warnings.push(`저장된 모듈 제외 ${moduleSelection.unresolvedExclusions.length}개는 현재 활성 모듈과 일치하지 않아 적용하지 않았습니다.`);
    const includedStableKeys = new Set(moduleSelection.included.map((descriptor) => descriptor.stableKey));
    const moduleDiagnostics = [];
    for (const descriptor of activeModules) {
      requestGuard?.throwIfAborted('source inventory');
      const module = descriptor.module;
      const includedForAnalysis = includedStableKeys.has(descriptor.stableKey);
      const diagnostic = { key: descriptor.key, stableKey: descriptor.stableKey, name: descriptor.name, embedded: descriptor.embedded, includedForAnalysis, selectable: descriptor.selectable, collision: descriptor.collision, rawEntries: 0, acceptedEntries: 0, analysisExcludedEntries: 0, externalExcludedEntries: 0, conditionalExcludedEntries: 0, excludedEntries: 0, emptyEntries: 0, duplicateEntries: 0, chars: 0 };
      const descriptionParts = [module?.description, module?.backgroundEmbedding, module?.prompt, module?.data?.description]
        .filter((item) => typeof item === 'string' && item.trim());
      const description = descriptionParts.join('\n\n');
      if (description) {
        if (includedForAnalysis) {
          const externalSource = externalLoreSource({ name: descriptor.name }, description);
          if (externalSource) {
            excludedExternalSources.push({ kind: 'module_description', originId: descriptor.key, label: `${descriptor.name} 모듈 설명`, source: externalSource });
            blockModuleText(description);
            descriptionParts.forEach(blockModuleText);
          } else {
            const prepared = prepareConditionalLoreContent(description, variableContext, { includeGlobalToggles });
            recordConditionalDiagnostics(prepared);
            if (prepared.profileContent) add({ kind: 'module_description', label: `${descriptor.name} 모듈 설명`, originId: descriptor.key, moduleName: descriptor.name, text: prepared.profileContent });
          }
        }
        else {
          blockModuleText(description);
          descriptionParts.forEach(blockModuleText);
        }
      }
      const collections = moduleLoreCollections(module);
      for (let sourceIndex = 0; sourceIndex < collections.length; sourceIndex += 1) {
        const entries = asObjectArray(collections[sourceIndex]);
        for (let index = 0; index < entries.length; index += 1) {
          if (index % 25 === 0) requestGuard?.throwIfAborted('source inventory');
          const entry = entries[index];
          diagnostic.rawEntries += 1;
          if (isLoreDisabled(entry)) { diagnostic.excludedEntries += 1; continue; }
          const content = loreContent(entry);
          if (!content) { diagnostic.emptyEntries += 1; continue; }
          const rawRendered = loreEntryToText(entry, index);
          if (!includedForAnalysis) {
            blockModuleText(content);
            blockModuleText(rawRendered);
            diagnostic.analysisExcludedEntries += 1;
            diagnostic.chars += rawRendered.length;
            continue;
          }
          const externalSource = externalLoreSource(entry, content);
          if (externalSource) {
            excludedExternalSources.push({ kind: 'module_lore', originId: `${descriptor.key}_${sourceIndex}_${entry.id || entry._id || index}`, label: sourceDocumentLabel(entry, `${descriptor.name} 로어 ${index + 1}`), source: externalSource });
            blockModuleText(content);
            blockModuleText(rawRendered);
            diagnostic.externalExcludedEntries += 1;
            continue;
          }
          const prepared = prepareConditionalLoreContent(content, variableContext, { includeGlobalToggles });
          if (!rosterSeen.has(fnv1a(prepared.rawContent))) recordConditionalDiagnostics(prepared);
          const label = sourceDocumentLabel(entry, `${descriptor.name} 로어 ${index + 1}`);
          const originId = `${descriptor.key}_${sourceIndex}_${entry.id || entry._id || index}`;
          addRoster({ entry, prepared, kind: 'module_lore', label, originId, moduleName: descriptor.name });
          if (!prepared.profileContent) {
            diagnostic.conditionalExcludedEntries += 1;
            continue;
          }
          const rendered = loreEntryToText(entry, index, prepared.profileContent);
          const beforeCount = documents.length;
          const beforeDuplicates = buildState.duplicates;
          add({
            kind: 'module_lore',
            label,
            originId,
            moduleName: descriptor.name,
            text: rendered,
          });
          if (documents.length > beforeCount) {
            diagnostic.acceptedEntries += 1;
            diagnostic.chars += documents[documents.length - 1]?.chars || 0;
          } else if (buildState.duplicates > beforeDuplicates) diagnostic.duplicateEntries += 1;
        }
      }
      moduleDiagnostics.push(diagnostic);
    }

    // The host aggregate contains character, chat, and active-module lore without
    // provenance. Direct sources above must win; this pass only fills gaps and
    // merges an aggregate source reference into already-seen documents.
    try {
      const entriesPromise = getLoreEntries();
      const currentEntries = requestGuard ? await requestGuard.wait(entriesPromise, 'current lore inventory') : await entriesPromise;
      addLoreCollection(currentEntries, 'aggregate_lore', 'RisuAI 통합 로어');
    } catch (error) {
      requestGuard?.throwIfAborted('current lore inventory');
      warnings.push(`현재 로어북 읽기 실패: ${error?.message || error}`);
    }

    const counts = {};
    for (let index = 0; index < documents.length; index += 1) {
      if (index % 100 === 0) requestGuard?.throwIfAborted('source inventory');
      const document = documents[index];
      for (const kind of document.sourceKinds || [document.kind]) counts[kind] = (counts[kind] || 0) + 1;
    }
    requestGuard?.throwIfAborted('source inventory');
    if (buildState.partial) warnings.push(`사용자가 설정한 분석 한도에 도달해 ${buildState.deferredDocuments.toLocaleString()}개 자료(${buildState.deferredChars.toLocaleString()}자)가 이번 분석에서 보류되었습니다. 한도를 늘리거나 전체 분석으로 다시 실행할 수 있습니다.`);
    conditionalDiagnostics.globalToggleNames = [...conditionalToggleNames].sort();
    if (conditionalDiagnostics.excludedGlobalBlocks > 0) warnings.push(`설정 토글 자료 ${conditionalDiagnostics.excludedGlobalBlocks.toLocaleString()}개를 분석에서 제외했습니다.`);
    const activationTokens = documents
      .filter((document) => !['character_card', 'aggregate_lore'].includes(document.kind))
      .map((document) => `${document.kind}:${document.moduleName || ''}:${document.originId || document.label || ''}`)
      .sort();
    const activationSignature = activationTokens.join('|');
    const variantKey = activationTokens.length > 0 ? `variant_${fnv1a(activationSignature)}` : 'default';
    const variantLabel = moduleSelection.included.length > 0
      ? moduleSelection.included.map((item) => item.name).filter(Boolean).join(' + ')
      : activationTokens.length > 0 ? '로어 설정' : '기본 설정';
    const sourceHash = fnv1a(documents.map((document) => `${(document.sourceKinds || [document.kind]).join(',')}:${document.originId}:${document.hash}`).join('\n'));
    for (const document of documents) {
      document.semanticHash = fnv1a(analysisSourceText(document.text));
      document.analysisRelevant = analysisSourceRelevant(document);
    }
    requestGuard?.throwIfAborted('source inventory');
    const inventory = {
      schemaVersion: SOURCE_INVENTORY_SCHEMA,
      sourceBundleKey: scope?.sourceBundleKey || safeKeyPart(identity.id, safeKeyPart(identity.name, 'character')),
      identity,
      sourceHash,
      transportSourceHash: sourceHash,
      semanticSourceHash: `content_v2_${fnv1a([...new Set(analysisSourceRows(documents).map(d => `${d.semanticLabel}:${d.semanticHash}`))].sort().join('\n'))}`,
      analysisFamily: analysisFamilySignature(documents),
      variantKey,
      variantLabel,
      activationSignature,
      activationTokens,
      documents,
      rosterEntries,
      analysisWorkflow: analysisWorkflow({ botOverride }),
      variableContext,
      counts,
      totalChars: buildState.totalChars,
      activeModules: activeModules.map((item) => ({
        key: item.key,
        legacyKey: item.legacyKey,
        stableKey: item.stableKey,
        name: item.name,
        embedded: item.embedded,
        selectable: item.selectable !== false,
        collision: item.collision === true,
        identityKind: item.identityKind,
        identityValue: item.identityValue,
        ownerKind: item.ownerKind,
        ownerId: item.ownerId,
        contentFingerprint: item.contentFingerprint,
      })),
      analysisModules: moduleSelection.included.map((item) => ({ key: item.key, stableKey: item.stableKey, name: item.name, embedded: item.embedded })),
      excludedModules: moduleSelection.excluded.map((item) => ({ key: item.key, stableKey: item.stableKey, name: item.name, embedded: item.embedded })),
      unresolvedModuleExclusions: moduleSelection.unresolvedExclusions,
      moduleSelectionRevision: clampInt(botOverride?.analysisModules?.revision, 0, 0, 1000000000),
      moduleDiagnostics,
      conditionalDiagnostics,
      excludedExternalSources,
      duplicateDocuments: buildState.duplicates,
      partial: buildState.partial,
      deferredDocuments: buildState.deferredDocuments,
      deferredChars: buildState.deferredChars,
      limitReason: buildState.limitReason,
      warnings,
      collectedAt: new Date().toISOString(),
    };
    requestGuard?.throwIfAborted('source inventory');
    return inventory;
  }





  async function readScopeUserIdentity(chat, characterIndex, chatIndex) {
    if (typeof R.getDatabase !== 'function') return null;
    let db;
    try { db = await R.getDatabase(['personas', 'selectedPersona', 'username']); } catch (_) { return null; }
    const personas = Array.isArray(db?.personas) ? db.personas : [];
    const boundId = String(chat?.bindedPersona || '');
    const bound = boundId ? personas.find(persona => String(persona?.id || '') === boundId) : null;
    let persona = bound, name = String(bound?.name || ''), source = bound ? 'chat_bound_persona' : '';
    if (boundId && !bound) return null;
    if (!bound) {
      const selected = db?.selectedPersona;
      persona = personas.find(item => String(item?.id || '') === String(selected))
        || (Number.isInteger(Number(selected)) ? personas[Number(selected)] : null);
      name = typeof db?.username === 'string' ? db.username : '';
      // Risu's effective {{user}} can differ from an unsaved persona name.
      if (typeof R.parseRisuChat === 'function') {
        try {
          const before = await Promise.all([R.getCurrentCharacterIndex(), R.getCurrentChatIndex()]);
          if (before[0] === characterIndex && before[1] === chatIndex) {
            const parsed = await R.parseRisuChat('{{user}}', { runVar: false, processRegex: false });
            const after = await Promise.all([R.getCurrentCharacterIndex(), R.getCurrentChatIndex()]);
            if (after[0] === characterIndex && after[1] === chatIndex && typeof parsed === 'string' && !parsed.includes('{{')) name = parsed;
          }
        } catch (_) { /* Older hosts expose only persona metadata. */ }
      }
      name ||= String(persona?.name || '');
      source = 'active_user';
    }
    const explicitNames = [];
    for (const line of String(persona?.personaPrompt || '').split('\n')) {
      const match = line.match(/^\s*(?:#{1,4}\s*|[-*]\s*)?(?:name|full\s*name|이름|성명|닉네임|alias(?:es)?)\s*[:：]\s*([^\n;]{1,180})\s*$/i);
      if (match) explicitNames.push(...identityMatcher.tokens(match[1]));
    }
    return normalizeUserIdentity({ personaId: boundId || String(persona?.id || ''), name, source,
      aliases: [...identityMatcher.tokens(name), ...normalizeStringList(persona?.aliases, 20, 180), ...explicitNames] });
  }

  async function scopeUserIdentityCurrent(scope) {
    if (!scope?.userIdentity?.signature) return true;
    try {
      const chat = await R.getChatFromIndex(scope.characterIndex, scope.chatIndex);
      if (String(chat?.id || chat?.chatId || '') !== String(scope.chatId || scope.chat?.id || '')) return false;
      const current = await readScopeUserIdentity(chat, scope.characterIndex, scope.chatIndex);
      return current?.signature === scope.userIdentity.signature;
    } catch (_) { return false; }
  }

  async function resolveScope(character, knownIndices = null) {
    let characterIndex = knownIndices?.characterIndex ?? -1;
    let chatIndex = knownIndices?.chatIndex ?? -1;
    let chat = knownIndices?.chat ?? null;
    try {
      if (characterIndex < 0) characterIndex = await R.getCurrentCharacterIndex();
      if (chatIndex < 0) chatIndex = await R.getCurrentChatIndex();
      if (!chat) chat = await R.getChatFromIndex(characterIndex, chatIndex);
    } catch (error) {
      throw scopeUnavailableError('현재 RisuAI 채팅 좌표 또는 채팅 정보를 읽을 수 없습니다.', error);
    }
    if (!Number.isInteger(characterIndex) || characterIndex < 0 || !Number.isInteger(chatIndex) || chatIndex < 0) {
      throw scopeUnavailableError('현재 RisuAI 채팅 좌표가 유효하지 않습니다.');
    }
    if (!isPlainObject(chat)) throw scopeUnavailableError('현재 RisuAI 채팅 스냅샷을 찾을 수 없습니다.');
    const snapshotCharacterIndex = Number(chat.characterIndex ?? chat.character_index);
    const snapshotChatIndex = Number(chat.chatIndex ?? chat.chat_index);
    if ((Number.isInteger(snapshotCharacterIndex) && snapshotCharacterIndex >= 0 && snapshotCharacterIndex !== characterIndex)
      || (Number.isInteger(snapshotChatIndex) && snapshotChatIndex >= 0 && snapshotChatIndex !== chatIndex)) {
      throw scopeUnavailableError('현재 RisuAI 좌표와 채팅 스냅샷이 일치하지 않습니다.');
    }
    const identity = characterIdentity(character);
    const chatId = chat?.id ?? chat?.chatId ?? chat?.name ?? chatIndex;
    const chatName = String(chat?.name ?? chat?.title ?? `채팅 ${chatIndex >= 0 ? chatIndex + 1 : ''}`).trim() || `채팅 ${chatIndex >= 0 ? chatIndex + 1 : ''}`;
    const characterPart = safeKeyPart(identity.id, safeKeyPart(identity.name, 'character'));
    const chatPart = safeKeyPart(chatId, String(chatIndex >= 0 ? chatIndex : 'chat'));
    const userIdentity = await readScopeUserIdentity(chat, characterIndex, chatIndex);
    return {
      identity,
      characterIndex,
      chatIndex,
      chat,
      chatId: String(chatId ?? chatIndex),
      chatName,
      sourceBundleKey: characterPart,
      scopeKey: `${characterPart}:${chatPart}`,
      ...(userIdentity ? { userIdentity } : {}),
    };
  }








  function resolveAnalyzedTargetGenderPreference(value, previousBase = null) {
    const source = isPlainObject(value) ? { ...value } : {};
    const fields = ['malePercent', 'femalePercent', 'genderlessPercent'];
    const present = fields.filter(field => isPreferenceNumber(source[field]));
    if (present.length === 2 && Math.abs(present.reduce((sum, field) => sum + Number(source[field]), 0) - 100) < 0.01) {
      const missing = fields.find(field => !present.includes(field));
      if (source[missing] == null) source[missing] = 0;
    }
    const completeNumbers = fields.every((field) => isPreferenceNumber(source[field]));
    const total = completeNumbers ? fields.reduce((sum, field) => sum + Number(source[field]), 0) : 0;
    const normalized = normalizeTargetGenderPreference(source, normalizeGenderIdentity('unknown'));
    const ready = completeNumbers && Math.abs(total - 100) < 0.01 && source.status !== 'unknown' && source.status !== 'incomplete';
    if (ready) return { ...normalized, basis: source.basis === 'explicit' && normalized.evidence.length ? 'explicit' : 'inferred',
      notes: normalized.notes || '분석 모델이 반환한 추정 비율입니다. 상세 추정 근거는 반환되지 않았습니다.',
      status: 'ready', needsReanalysis: false, migratedFromLegacy: false, lastAnalysisStatus: 'ready', lastAnalysisNote: '' };
    const status = source.status === 'unknown' && total === 0 ? 'unknown' : 'incomplete';
    const note = truncate(source.notes || '분석 모델이 유효한 선호 비율을 반환하지 않아 이번 선호 분석을 완료하지 못했습니다.', 500);
    const previous = previousBase ? normalizeEroticProfile(previousBase).targetGenderPreference : null;
    if (previous && previous.malePercent + previous.femalePercent + previous.genderlessPercent > 0) {
      return { ...previous, lastAnalysisStatus: status, lastAnalysisNote: `이번 선호 분석 미완료로 기존 저장값을 보존했습니다. ${note}`.slice(0, 500) };
    }
    return { ...normalized, malePercent: 0, femalePercent: 0, genderlessPercent: 0,
      status, confidence: 0, lastAnalysisStatus: status, lastAnalysisNote: note };
  }






  function preferenceItemState(profile, state, item) {
    const data = preferenceStateForRead(state), actor = profile.id;
    const key = value => String(value || '').normalize('NFKC').trim().toLowerCase();
    const matches = value => value?.id === item.id || key(value?.label) === key(item.label);
    const base = normalizePositionPreferences(applyProfileOverrides(profile.baseProfile, profile.userOverrides).positionPreferences).find(matches);
    const applied = [...data.settled, ...data.entries.filter(entry => !entry.reverted)].filter(entry => entry.actor === actor && matches(entry.item))
      .sort((a, b) => a.order - b.order).at(-1);
    return { item: applied?.item || base || null, order: applied?.order || 0 };
  }

  function effectivePositionPreferences(profile, state) {
    if (!profile || isNonActingMainProfile(profile)) return [];
    const data = preferenceStateForRead(state), byId = new Map();
    for (const entry of normalizePositionPreferences(applyProfileOverrides(profile.baseProfile, profile.userOverrides).positionPreferences)) byId.set(entry.id, entry);
    for (const entry of [...data.settled, ...data.entries.filter(entry => !entry.reverted)].filter(entry => entry.actor === profile.id).sort((a, b) => a.order - b.order)) {
      const sameLabel = [...byId.values()].find(item => item.label.normalize('NFKC').toLowerCase() === entry.item.label.normalize('NFKC').toLowerCase());
      if (sameLabel) byId.delete(sameLabel.id);
      byId.delete(entry.item.id); byId.set(entry.item.id, entry.item);
    }
    return [...byId.values()].slice(-16);
  }


  function applyPreferenceCandidate(state, profileStore, candidateId, method = 'auto') {
    const data = state.preferenceState, candidate = data?.candidates?.find(item => item.id === candidateId);
    const profile = profileStore?.profiles?.[candidate?.actor];
    if (!candidate || !profile || !candidate.evidence.length || ['applied', 'rejected'].includes(candidate.status) || isNonActingMainProfile(profile)) return false;
    const current = preferenceItemState(profile, state, candidate.item);
    if (current.order !== candidate.predecessor || (current.item?.preference || '') !== candidate.previousPreference) return false;
    compactPreferenceHistory(state);
    if (data.entries.length >= 1024) return false;
    const order = ++data.sequence;
    const entry = { id: `pref_applied_${order}_${fnv1a(candidate.id)}`, actor: candidate.actor, item: { ...safeClone(candidate.item), basis: 'observed' }, previousPreference: candidate.previousPreference,
      evidenceIds: candidate.evidence.map(e => e.id), commitIds: [...new Set(candidate.evidence.map(e => e.commitId))],
      order, turn: state.turnIndex, at: new Date().toISOString(), method, reverted: false };
    data.entries.push(entry); candidate.status = 'applied'; candidate.appliedId = entry.id;
    data.revision++;
    return true;
  }


  function processPreferenceSignals(signals, state, registry, profileStore, config) {
    const policy = preferenceChangePolicy(config);
    if (!Array.isArray(signals) || !signals.length) return { applied: 0, collected: 0 };
    if (policy.mode === 'off' || (configCache && preferencePolicySignature(configCache) !== preferencePolicySignature(config))) return { applied: 0, collected: 0 };
    const commit = latestCommitJournalEntry(state);
    if (!commit?.commitId || (state.preferenceState && state.preferenceState.schemaVersion !== 1)) return { applied: 0, collected: 0 };
    let data = normalizePreferenceState(state.preferenceState), applied = 0, collected = 0;
    const seen = new Set();
    for (const raw of (Array.isArray(signals) ? signals : []).slice(0, 8)) {
      if (!isPlainObject(raw) || raw.scope === 'temporary' || raw.bodyConditionOnly === true || raw.independentOfErosyncPlan !== true) continue;
      const actor = resolveEntity(registry, raw.actor, state.scopeKey), profile = profileStore.profiles?.[actor];
      if (!profile || !isProfileDirectorEligible(profile) || !dynamicsProfileAllowed(profile, state, profileStore, registry)) continue;
      let item = normalizePositionPreferences([{ ...raw, basis: 'observed' }])[0];
      if (!item || !item.evidence.length) continue;
      const current = preferenceItemState(profile, { ...state, preferenceState: data }, item);
      if (current.item) item.id = current.item.id;
      if (current.item?.preference === item.preference) continue;
      const pair = `${actor}:${item.id}`;
      if (seen.has(pair)) continue; seen.add(pair);
      const evidenceId = `pref_ev_${fnv1a(`${commit.commitId}:${pair}`)}`;
      if (data?.candidates.some(candidate => candidate.evidence.some(e => e.id === evidenceId))) continue;
      if (!data) data = preferenceStateForRead(null);
      state.preferenceState = data;
      const id = `pref_candidate_${fnv1a(`${pair}:${item.preference}:${current.item?.preference || ''}:${current.order}`)}`;
      let candidate = data.candidates.find(c => c.id === id);
      if (candidate?.status === 'rejected') continue;
      if (!candidate) {
        candidate = { id, actor, item, previousPreference: current.item?.preference || '', predecessor: current.order, evidence: [], status: 'collecting', appliedId: '', updatedTurn: state.turnIndex };
        data.candidates.push(candidate);
      }
      candidate.item = item; candidate.updatedTurn = state.turnIndex;
      candidate.evidence.push({ id: evidenceId, commitId: commit.commitId, scene: `${state.scene?.sequence || 0}:${state.scene?.location || ''}`, turn: state.turnIndex,
        confidence: item.confidence, summary: item.evidence.join('; ').slice(0, 300) });
      candidate.evidence = candidate.evidence.slice(-20);
      const scenes = new Set(candidate.evidence.map(e => e.scene)).size;
      const confidence = candidate.evidence.reduce((sum, e) => sum + e.confidence, 0) / candidate.evidence.length;
      candidate.status = policy.mode === 'review' ? 'pending_review' : 'collecting';
      if (candidate.evidence.length >= policy.minEvidence && scenes >= policy.minScenes && confidence >= policy.minConfidence) {
        candidate.status = policy.mode === 'review' ? 'pending_review' : 'ready';
        if (policy.mode === 'auto' && applyPreferenceCandidate(state, profileStore, id)) applied++;
      }
      data.policySignature = preferencePolicySignature(config); data.revision++; collected++;
    }
    if (data) { state.preferenceState = data; compactPreferenceHistory(state); }
    return { applied, collected };
  }




  















  // Dusk ‘월경·임신 기록’(성인 항목)이 켜져 있으면 몸 상태·주기는 Dusk의 날짜 계산이 맡고, Erosync 쪽 주기는 쉰다(같은 몸 상태가 두 번 들어가지 않게). 저장값은 건드리지 않는다.
  let duskCycleOwns = false;
