    let value = stored || cycleInitialValue(settings, seed);
    if (value.status === 'waiting' && value.resumeAtMinute !== null && clock.minutes >= value.resumeAtMinute) value = cycleResumedValue(value, value.resumeAtMinute);
    const lengthDays = value.lengthDays || settings.lengthDays;
