    const irregular = value.irregular || settings.irregular, lutealDays = value.lutealDays || settings.lutealDays;
    const awareNextPeriod = typeof value.awareNextPeriod === 'boolean' ? value.awareNextPeriod : settings.awareNextPeriod;
    const swing = flat || lengthDays < 15 ? 0 : transition === 'late' ? 5 : transition === 'early' ? 3 : irregular ? 2 : 1;
    const shiftSeed = `${seed}:cycle-shift`, frame = `${seed}:${value.anchorMinute}`;
