      + delays.filter(entry => entry.cycle === number).reduce((sum, entry) => sum + entry.days, 0);
    const extraRule = transition === 'late' || settling || delays.length > 0;
    const locate = at => extraRule ? locateCycleDayExtra(at, lengthDays, swing, shiftSeed, initialDay, extraOf) : locateCycleDay(at, lengthDays, swing, shiftSeed, initialDay);
    const place = locate(ordinal);
    const cycleLengthDays = place.length, day = place.day, startOrdinal = ordinal - day + 1;
