      state.lastCommittedOutput = truncate(baseline.lastCommittedOutput, 7000);
      state.lastCommittedMessageIndex = Number.isInteger(baseline.lastCommittedMessageIndex) ? baseline.lastCommittedMessageIndex : -1;
