      const limit = Number.isInteger(removed[0]?.messageIndex) && removed[0].messageIndex >= 0
        ? removed[0].messageIndex
        : Number.MAX_SAFE_INTEGER;
      let survivor = chatCommits.filter((commit) => commit.index < limit).pop();
      if (!survivor && limit > 0) survivor = latestChatCommit(chatMessages.slice(0, limit));
