      // profile's owner. Ambiguous same-name local NPCs prevent automatic remap.
      if (context.userIdentity && overlap(names, context.userNames) && matches.length === 0) mapping.set(id, 'user');
      else if (matches.length === 1 && !overlap(names, context.userNames)) mapping.set(id, matches[0].id);
