      if (!stage) continue;
      const reasonSource = MOTIVE_REASON_SOURCES.includes(raw.reasonSource) ? raw.reasonSource : 'behavior';
      const planned = plannedActions.some((action) => action?.actor === actor);
      const independent = raw.independentOfErosyncPlan === true;
      const mainModelNonExecution = nonExecutedPairs.has(`${String(raw.actor || '').toLowerCase()}->${String(raw.target || '').toLowerCase()}`);
      const confidence = Math.round(clampNumber(raw.confidence, 50));
