      const evidenceId = `dev_${state.turnIndex}_${fnv1a(`${actor}::global:sexualMotive:${motive}:${reasonSource}:${summary}`)}`;
      const evidence = {
        id: evidenceId, turn: state.turnIndex, at: new Date().toISOString(), sceneKey, actor, target: '', scope: 'global', trait: 'sexualMotive', direction: 'increase',
        strength: Math.round(clampNumber(raw.strength, 50)), pattern: '', motive, reasonSource, stage, summary, confidence, plannedByErosync: planned, independent, mainModelNonExecution,
        qualifies: independent && !mainModelNonExecution && confidence >= MOTIVE_MIN_CONFIDENCE && MOTIVE_EVIDENCE_SOURCES.includes(reasonSource),
      };
