      dev.evidence.push(evidence);
      recordCommitId('evidenceIds', evidence.id);
      const candidateId = `candidate_${fnv1a(`${actor}::global:sexualMotive:${motive}:${stage}`)}`;
      recordCommitPrev('candidates', candidateId, dev.candidates[candidateId]);
