      const hatredDelta = botOverride?.domains?.conflict === true ? clampNumber(patch.hatredDelta, 0, -100, 100) * relationMultipliers.hatred : 0;
      const note = truncate(patch.note, 500).trim();
      const hasNumericChange = affectionDelta !== 0 || eroticAttractionDelta !== 0 || hatredDelta !== 0;
