  function sexualTargetFormChance(profileStore, state, actor, target) {
    if (!target || target === 'user') return null;
    const targetProfile = profileStore?.profiles?.[target];
    if (!targetProfile) return null;
    const gender = profileGenderValue(targetProfile);
    if (!['male', 'female', 'genderless'].includes(gender)) return null;
    const actorProfile = profileStore?.profiles?.[actor];
    if (!actorProfile) return null;
    const percent = targetGenderPreferencePercent(effectiveProfileForDirector(actorProfile, state, actor).targetGenderPreference, gender);
    if (percent === null) return null;
    return { percent, gender, chance: percent >= GENDER_GATE_FREE_PERCENT ? 100 : percent };
  }

