        for (const [actorId, actorState] of Object.entries(raw.nextState.actorStates)) {
          if (!isPlainObject(actorState)) continue;
          const id = resolveEntity(registry, actorId, state.scopeKey);
          if (!id || id === 'user') continue;
          const scoped = scopedRuntimeStateValue(actorState, registry, state.scopeKey);
          if (!scoped) continue;
          state.actorStates[id] = { ...(isPlainObject(state.actorStates[id]) ? state.actorStates[id] : {}), ...scoped };
        }
