  function interruptedSceneCandidate(scope, state) {
    const base = latestCommitJournalEntry(state), attempt = normalizeDirectorAttempt(state?.lastDirectorAttempt);
    const no = reason => ({ reason, base, attempt });
    if (!base || String(state.variantKey || 'default') !== String(scope.variantKey || 'default')) return no('RECOVERY_NO_BASE');
    if (base.userIdentity?.signature && base.userIdentity.signature !== scope.userIdentity?.signature) return no('RECOVERY_PERSONA_CHANGED');
    if (base.directorObservationApplied === true || state.preparedLookahead?.baseCommitId === base.commitId) return no('RECOVERY_OBSERVED');
    if (base.directorObservationApplied !== false || !base.undo?.hasBaseline || base.unverified || !attempt || attempt.applied
      || attempt.baseCommitId !== base.commitId || attempt.scopeKey !== scope.scopeKey || attempt.variantKey !== scope.variantKey) return no('RECOVERY_UNVERIFIABLE');
    if (!recoveryChatMatches(scope, state)) return no('RECOVERY_CHAT_CHANGED');
    const partition = `${scope.scopeKey}::${scope.variantKey || 'default'}`;
    // A status owned by this live instance is not an abandoned request, even if old.
    if (directorAttempts.has(partition) || [...decisionPromises.keys()].some(key => key.startsWith(`${scope.scopeKey}:`))) return no('RECOVERY_LIVE_TASK');
    if (state.sceneRecovery?.baseCommitId === base.commitId && state.sceneRecovery?.baseContentHash === base.contentHash) return no('RECOVERY_ALREADY_TRIED');
    if (isDirectorTerminal(attempt)) return no('RECOVERY_TERMINAL');
    if (String(attempt.restoreHash || '') !== String(transferMeta?.recoveryHash || '')
      || (attempt.restoreHash === undefined && (transferMeta.manualHoldPartitions || []).includes(partition))) return no('RECOVERY_BACKUP_RESTORED');
    if ((attempt.sourceHash !== undefined && attempt.sourceHash !== scope.sourceHash)
      || (attempt.planningSignature !== undefined && attempt.planningSignature !== scope.planningSignature)) return no('RECOVERY_INPUT_CHANGED');
    const started = Date.parse(attempt.startedAt);
    if (!Number.isFinite(started)) return no('RECOVERY_UNVERIFIABLE');
    const currentProvider = resolveRoleProfile(configCache || DEFAULT_CONFIG, 'director').providerId;
    if (attempt.provider === 'risu' || currentProvider === 'risu') {
      const until = started + Math.max(15, attempt.configuredTimeoutSeconds || 120) * 1000 * (attempt.maxRetries + 1) + 4000;
      if (risuActiveCalls.size || Date.now() < until) return { ...no('RECOVERY_PREVIOUS_REQUEST_WAIT'), waitUntil: until };
    }
    return { reason: '', base, attempt };
  }

  async function assertSceneRecoveryInput(pending, base) {
    const guard = createRequestGuard(15000, 'scene recovery recheck');
    try {
      const character = await guard.wait(R.getCharacter(), 'recovery current character');
      if (!character) throw staleLifecycleError('recovery character unavailable');
      const scope = await guard.wait(resolveScope(character), 'recovery current chat');
      if (scope.scopeKey !== pending.scope.scopeKey || scope.chat?.isStreaming === true) throw staleLifecycleError('recovery active chat changed');
      const store = await guard.wait(loadProfileStore(), 'recovery current profiles');
      const inventory = await guard.wait(collectSourceInventory(character, scope, { maxSourceChars: (configCache || DEFAULT_CONFIG).analysisMaxSourceChars, requestGuard: guard }), 'recovery current sources');
      if (resolveInventoryVariantKey(store, scope.sourceBundleKey, inventory) !== pending.scope.variantKey
        || effectiveSourceHash(configCache || DEFAULT_CONFIG, store, { sourceBundleKey: scope.sourceBundleKey, variantKey: pending.scope.variantKey }, inventory) !== pending.scope.sourceHash || Number(inventory.moduleSelectionRevision || 0) !== Number(pending.scope.moduleSelectionRevision || 0)
        || !recoveryChatMatches(scope, base.state)) throw staleLifecycleError('recovery input changed');
    } finally { guard.dispose(); }
  }

  function scheduleInterruptedSceneRecovery(delay = 180) {
    if (!sceneRecoveryCheckPending || sceneRecoveryTimer || sceneRecoveryTask || unloaded || stateRecoveryFault || typeof R.getCharacter !== 'function') return;
    sceneRecoveryTimer = setTimeout(() => {
      sceneRecoveryTimer = null;
      const previousNotice = sceneRecoveryNotice;
      const task = replanLiveLookahead(preparedDecisionGeneration, { recoverInterrupted: true });
      sceneRecoveryTask = task;
      task.catch(error => {
        sceneRecoveryCheckPending = false;
        if (sceneRecoveryNotice) sceneRecoveryNotice.reason = 'RECOVERY_PREPARATION_FAILED';
        if (!unloaded) warn('interrupted scene recovery preparation stopped:', { code: error?.code || 'RECOVERY_PREPARATION_FAILED' });
      }).finally(() => {
        if (sceneRecoveryTask === task) sceneRecoveryTask = null;
        if (sceneRecoveryCheckPending && sceneRecoveryNotice?.waitUntil > Date.now()) scheduleInterruptedSceneRecovery(sceneRecoveryNotice.waitUntil - Date.now() + 50);
        if (!sceneRecoveryCheckPending && sceneRecoveryNotice !== previousNotice) scheduleUiRefresh();
      });
    }, Math.max(180, delay));
  }

  

  

  function scheduleLiveLookahead() {
    if (replanTimer) clearTimeout(replanTimer);
    if (typeof R.getCharacter !== 'function') { replanTimer = null; return; }
    const generation = preparedDecisionGeneration;
    replanTimer = setTimeout(() => {
      replanTimer = null;
      const previous = replanTask || Promise.resolve();
      const task = previous.catch(() => {}).then(() => replanLiveLookahead(generation));
      replanTask = task;
      task.catch(error => {
        if (!unloaded && !isStaleLifecycleError(error)) warn('scene replan preparation failed:', { code: error?.code || 'REPLAN_PREPARATION_FAILED' });
      }).finally(() => { if (replanTask === task) replanTask = null; });
    }, 180);
  }

  async function replanLiveLookahead(generation, options = {}) {
    if (unloaded || transferBusy || exportWaitInProgress || generation !== preparedDecisionGeneration) return null;
    if (options.recoverInterrupted && !coreHooksOperational()) return null;
    if (options.recoverInterrupted && (analysisRuntime.running || profileCompilePromises.size)) return null;
    const guard = createRequestGuard(15000, 'scene replan preparation');
    let job = null;
    try {
      const config = await guard.wait(loadConfig(), 'replan settings');
      if (!config.enabled || config.mode === 'off') return null;
      const character = await guard.wait(R.getCharacter(), 'replan character');
      if (!character) return null;
      const scope = await guard.wait(resolveScope(character), 'replan scope');
      if (scope.chat?.isStreaming === true || pendingMainOrder.some(item => item.scope?.scopeKey === scope.scopeKey)) return null;
      const store = await guard.wait(loadProfileStore(), 'replan profiles');
      const inventory = await guard.wait(collectSourceInventory(character, scope, { maxSourceChars: config.analysisMaxSourceChars, requestGuard: guard }), 'replan inventory');
      scope.variantKey = resolveInventoryVariantKey(store, scope.sourceBundleKey, inventory);
      scope.sourceHash = effectiveSourceHash(config, store, scope, inventory); // 점진 분석(2026-10-31)
      scope.variantSignature = String(inventory.activationSignature || '');
      scope.moduleSelectionRevision = clampInt(inventory.moduleSelectionRevision, 0, 0, 1000000000);
      const context = lookaheadContexts.get(`${scope.scopeKey}::${scope.variantKey || 'default'}`);
      const [state, registry, override] = await guard.wait(Promise.all([loadExistingSession(scope), loadRegistry(), getBotOverride(scope.sourceBundleKey)]), 'replan state');
      const latest = latestCommitJournalEntry(state);
      if (!latest) { if (options.recoverInterrupted) sceneRecoveryCheckPending = false; return null; }
      const live = latestChatCommit(scope.chat?.message);
      if (!live || live.index !== latest.messageIndex || live.id !== latest.messageId || live.hash !== (latest.currentContentHash || latest.contentHash)) {
        if (options.recoverInterrupted) sceneRecoveryCheckPending = false;
        if (!options.retryOf) setUiStatus('현재 선택된 답변과 저장된 판단 기준이 달라 재판단을 보류했습니다. 다음 확정 응답에서 새 장면을 판단합니다.', 'warn');
        return null;
      }
      if (generation !== preparedDecisionGeneration || unloaded || transferBusy || exportWaitInProgress) return null;
      if (options.retryOf && !judgmentRetryStillWanted(scope, state, latest, options)) return null;
      const bundle = bundleVariantRecord(store.sourceBundles?.[scope.sourceBundleKey], scope.variantKey);
      const ids = preparedProfileIdsForBundle(bundle, store, scope.variantKey);
      scope.planningSignature = planningSettingsSignature(config, override, store, scope.sourceBundleKey, scope.variantKey);
      const fence = captureBackgroundFence(scope);
      const epoch = currentScopeEpoch(scope);
      let recovery = null;
      if (options.recoverInterrupted) {
        const candidate = interruptedSceneCandidate(scope, state);
        sceneRecoveryNotice = { scopeKey: scope.scopeKey, variantKey: scope.variantKey, baseCommitId: latest.commitId, reason: candidate.reason, waitUntil: candidate.waitUntil || 0 };
        sceneRecoveryCheckPending = false;
        if (candidate.reason) {
          if (candidate.waitUntil && candidate.waitUntil > Date.now()) {
            sceneRecoveryCheckPending = true;
          }
          return null;
        }
        const ready = !detectVariantConflict(store, scope.sourceBundleKey, inventory) && ['complete', 'partial'].includes(bundle?.status)
          && bundle.sourceHash === scope.sourceHash && Number(bundle.moduleSelectionRevision || 0) === scope.moduleSelectionRevision && ids.length > 0;
        if (!ready) { sceneRecoveryNotice.reason = 'RECOVERY_INPUT_CHANGED'; return null; }
        if (analysisRuntime.running || profileCompilePromises.size || resyncPromises.has(scope.scopeKey) || isScopeSessionWriteBusy(scope)) {
          sceneRecoveryCheckPending = true; sceneRecoveryNotice.reason = 'RECOVERY_BUSY'; return null;
        }
        await guard.wait(assertSceneRecoveryInput({ scope }, { state }), 'recovery live basis');
        recovery = await guard.wait(enqueueCoordinatedStateWrite(scope, async () => {
          guard.throwIfAborted('recovery reservation');
          assertBackgroundFence(fence, 'recovery reservation');
          if (generation !== preparedDecisionGeneration || transferBusy || exportWaitInProgress) return null;
          const read = await strictDurableRead(`${SESSION_KEY_PREFIX}${scope.scopeKey}`);
          if (read.status !== 'ok' || !isPlainObject(read.value) || read.value.variantKey !== scope.variantKey) return null;
          const stored = safeClone(read.value), current = normalizeSessionState(stored, scope.scopeKey, config);
          const fresh = interruptedSceneCandidate(scope, current);
          if (fresh.reason || fresh.attempt.id !== candidate.attempt.id || fresh.base.commitId !== latest.commitId) return null;
          const reservation = { schemaVersion: 1, scopeKey: scope.scopeKey, variantKey: scope.variantKey, baseCommitId: latest.commitId,
            baseContentHash: latest.contentHash, sourceAttemptId: candidate.attempt.id, reservedAt: new Date().toISOString(), restoreHash: String(transferMeta?.recoveryHash || '') };
          stored.sceneRecovery = reservation;
          guard.throwIfAborted('recovery reservation save');
          await commitStateTransactionWithinLock('interrupted scene recovery reservation', [{ key: `${SESSION_KEY_PREFIX}${scope.scopeKey}`, value: stored }], { fence });
          state.sceneRecovery = reservation;
          return reservation;
        }), 'recovery reservation');
        if (!recovery) { sceneRecoveryNotice.reason = 'RECOVERY_RESERVATION_CHANGED'; return null; }
        sceneRecoveryNotice.reason = '';
      }
      const reusable = context?.base.commitId === latest.commitId && backgroundFenceIsCurrent(context.base.backgroundFence || context.pending.backgroundFence) ? context : null;
      const dialogue = buildCompatibleMessageContext(scope.chat.message.slice(0, latest.messageIndex).map(message => ({
        role: message.role === 'char' ? 'assistant' : message.role, content: chatMessageText(message),
      })), config);
      const pending = { ...(reusable?.pending || {}), scope, epoch, lifecycleEpoch, backgroundFence: fence,
        lookaheadConversation: reusable?.pending.lookaheadConversation || recentConversation(dialogue.dialogue, config.recentMessages),
        lookaheadExternalContext: reusable?.pending.lookaheadExternalContext || dialogue.external,
        externalSources: reusable?.pending.externalSources || dialogue.detectedSources,
      };
      const previousAttempt = state.lastDirectorAttempt;
      const knownUnapplied = latest.directorObservationApplied === false || latest.directorObservationApplied !== true
        && previousAttempt?.baseCommitId === latest.commitId && previousAttempt.applied === false
        && ['failed', 'cancelled', 'discarded', 'skipped'].includes(previousAttempt.phase)
        && (latest.undo?.eventIds || []).every(id => state.events.some(event => event.id === id && event.type === 'decision'));
      guard.throwIfAborted('replan enqueue');
      options.onStart?.(); // 수동 판단(2026-10-31): 단추가 '시작됨'을 알 수 있게
      job = queueNextTurnLookahead(pending, chatMessageText(scope.chat.message[latest.messageIndex]), {
        ...(reusable?.base || {}), commitId: latest.commitId, contentHash: latest.contentHash, turnIndex: state.turnIndex, state, registry,
        profileStore: projectProfileStoreVariant(safeClone(store), scope.sourceBundleKey, scope.variantKey), botOverride: safeClone(override),
        epoch, lifecycleEpoch, backgroundFence: fence, profileSourceIds: ids,
        planOnly: recovery ? false : options.manual ? latest.directorObservationApplied === true : !knownUnapplied, // 수동 판단(2026-10-31): 관측이 안 된 응답이면 관측 포함
        ...(recovery ? { recovery } : {}),
        retryOf: options.retryOf || '',
        lookaheadEligible: ['complete', 'partial'].includes(bundle?.status) && bundle.sourceHash === scope.sourceHash
          && Number(bundle.moduleSelectionRevision || 0) === scope.moduleSelectionRevision && ids.length > 0,
      });
    } finally { guard.dispose(); }
    return await job;
  }

  // 수동 판단(2026-10-31, Erosync.Manual-Judgment.Work-Plan.md): 장면·목표 탭 '지금 판단' 단추 — 밀린 응답은 리롤 뒤에 쓰는 통과 확정 길로
  // 따라잡아 확정하고 다음 턴 판단을 잇는다. 이미 확정돼 있으면 돌던 판단을 멈추고 이 응답 기준으로 다시 판단한다. 못 하는 때는 이유를 적는다.
  // 같이 붙는 것: 요청 연결 상태 줄(훅 등록·권한·마지막 요청/응답/확정 시각), 최근 로그(글 칸 없이 300줄, 복사).
  const MANUAL_LOCK_WAIT_MS = 8000, MANUAL_JUDGE_BUDGET_MS = 20000, MANUAL_STALE_PENDING_MS = 10 * 60 * 1000, PLUGIN_LOG_LIMIT = 300;

  function pluginLogPush(level, args) {
    try {
      const now = new Date();
      const time = [now.getHours(), now.getMinutes(), now.getSeconds()].map(part => String(part).padStart(2, '0')).join(':');
      pluginLogRing.push(`${time} ${level} ${(Array.isArray(args) ? args : [args]).map(item => pluginLogValue(item)).join(' ')}`);
      if (pluginLogRing.length > PLUGIN_LOG_LIMIT) pluginLogRing.splice(0, pluginLogRing.length - PLUGIN_LOG_LIMIT);
    } catch (_) { /* 로그 때문에 멈추지 않는다 */ }
  }
  
  

  
  // 요청 연결 상태: 리스가 훅을 부르는지, 마지막 요청·응답·확정이 언제였는지
  
  

  // 저장된 마지막 확정 뒤에 온 캐릭터 응답 가운데 이번에 확정하는 것(마지막) 앞의 개수 = 기록 없이 지나간 응답 수
  

  

  
  
  
  



  function profileRefreshReservationIsCurrent(pending, fence) {
    return !!pending
      && !!fence
      && pending.lifecycleEpoch === lifecycleEpoch
      && fence.lifecycleEpoch === pending.lifecycleEpoch
      && backgroundFenceIsCurrent(fence);
  }

  function buildProfileRefreshRequest(config, store, scope, inventory, variantConflict) {
    const rootBundle = store?.sourceBundles?.[scope?.sourceBundleKey || ''];
    const preparedBundle = bundleVariantRecord(rootBundle, scope?.variantKey || 'default');
    const baselineBundle = preparedBundle || bundleVariantRecord(rootBundle, rootBundle?.activeVariantKey || 'default') || rootBundle;
    const moduleSelectionChanged = !!baselineBundle
      && clampInt(baselineBundle.moduleSelectionRevision, 0, 0, 1000000000) !== clampInt(inventory?.moduleSelectionRevision, 0, 0, 1000000000);
    // 점진 분석(2026-10-31, Erosync.Progressive-Followup.Work-Plan.md 2절 1항): 카드만으로 만든 점진 묶음은 "카드만 → 전체 자료" 차이를 자료 바뀜으로 보지 않는다(설정을 전체 분석으로 바꾸면 전처럼 본다).
    const progressiveBundle = config?.profilePreparationMode === 'progressive' && preparedBundle?.preparation === 'progressive';
    const sourceChanged = !preparedBundle || (!progressiveBundle && String(preparedBundle.sourceHash || '') !== String(inventory?.sourceHash || ''));
    if (sourceChanged || moduleSelectionChanged || variantConflict) invalidateUiInventory(scope?.sourceBundleKey);
    const reason = variantConflict ? 'variant_conflict' : moduleSelectionChanged ? 'module_selection_changed' : 'source_changed';
    return {
      needed: !(transferMeta.manualHoldPartitions || []).includes(`${scope.sourceBundleKey}::${preparedBundle ? scope.variantKey || 'default' : rootBundle?.activeVariantKey || 'default'}`)
        && config?.autoRefreshProfiles === true && !!rootBundle && (variantConflict || moduleSelectionChanged || sourceChanged),
      reason,
      sourceHash: String(inventory?.sourceHash || ''),
      moduleSelectionRevision: clampInt(inventory?.moduleSelectionRevision, 0, 0, 1000000000),
    };
  }


  function cacheProfileRefreshState(scope, state) {
    if (!scope?.sourceBundleKey || !state) return null;
    profileRefreshStates.set(profileRefreshKey(scope), state);
    scheduleUiRefresh(0);
    return state;
  }

  async function persistProfileRefreshState(scope, patch = {}, options = {}) {
    if (!scope?.sourceBundleKey) return null;
    if (options.fence && !profileRefreshReservationIsCurrent(options.pending, options.fence)) return null;
    const key = profileRefreshKey(scope);
    const state = createProfileRefreshState(scope, patch);
    if (options.fence && !profileRefreshReservationIsCurrent(options.pending, options.fence)) return null;
    cacheProfileRefreshState(scope, state);
    try {
      await mutateProfileRegistry('profile refresh status', (store) => {
        const current = analysisCheckpointSnapshot(store.analysisRuns?.[key]);
        store.analysisRuns[key] = analysisCheckpointSnapshot(current, { autoRefresh: state, updatedAt: current.updatedAt || state.updatedAt });
        store.analysisRuns[scope.sourceBundleKey] = store.analysisRuns[key];
      }, { writeRegistry: false, fence: options.fence || null });
    } catch (error) {
      if (options.fence && !profileRefreshReservationIsCurrent(options.pending, options.fence)) return null;
      warn('profile refresh status save skipped:', error?.message || error);
    }
    if (options.fence && !profileRefreshReservationIsCurrent(options.pending, options.fence)) return null;
    return state;
  }

  function captureAutoProfileScopeSnapshot(state, scope, variantKey) {
    const profiles = state?.profiles || emptyProfileStore();
    const registry = state?.registry || emptyRegistry();
    const sourceBundleKey = String(scope?.sourceBundleKey || '');
    const targetVariantKey = String(variantKey || scope?.variantKey || 'default');
    const bundleRoot = profiles.sourceBundles?.[sourceBundleKey];
    const profileIds = new Set([
      ...(Array.isArray(bundleVariantRecord(bundleRoot, targetVariantKey)?.characterIds) ? bundleVariantRecord(bundleRoot, targetVariantKey).characterIds : []),
      ...Object.entries(profiles.profiles || {}).filter(([, profile]) => (profile?.ownerBundleKeys || []).includes(sourceBundleKey)).map(([id]) => id),
    ]);
    return {
      sourceBundleKey,
      targetVariantKey,
      bundleRoot: safeClone(bundleRoot),
      targetVariantExisted: !!bundleVariantRecord(bundleRoot, targetVariantKey),
      profiles: Object.fromEntries([...profileIds].filter((id) => profiles.profiles?.[id]).map((id) => [id, safeClone(profiles.profiles[id])])),
      registry: Object.fromEntries([...profileIds].filter((id) => registry.entities?.[id]).map((id) => [id, safeClone(registry.entities[id])])),
      baseRelations: Object.fromEntries(Object.entries(profiles.baseRelations || {}).filter(([, relation]) => relation?.sourceBundleKey === sourceBundleKey && String(relation.variantKey || 'default') === targetVariantKey).map(([key, value]) => [key, safeClone(value)])),
      analysisRuns: Object.fromEntries(Object.entries(profiles.analysisRuns || {}).filter(([key]) => key === sourceBundleKey || key === `${sourceBundleKey}::${targetVariantKey}`).map(([key, value]) => [key, safeClone(value)])),
      executionPartition: safeClone(profiles.analysisExecutionHistory?.partitions?.[analysisHistoryPartitionKey(sourceBundleKey, targetVariantKey)]),
    };
  }

  function autoProfileRollbackAllowed(active) {
    return !!active?.rollbackFence
      && active.rollbackFence.lifecycleEpoch === lifecycleEpoch
      && active.rollbackFence.resetGeneration === resetGeneration
      && backgroundFenceIsCurrent(active.rollbackFence);
  }

  async function restoreAutoProfileSnapshot(active, refreshState = null) {
    const before = active?.beforeState;
    if (!before?.sourceBundleKey || !autoProfileRollbackAllowed(active)) return false;
    const sourceBundleKey = before.sourceBundleKey;
    const variantKey = before.targetVariantKey;
    const autoSourceHash = String(active.sourceHash || '');
    await mutateProfileRegistry('automatic profile refresh scoped rollback', (profiles, registry) => {
      const freshRoot = profiles.sourceBundles?.[sourceBundleKey];
      const baselineRoot = before.bundleRoot;
      if (baselineRoot && freshRoot) {
        const freshVariants = { ...(isPlainObject(freshRoot.variants) ? freshRoot.variants : {}) };
        const baselineVariant = bundleVariantRecord(baselineRoot, variantKey);
        if (before.targetVariantExisted && baselineVariant) freshVariants[variantKey] = safeClone(baselineVariant);
        else if (freshVariants[variantKey]?.sourceHash === autoSourceHash) delete freshVariants[variantKey];
        const baselineActiveKey = String(baselineRoot.activeVariantKey || 'default');
        const baselineActive = bundleVariantRecord(baselineRoot, baselineActiveKey) || baselineRoot;
        profiles.sourceBundles[sourceBundleKey] = { ...freshRoot, ...safeClone(baselineActive), variants: freshVariants, activeVariantKey: baselineActiveKey };
      } else if (baselineRoot && !freshRoot) profiles.sourceBundles[sourceBundleKey] = safeClone(baselineRoot);

      const baselineIds = new Set(Object.keys(before.profiles || {}));
      for (const [id, baselineProfile] of Object.entries(before.profiles || {})) {
        const fresh = profiles.profiles?.[id];
        if (!fresh) continue; // A concurrent user deletion/tombstone wins.
        const freshVariants = { ...(isPlainObject(fresh.variants) ? fresh.variants : {}) };
        const baselineVariants = isPlainObject(baselineProfile.variants) ? baselineProfile.variants : {};
        if (isPlainObject(baselineVariants[variantKey])) {
          const preservedVariantLocked = freshVariants[variantKey]?.locked === true || fresh.locked === true;
          freshVariants[variantKey] = {
            ...safeClone(baselineVariants[variantKey]),
            userOverrides: safeClone(freshVariants[variantKey]?.userOverrides || fresh.userOverrides || {}),
            locked: preservedVariantLocked,
            lockOrigin: normalizeProfileLockOrigin(freshVariants[variantKey]?.locked === true ? freshVariants[variantKey]?.lockOrigin : fresh.lockOrigin, preservedVariantLocked),
          };
        } else if (freshVariants[variantKey]?.sourceHash === autoSourceHash) delete freshVariants[variantKey];
        const restored = {
          ...fresh,
          ...safeClone(baselineProfile),
          variants: freshVariants,
          userOverrides: safeClone(fresh.userOverrides || {}),
          locked: fresh.locked === true,
          lockOrigin: normalizeProfileLockOrigin(fresh.lockOrigin, fresh.locked === true),
          identityOverride: safeClone(fresh.identityOverride),
          sessionOverlay: safeClone(fresh.sessionOverlay || {}),
          scopeOwnership: safeClone(fresh.scopeOwnership),
          excludedFromDirector: fresh.excludedFromDirector === true,
          ownerBundleKeys: normalizeStringList([...(baselineProfile.ownerBundleKeys || []), ...(fresh.ownerBundleKeys || [])], 40, 160),
        };
        // 프로필 사진 선택은 사용자 값이라 수정값·잠금처럼 지금 값을 쓴다
        if (isPlainObject(fresh.portrait)) restored.portrait = safeClone(fresh.portrait);
        else delete restored.portrait;
        profiles.profiles[id] = restored;
        if (before.registry?.[id] && registry.entities?.[id]) {
          const live = registry.entities[id];
          registry.entities[id] = { ...safeClone(before.registry[id]), firstSeenTurn: live.firstSeenTurn, lastSeenTurn: live.lastSeenTurn, appearanceCount: live.appearanceCount, scopeKey: live.scopeKey || before.registry[id].scopeKey || '' };
        }
      }
      for (const [id, profile] of Object.entries(profiles.profiles || {})) {
        if (baselineIds.has(id) || !(profile?.ownerBundleKeys || []).includes(sourceBundleKey)) continue;
        const autoOwned = profile.sourceHash === autoSourceHash || profile.variants?.[variantKey]?.sourceHash === autoSourceHash;
        if (!autoOwned) continue;
        profile.ownerBundleKeys = profile.ownerBundleKeys.filter((key) => key !== sourceBundleKey);
        if (profile.ownerBundleKeys.length === 0) {
          delete profiles.profiles[id];
          if (registry.entities?.[id]?.profileId === id) delete registry.entities[id];
        }
      }
      const restoredRoot = profiles.sourceBundles?.[sourceBundleKey];
      if (restoredRoot) {
        restoredRoot.characterIds = (restoredRoot.characterIds || []).filter((id) => !!profiles.profiles?.[id]);
        for (const variant of Object.values(isPlainObject(restoredRoot.variants) ? restoredRoot.variants : {})) {
          if (isPlainObject(variant)) variant.characterIds = (variant.characterIds || []).filter((id) => !!profiles.profiles?.[id]);
        }
      }
      for (const [key, relation] of Object.entries(profiles.baseRelations || {})) {
        if (relation?.sourceBundleKey === sourceBundleKey && String(relation.variantKey || 'default') === variantKey) delete profiles.baseRelations[key];
      }
      for (const [key, relation] of Object.entries(before.baseRelations || {})) {
        if (relation.from !== 'user' && !profiles.profiles?.[relation.from]) continue;
        if (relation.to !== 'user' && !profiles.profiles?.[relation.to]) continue;
        if (isBaseRelationSuppressed(profiles, sourceBundleKey, variantKey, relation.from, relation.to)) continue;
        profiles.baseRelations[key] = safeClone(relation);
      }
      for (const key of [sourceBundleKey, `${sourceBundleKey}::${variantKey}`]) {
        if (before.analysisRuns?.[key]) profiles.analysisRuns[key] = safeClone(before.analysisRuns[key]);
        else delete profiles.analysisRuns[key];
      }
      if (refreshState) {
        const refreshKey = analysisHistoryPartitionKey(sourceBundleKey, variantKey);
        const current = analysisCheckpointSnapshot(profiles.analysisRuns?.[refreshKey] || profiles.analysisRuns?.[sourceBundleKey]);
        const restoredRun = analysisCheckpointSnapshot(current, { autoRefresh: safeClone(refreshState), updatedAt: current.updatedAt || refreshState.updatedAt });
        profiles.analysisRuns[refreshKey] = restoredRun;
        profiles.analysisRuns[sourceBundleKey] = restoredRun;
      }
      profiles.analysisExecutionHistory = normalizeAnalysisExecutionHistory(profiles.analysisExecutionHistory);
      const partitionKey = analysisHistoryPartitionKey(sourceBundleKey, variantKey);
      if (before.executionPartition) profiles.analysisExecutionHistory.partitions[partitionKey] = safeClone(before.executionPartition);
      else delete profiles.analysisExecutionHistory.partitions[partitionKey];
      // deletedProfiles and baseRelationSuppressions intentionally remain from the fresh store.
    }, { fence: active.rollbackFence, registryFirst: true });
    return true;
  }

  function preemptAutoProfileRefreshForMain() {
    const active = activeAutoProfileRefresh;
    if (!active) return false;
    if (active.preempted) return true;
    const error = new Error('automatic profile refresh was safely cancelled for a new main request');
    error.code = 'EROSYNC_ANALYSIS_CANCELLED';
    autoProfileRefreshGeneration += 1;
    active.preempted = true;
    active.preemptKind = 'main_request';
    active.guard?.abort(error);
    updateAnalysisRuntime({ running: false, cancelRequested: true, phase: 'cancelled', detail: '새 메인 요청을 우선하기 위해 자동 재분석을 안전하게 취소했습니다.', finishedAt: Date.now() });
    return true;
  }

  async function preemptAutoProfileRefreshForMutation(sourceBundleKey, reason = 'user profile mutation') {
    const active = activeAutoProfileRefresh;
    if (!active || active.scope?.sourceBundleKey !== sourceBundleKey) return false;
    if (active.preempted) {
      try { await active.promise; } catch (_) {}
      return true;
    }
    const error = new Error(reason);
    error.code = 'EROSYNC_ANALYSIS_CANCELLED';
    autoProfileRefreshGeneration += 1;
    active.preempted = true;
    active.preemptKind = 'user_mutation';
    active.guard?.abort(error);
    updateAnalysisRuntime({ running: false, cancelRequested: true, phase: 'cancelled', detail: '사용자 프로필 변경을 우선하기 위해 자동 재분석을 취소했습니다.', finishedAt: Date.now() });
    try { await active.promise; } catch (_) {}
    return true;
  }

  function schedulePostResponseProfileRefresh(pending) {
    if (transferBusy || stateRecoveryFault) return null;
    const request = pending?.profileRefresh;
    if (settingsResetInProgress || !request?.needed || !pending?.scope) return Promise.resolve(null);
    const reservationFence = profileRefreshReservationFence(pending);
    if (!profileRefreshReservationIsCurrent(pending, reservationFence)) return Promise.resolve(null);
    let scope = safeClone(pending.scope) || pending.scope;
    const existingCoordinator = activeAutoProfileRefresh;
    if (existingCoordinator?.promise
      && existingCoordinator.scope?.sourceBundleKey === scope.sourceBundleKey
      && existingCoordinator.scope?.scopeKey === scope.scopeKey
      && String(existingCoordinator.sourceHash || '') === String(request.sourceHash || '')
      && clampInt(existingCoordinator.moduleSelectionRevision, 0, 0, 1000000000) === clampInt(request.moduleSelectionRevision, 0, 0, 1000000000)) {
      return existingCoordinator.promise;
    }
    let refreshSourceHash = String(request.sourceHash || '');
    let refreshModuleSelectionRevision = clampInt(request.moduleSelectionRevision, 0, 0, 1000000000);
    const reservationIsCurrent = () => !settingsResetInProgress && profileRefreshReservationIsCurrent(pending, reservationFence);
    const manualPending = async (reason, message) => {
      if (!reservationIsCurrent()) return null;
      return await persistProfileRefreshState(scope, {
        status: 'manual_pending',
        reason,
        message,
        sourceHash: refreshSourceHash,
        moduleSelectionRevision: refreshModuleSelectionRevision,
      }, { pending, fence: reservationFence });
    };
    const job = (async () => {
      if (!reservationIsCurrent()) return null;
      const config = await loadConfig();
      if (!reservationIsCurrent()) return null;
      if (config.autoRefreshProfiles !== true) return null;
      if (analysisRuntime.running || profileCompilePromises.size > 0 || verificationPromises.size > 0) {
        return await manualPending('analysis_busy', '다른 수동 분석 또는 인물 판독이 진행 중이어서 자동 재분석을 시작하지 않았습니다. 수동 재분석이 필요합니다.');
      }
      const assignment = resolveRoleProfile(config, 'profile');
      const cancellable = autoRefreshCancellable(assignment.providerId, typeof host.runAI === 'function');
      if (!cancellable) return await manualPending('risu_non_cancellable', '자동 재분석 대기 · RisuAI 보조 모델 호출은 안전하게 취소할 수 없어 수동 재분석이 필요합니다.');
      if (activeAutoProfileRefresh) return await manualPending('coordinator_busy', '다른 자동 재분석이 진행 중이어서 이 변경은 수동 재분석 대기로 남겼습니다.');
      if (!reservationIsCurrent()) return null;
      // 정의학 반영 뒤 프로필 묶음마다 호출이 둘(축 채점·프로필 작성)이라 자동 재분석 시간 예산을 그만큼 늘렸다(호출 시간 ×3 → ×5).
      const timeoutMs = Math.max(30000, providerAttemptLimitMs(assignment) * 5);
      const guard = cancellable ? createRequestGuard(timeoutMs, 'automatic profile refresh') : null;
      const refreshGeneration = guard ? ++autoProfileRefreshGeneration : null;
      const active = guard ? {
        id: `auto_refresh_${++autoProfileRefreshSequence}`,
        scope,
        guard,
        sourceHash: refreshSourceHash,
        moduleSelectionRevision: refreshModuleSelectionRevision,
        preempted: false,
        preemptKind: '',
        generation: refreshGeneration,
        reservationFence,
        reservationLifecycleEpoch: pending.lifecycleEpoch,
      } : null;
      if (active) {
        activeAutoProfileRefresh = active;
        active.promise = job;
      }
      try {
        if (!reservationIsCurrent()) return null;
        const characterPromise = R.getCharacter();
        const character = guard ? await guard.wait(characterPromise, 'automatic profile character') : await characterPromise;
        if (!reservationIsCurrent()) return null;
        const freshScopePromise = resolveScope(character);
        const freshScope = guard ? await guard.wait(freshScopePromise, 'automatic profile scope') : await freshScopePromise;
        if (!reservationIsCurrent()) return null;
        if (!freshScope || freshScope.scopeKey !== pending.scope.scopeKey || freshScope.sourceBundleKey !== pending.scope.sourceBundleKey) {
          return await manualPending('scope_changed', '응답 후 채팅 범위가 바뀌어 자동 재분석을 시작하지 않았습니다. 수동 재분석이 필요합니다.');
        }
        const inventoryPromise = collectSourceInventory(character, freshScope, { force: true, maxSourceChars: config.analysisMaxSourceChars, requestGuard: guard });
        const inventory = guard ? await guard.wait(inventoryPromise, 'automatic profile inventory') : await inventoryPromise;
        if (!reservationIsCurrent()) return null;
        const freshStorePromise = loadProfileStore();
        const freshStore = guard ? await guard.wait(freshStorePromise, 'automatic profile store') : await freshStorePromise;
        if (!reservationIsCurrent()) return null;
        freshScope.variantKey = resolveInventoryVariantKey(freshStore, freshScope.sourceBundleKey, inventory);
        freshScope.variantLabel = String(inventory.variantLabel || freshScope.variantKey);
        freshScope.sourceHash = String(inventory.sourceHash || '');
        freshScope.moduleSelectionRevision = clampInt(inventory.moduleSelectionRevision, 0, 0, 1000000000);
        inventory.variantKey = freshScope.variantKey;
        const freshConflict = detectVariantConflict(freshStore, freshScope.sourceBundleKey, inventory);
        const freshRequest = buildProfileRefreshRequest(config, freshStore, freshScope, inventory, freshConflict);
        scope = freshScope;
        refreshSourceHash = freshRequest.sourceHash;
        refreshModuleSelectionRevision = freshRequest.moduleSelectionRevision;
        if (active) {
          active.scope = scope;
          active.sourceHash = refreshSourceHash;
          active.moduleSelectionRevision = refreshModuleSelectionRevision;
        }
        if (freshRequest.reason === 'module_selection_changed') return await manualPending('module_selection_changed', '분석 대상 모듈이 변경되었습니다. 자동 재분석 대신 수동 재분석이 필요합니다.');
        if (freshRequest.reason === 'variant_conflict') return await manualPending('variant_conflict', '여러 설정 변형이 함께 활성화되어 자동 재분석을 시작하지 않았습니다. 모듈·로어를 정리한 뒤 수동 재분석이 필요합니다.');
        if (!freshRequest.needed) return null;
        if (!guard) return await manualPending('risu_non_cancellable', '자동 재분석 대기 · RisuAI 보조 모델 호출은 안전하게 취소할 수 없어 수동 재분석이 필요합니다.');
        if (!reservationIsCurrent()) return null;
        const rollbackState = await guard.wait(readFreshProfileRegistryState(), 'automatic profile rollback snapshot');
        if (!reservationIsCurrent()) return null;
        active.beforeState = captureAutoProfileScopeSnapshot(rollbackState, scope, inventory.variantKey || scope.variantKey || 'default');
        active.rollbackFence = reservationFence;
        await persistProfileRefreshState(scope, {
          status: 'running',
          reason: 'source_changed',
          message: '응답 확정 후 자동 재분석을 진행하고 있습니다. 새 메인 요청이 오면 안전하게 취소합니다.',
          sourceHash: refreshSourceHash,
          moduleSelectionRevision: refreshModuleSelectionRevision,
        }, { pending, fence: reservationFence });
        if (!reservationIsCurrent()) return null;
        guard.throwIfAborted('automatic profile admission');
        await compileProfilesFromInventory(character, scope, config, inventory, { force: true, autoRefresh: true, knownPeopleOnly: true, requestGuard: guard, autoProfileRefreshGeneration: refreshGeneration, backgroundFence: reservationFence });
        if (!reservationIsCurrent()) return null;
        guard.throwIfAborted('automatic profile completion');
        const fresh = await guard.wait(readFreshProfileRegistryState(), 'automatic profile durable verification');
        if (!reservationIsCurrent()) return null;
        const durableBundle = bundleVariantRecord(fresh.profiles?.sourceBundles?.[scope.sourceBundleKey], inventory.variantKey || scope.variantKey || 'default');
        const durableComplete = durableBundle?.status === 'complete'
          && String(durableBundle.sourceHash || '') === String(inventory.sourceHash || '')
          && clampInt(durableBundle.moduleSelectionRevision, 0, 0, 1000000000) === clampInt(inventory.moduleSelectionRevision, 0, 0, 1000000000);
        if (!durableComplete) {
          await restoreAutoProfileSnapshot(active);
          updateAnalysisRuntime({ running: false, phase: 'partial', detail: '자동 재분석이 완전한 성공 상태가 아니어서 수동 재분석이 필요합니다.', errors: [], finishedAt: Date.now() });
          return await manualPending('analysis_incomplete', '자동 재분석이 완전한 성공 상태로 저장되지 않아 수동 재분석이 필요합니다.');
        }
        return await persistProfileRefreshState(scope, {
          status: 'complete',
          reason: 'source_changed',
          message: '자료 변경 자동 재분석을 완료했습니다.',
          sourceHash: inventory.sourceHash,
          moduleSelectionRevision: inventory.moduleSelectionRevision,
        }, { pending, fence: reservationFence });
      } catch (error) {
        if (!reservationIsCurrent() && !active?.preempted) return null;
        if (active?.preempted) {
          if (!autoProfileRollbackAllowed(active)) return null;
          const userMutation = active.preemptKind === 'user_mutation';
          const refreshState = createProfileRefreshState(scope, {
            status: 'manual_pending',
            reason: userMutation ? 'user_mutation_preempted' : 'main_request_preempted',
            message: userMutation
              ? '사용자 프로필 변경을 보존하기 위해 자동 재분석을 취소했습니다. 필요하면 수동 재분석을 실행하세요.'
              : '자동 재분석이 새 메인 요청을 위해 안전하게 취소되었습니다. 수동 재분석이 필요합니다.',
            sourceHash: refreshSourceHash,
            moduleSelectionRevision: refreshModuleSelectionRevision,
          });
          let restored = false;
          if (active.beforeState) {
            try { restored = await restoreAutoProfileSnapshot(active, refreshState); } catch (restoreError) { warn('automatic profile preemption rollback failed:', restoreError?.message || restoreError); }
          }
          if (!autoProfileRollbackAllowed(active)) return null;
          updateAnalysisRuntime({
            running: false,
            cancelRequested: true,
            phase: 'cancelled',
            detail: userMutation
              ? '사용자 프로필 변경을 보존하기 위해 자동 재분석을 취소하고 중간 저장을 되돌렸습니다.'
              : '새 메인 요청을 우선하기 위해 자동 재분석 중간 저장을 안전하게 되돌렸습니다.',
            errors: [],
            finishedAt: Date.now(),
          });
          if (restored) return cacheProfileRefreshState(scope, refreshState);
          return await persistProfileRefreshState(scope, refreshState, { pending, fence: reservationFence });
        }
        if (error?.code === 'EROSYNC_ANALYSIS_CANCELLED' || isStaleLifecycleError(error) || unloaded) return null;
        if (active?.beforeState) {
          try { await restoreAutoProfileSnapshot(active); } catch (restoreError) { warn('automatic profile rollback failed:', restoreError?.message || restoreError); }
        }
        if (error?.code === 'EROSYNC_AUTO_NEEDS_FULL') {
          updateAnalysisRuntime({ running: false, phase: 'idle', detail: '', errors: [], finishedAt: Date.now() });
          return await manualPending('needs_full', '새 인물을 찾아야 할 만큼 자료가 바뀌어 자동 재분석을 하지 않았습니다. 인물 분석을 직접 실행하세요.');
        }
        if (error?.code === 'EROSYNC_PROFILE_VARIANT_CONFLICT') return await manualPending('variant_conflict', '여러 설정 변형이 함께 활성화되어 수동 재분석이 필요합니다.');
        const failureCode = truncate(error?.code || 'provider_error', 80).replace(/[^a-zA-Z0-9_.-]/g, '_');
        const httpStatus = clampInt(error?.status || error?.statusCode, 0, 0, 999);
        updateAnalysisRuntime({ running: false, phase: 'error', detail: `자동 재분석 실패 · ${failureCode}${httpStatus ? ` · HTTP ${httpStatus}` : ''}`, errors: [], finishedAt: Date.now() });
        return await manualPending(`automatic_failed:${failureCode}`, `자동 재분석에 실패해 수동 재분석이 필요합니다. 오류 코드: ${failureCode}${httpStatus ? ` · HTTP ${httpStatus}` : ''}`);
      } finally {
        guard?.dispose();
        if (active && activeAutoProfileRefresh === active) activeAutoProfileRefresh = null;
      }
    })().catch((error) => {
      if (!profileRefreshReservationIsCurrent(pending, reservationFence)) return null;
      warn('post-response profile refresh skipped:', error?.message || error);
      return null;
    });
    return job;
  }

  // 점진 분석 후속(2026-10-31, Erosync.Progressive-Followup.Work-Plan.md): 응답 확정 · 미리 짜기 · 자동 재분석 다음의 백그라운드.
  // (0) 점진 설정인데 준비된 묶음이 없으면 카드만으로 첫 분석을 돌린다. (2) 묶음이 있으면 현재 장면 인물 가운데 자료가 새로 생긴 한 명을 단일 재분석으로 분석한다.
  // 카드만으로 만든 점진 묶음은 전체 자료 해시 대신 묶음의 해시를 범위의 자료 해시로 쓴다(로어·모듈 변화는 인물별 후속 분석이 본다).
  function effectiveSourceHash(config, store, scope, inventory) {
    const full = String(inventory?.sourceHash || '');
    if (config?.profilePreparationMode !== 'progressive') return full;
    const bundle = bundleVariantRecord(store?.sourceBundles?.[scope?.sourceBundleKey || ''], scope?.variantKey || 'default');
    return bundle?.preparation === 'progressive' && bundle.sourceHash ? String(bundle.sourceHash) : full;
  }
  // 단일 재분석의 자료 고르기: 이름·별칭이 제목이나 본문에 든 자료(메인은 카드 포함). 후속 분석의 서명도 같은 목록으로 만든다.
  function singleReanalysisDocumentsByName(profile, inventory) {
    const names = candidateNames(profile).filter(name => name.length >= 2);
    return (inventory?.documents || []).filter(document => (profile.isMain && document.kind === 'character_card')
      || names.some(name => `${document.label || ''}\n${document.text || ''}`.toLowerCase().includes(name)));
  }
  async function markFollowUp(profileId, patch) {
    await mutateProfileRegistry('progressive follow-up mark', fresh => {
      const root = fresh.profiles?.[profileId];
      if (!isPlainObject(root)) return;
      root.followUp = normalizeFollowUp({ ...patch, at: new Date().toISOString() });
    }, { writeRegistry: false });
  }
  function progressiveFollowUpBlocked(config) {
    if (transferBusy || stateRecoveryFault || settingsResetInProgress || unloaded) return 'busy';
    if (config?.profilePreparationMode !== 'progressive') return 'mode';
    if (analysisRuntime.running || profileCompilePromises.size > 0 || verificationPromises.size > 0 || activeAutoProfileRefresh) return 'analysis';
    if (resolveRoleProfile(config, 'profile').providerId === 'risu') return 'provider';
    return '';
  }
  // (0) 첫 분석: 카드 문서만으로 전체 분석 길을 돈다(전체 분석과 같은 호출, 자료만 카드). 선택 로어 봇은 고른 자료만 분석하므로 돌리지 않는다.
  async function runProgressiveBootstrap(character, scope, config, inventory) {
    if (inventory?.analysisWorkflow === 'selected_lore') return null;
    const cardDocuments = (inventory?.documents || []).filter(document => document.kind === 'character_card');
    if (!cardDocuments.length) return null;
    const minimalInventory = { ...inventory, documents: cardDocuments, counts: { character_card: cardDocuments.length },
      totalChars: cardDocuments.reduce((sum, document) => sum + Number(document.chars || 0), 0),
      sourceHash: fnv1a(cardDocuments.map(document => `${document.originId}:${document.hash}`).join('|')), partial: false,
      deferredDocuments: Math.max(0, (inventory.documents || []).length - cardDocuments.length) };
    const assignment = resolveRoleProfile(config, 'profile');
    const guard = createRequestGuard(Math.max(30000, providerAttemptLimitMs(assignment) * 5), 'progressive bootstrap');
    try {
      await compileProfilesFromInventory(character, scope, config, minimalInventory, { force: true, progressiveBootstrap: true, fullDiscovery: true, requestGuard: guard });
      invalidateUiInventory(scope.sourceBundleKey);
      return { kind: 'bootstrap', documents: cardDocuments.length };
    } finally { guard.dispose(); }
  }
  async function scheduleProgressiveFollowUp(pending) {
    try {
      if (!pending?.scope) return null;
      const config = await loadConfig();
      if (progressiveFollowUpBlocked(config)) return null;
      const character = await R.getCharacter();
      const live = character ? await resolveScope(character) : null;
      if (!live || live.scopeKey !== pending.scope.scopeKey || live.sourceBundleKey !== pending.scope.sourceBundleKey || live.chat?.isStreaming === true) return null;
      const inventory = await collectSourceInventory(character, live, { force: true, maxSourceChars: config.analysisMaxSourceChars });
      const store = await loadProfileStore();
      live.variantKey = resolveInventoryVariantKey(safeClone(store) || store, live.sourceBundleKey, inventory);
      live.variantLabel = String(inventory.variantLabel || live.variantKey);
      live.moduleSelectionRevision = clampInt(inventory.moduleSelectionRevision, 0, 0, 1000000000);
      inventory.variantKey = live.variantKey;
      live.sourceHash = effectiveSourceHash(config, store, live, inventory);
      if (detectVariantConflict(store, live.sourceBundleKey, inventory)) return null;
      const bundle = bundleVariantRecord(store.sourceBundles?.[live.sourceBundleKey], live.variantKey);
      if (!bundle || !(Array.isArray(bundle.characterIds) && bundle.characterIds.length)) {
        if (bundle?.status === 'running') return null;
        return await runProgressiveBootstrap(character, live, config, inventory);
      }
      if (config.progressiveFollowUp === false) return null;
      const [registry, state] = await Promise.all([loadRegistry(), loadExistingSession(pending.scope)]);
      if (!state) return null;
      const identity = bindRuntimeIdentity(registry, store, state, live);
      const progressiveBundle = bundle.preparation === 'progressive';
      const members = new Set(bundle.characterIds || []);
      const ids = [...new Set([...(state.scene?.presentAtEnd || []), ...(state.scene?.nextCastForecast?.confirmed || [])])].filter(id => id && id !== 'user' && identity.allowed(id));
      for (const id of ids) {
        const root = store.profiles?.[id];
        if (!isPlainObject(root)) continue;
        const mob = ['temporary_mob', 'persistent_mob'].includes(root.category);
        if (!mob && !(progressiveBundle && members.has(id))) continue;
        if (root.roster?.personKey || root.selectedLore?.entries?.length) continue;
        const profile = materializeProfileVariant(root, live.variantKey) || root;
        if (profile.locked && normalizeProfileLockOrigin(profile.lockOrigin, true) !== 'roster_auto') continue;
        const documents = singleReanalysisDocumentsByName(profile, inventory);
        const signature = followUpSignature(documents);
        if (root.followUp?.signature === signature) continue;
        const fresh = documents.filter(document => document.kind !== 'character_card');
        if (!fresh.length) { await markFollowUp(id, { signature, status: 'no_sources', documents: 0 }); continue; }
        const analyzed = new Set(profile.sourceDocumentIds || []);
        if (profile.analysisStatus === 'ready' && documents.length === analyzed.size && documents.every(document => analyzed.has(document.id))) {
          await markFollowUp(id, { signature, status: 'done', documents: documents.length });
          continue;
        }
        const context = { isLiveScope: true, character, scope: live, config, session: state, lifecycleEpoch: pending.lifecycleEpoch };
        const result = await startSingleProfileReanalysis(context, id, 'full', { config, label: '후속 분석', auditReason: '채팅하며 후속 분석', followUp: { signature, documents: documents.length } });
        if (result?.status !== 'success') await markFollowUp(id, { signature, status: 'error', documents: documents.length }).catch(() => {});
        return { kind: 'followUp', profileId: id, status: result?.status || 'error' };
      }
      return null;
    } catch (error) {
      if (isStaleLifecycleError(error)) return null;
      warn('progressive follow-up skipped:', error?.message || error);
      return null;
    }
  }

  // 확정된 응답(messageIndex)까지의 실제 대화 턴 수. 비활성 메시지는 세지 않고, 사용자 입력 → 응답 한 쌍이 1턴이다.
  // 살아 있는 채팅을 우선 읽고, 못 읽으면 요청 때 담아 둔 채팅으로 센다. 확정 자리가 아직 비어 있으면 그 응답을 한 턴으로 더한다.
  async function committedDialogueTurn(scope, messageIndex) {
    if (!Number.isInteger(messageIndex) || messageIndex < 0) return 0;
    let messages = Array.isArray(scope?.chat?.message) ? scope.chat.message : null;
    try {
      const character = await R.getCharacter();
      const live = character ? await resolveScope(character) : null;
      if (live?.scopeKey === scope?.scopeKey && Array.isArray(live.chat?.message)) messages = live.chat.message;
    } catch (_) { /* 담아 둔 채팅으로 센다 */ }
    if (!messages) return 0;
    let pendingUser = false, turns = 0;
    for (const message of messages.slice(0, messageIndex)) {
      if (!message || message.disabled === true || message.enabled === false || !chatMessageText(message).trim()) continue;
      if (message.role === 'user') pendingUser = true;
      else if (['char', 'assistant'].includes(message.role) && pendingUser) { turns += 1; pendingUser = false; }
    }
    return pendingUser ? turns + 1 : turns;
  }

  async function commitSuccessfulTurn(pending, content, messageIndex = -1, messageId = '', swipeId = null) {
    if (!pending?.scope) return;
    if (pending.preparationPromise) await pending.preparationPromise;
    const commitFence = isPlainObject(pending.backgroundFence) ? pending.backgroundFence : captureBackgroundFence(pending.scope);
    const outputHash = commitContentHash(content);
    const idempotencyKey = `${pending.scope.scopeKey}:${String(pending.commitId || pending.requestId || '')}:${String(messageId || messageIndex)}:${outputHash}`;
    if (committedOutputKeys.has(idempotencyKey)) return;
    committedOutputKeys.add(idempotencyKey);
    if (committedOutputKeys.size > 500) {
      const first = committedOutputKeys.values().next().value;
      if (first) committedOutputKeys.delete(first);
    }
    let lookaheadBase = null;
    try {
      await enqueueScopeSessionWrite(pending.scope, async () => {
        assertBackgroundFence(commitFence, 'committed output start');
        if (unloaded || pending.lifecycleEpoch !== lifecycleEpoch || pending.epoch !== currentScopeEpoch(pending.scope)) {
          throw new Error('stale committed output discarded');
        }
        const config = await loadConfig();
        debug(config, 'committing finalized output', { requestId: pending.requestId, commitId: pending.commitId, scopeKey: pending.scope.scopeKey, messageIndex });
        const [originalProfileStore, originalRegistry, storedState] = await Promise.all([loadProfileStore(), loadRegistry(), loadExistingSession(pending.scope)]);
        const originalState = storedState || (() => {
          const state = newSessionState(pending.scope.scopeKey);
          state.scopeMeta = scopeCatalogSummary(pending.scope, state);
          state.variantKey = String(pending.scope.variantKey || 'default');
          return state;
        })();
        assertBackgroundFence(commitFence, 'committed output state read');
        const profileStore = projectProfileStoreVariant(safeClone(originalProfileStore) || originalProfileStore, pending.scope.sourceBundleKey, pending.scope.variantKey);
        const registry = safeClone(originalRegistry) || originalRegistry;
        const state = normalizeSessionState(safeClone(originalState), pending.scope.scopeKey, config);
        const currentBaseCommit = latestCommitJournalEntry(state);
        const expectedBaseMatches = pending.baseCommitId
          ? currentBaseCommit?.commitId === pending.baseCommitId
            && currentBaseCommit?.contentHash === pending.baseContentHash
            && state.turnIndex === pending.baseTurnIndex
          : !currentBaseCommit;
        const canRebaseAfterResync = pending.resyncRebase === true
          && pending.decision?.type !== 'ACT'
          && !pending.injection;
        if (!expectedBaseMatches && !canRebaseAfterResync) throw new Error('stale main response discarded because its base commit changed');
        if ((state.commitJournal || []).some((entry) => entry?.commitId === pending.commitId)) return;
        const undo = beginCommitRecorder(state);
        if (pending.scope.userIdentity) state.userIdentity = normalizeUserIdentity(pending.scope.userIdentity);
        // 관측 턴은 확정된 응답까지의 실제 대화 턴에 맞춘다(위치를 모르면 0 → 이전 값 + 1 규칙).
        const dialogueTurn = await committedDialogueTurn(pending.scope, messageIndex);
        // 확정 직전의 최신 상태를 기준으로 요청별 되돌리기 기록을 만듭니다.
        withCommitRecorder(undo, () => {
          const plannedTurn = canRebaseAfterResync ? state.turnIndex + 1 : Number(pending.plannedTurn || 0);
          state.turnIndex = Math.max(state.turnIndex + 1, plannedTurn, dialogueTurn);
          state.lastPlan = {
            type: pending.decision.type,
            reason: pending.decision.reason,
            actions: safeClone(pending.decision.actions),
            forecast: safeClone(pending.forecast),
            sceneAssessment: safeClone(pending.sceneAssessment),
            externalSources: normalizeStringList(pending.externalSources, 30, 120),
          };
          state.lastInjection = truncate(pending.injection, MAX_INJECTION_CHARS);
          state.preparedLookahead = null;
          state.lastCommittedOutput = truncate(stripTechnicalArtifacts(content), 7000);
          state.lastCommittedMessageIndex = Number.isInteger(messageIndex) ? messageIndex : -1;
          // 수동 판단(2026-10-31) 2절 1항: 따라잡기 확정이면 기록 한 줄
          if (isPlainObject(pending.manualCatchUp)) appendEvent(state, { type: 'scene_manual', manual: true, summary: `수동 따라잡기 · 건너뛴 응답 ${Number(pending.manualCatchUp.skipped || 0)}개` }, config);
          syncKocoState(state, kocoCommittedSnapshot(pending.scope, content, { messageId, messageIndex }), pending.botOverride?.koco, profileStore, registry, config);
          commitPlannedGoals(state, pending.decision);
          duskTempRecord(state);
          // 확률 탈락 계획(2026-10-22, 계획서 7절): 장면 판단이 제안했으나 실행 확률(또는 대상의 원함)에서 떨어진 행동을 기록으로 남긴다(판단 입력에는 넣지 않는다).
          for (const item of Array.isArray(pending.decision.dropped) ? pending.decision.dropped : []) {
            appendEvent(state, { type: 'plan_dropped', actor: item.actor, target: item.target, mode: item.mode, intent: item.intent, gate: item.gate, activationChance: item.activationChance, roll: item.roll,
              ...(item.goalType ? { goalType: item.goalType } : {}), summary: `${item.gate === 'desire' ? '원함' : '실행 확률'} ${item.activationChance} · 굴림 ${item.roll} · 이번 턴은 실행하지 않음` }, config);
          }
          if (pending.decision.type === 'ACT') {
            for (const action of pending.decision.actions) {
              appendEvent(state, {
                type: 'decision',
                decisionType: 'ACT',
                actor: action.actor,
                target: action.target,
                mode: action.mode,
                goalId: action.goal?.goalId || '',
                goalType: action.goal?.type || '',
                desire: action.goal?.desire ?? null,
                ...(action.intent ? { intent: action.intent } : {}),
                summary: action.goal?.nextMove || action.goal?.objective || action.style || action.mode,
              }, config);
            }
          } else {
            appendEvent(state, {
              type: 'decision',
              decisionType: pending.decision.type,
              summary: pending.decision.reason || pending.decision.type,
            }, config);
          }
        });
        const verifiedIndex = Number.isInteger(messageIndex) && messageIndex >= 0;
        const committedId = pending.commitId || `commit_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
        appendCommitJournal(state, {
          commitId: committedId,
          messageIndex: verifiedIndex ? messageIndex : -1,
          messageId: String(messageId || ''),
          contentHash: outputHash,
          currentContentHash: outputHash,
          narrativeHash: commitNarrativeHash(content),
          ...(Number.isInteger(swipeId) ? { swipeId } : {}),
          directorObservationApplied: false,
          ...(pending.scope.userIdentity ? { userIdentity: normalizeUserIdentity(pending.scope.userIdentity) } : {}),
          userInputHash: String(pending.userInputHash || ''),
          currentUserInputHash: String(pending.userInputHash || ''),
          userMessageId: String(pending.userMessageId || ''),
          turnKey: String(pending.turnKey || ''),
          requestSlotKey: String(pending.requestSlotKey || pending.turnKey || ''),
          turnIndex: state.turnIndex,
          unverified: !verifiedIndex,
          at: new Date().toISOString(),
          undo,
        });
        try {
          assertBackgroundFence(commitFence, 'committed output durable write');
          await saveSession(pending.scope, state, { awaitCatalog: false, fence: commitFence });
          assertBackgroundFence(commitFence, 'committed output durable completion');
          lookaheadBase = {
            commitId: committedId,
            contentHash: outputHash,
            turnIndex: state.turnIndex,
            epoch: pending.epoch,
            lifecycleEpoch: pending.lifecycleEpoch,
            backgroundFence: commitFence,
            lookaheadEligible: pending.lookaheadEligible === true,
            profileSourceIds: safeClone(pending.profileSourceIds),
            botOverride: safeClone(await getBotOverride(pending.scope.sourceBundleKey)),
            profileStore: safeClone(profileStore),
            registry: safeClone(registry),
            state: safeClone(state),
          };
          debug(config, 'finalized output committed', { commitId: pending.commitId, turnIndex: state.turnIndex, messageIndex });
          lastCommitAt = Date.now(); // 수동 판단(2026-10-31): 연결 상태 줄
        } catch (error) {
          if (!backgroundFenceIsCurrent(commitFence) || isStaleLifecycleError(error)) throw staleLifecycleError('committed output');
          await Promise.allSettled([
            saveSession(pending.scope, normalizeSessionState(originalState, pending.scope.scopeKey, config), { awaitCatalog: false, fence: commitFence }),
          ]);
          throw error;
        }
      });
    } catch (error) {
      committedOutputKeys.delete(idempotencyKey);
      throw error;
    }
    const lookaheadPending = lookaheadBase ? { ...pending, scope: { ...pending.scope, planningSignature: planningSettingsSignature(
      configCache || DEFAULT_CONFIG, lookaheadBase.botOverride, lookaheadBase.profileStore, pending.scope.sourceBundleKey, pending.scope.variantKey,
    ) } } : pending;
    // Dusk 2.1.4: 계획 미리 짜기·인물 재분석·비하인드를 잠깐 미룬다 — 그 사이 다시 생성(검열·중지로 잘린 응답)하면 잘린 응답 몫은 건너뛴다.
    const lookaheadJob = lookaheadDelay.delay(pending.scope.scopeKey, () => (lookaheadBase ? queueNextTurnLookahead(lookaheadPending, content, lookaheadBase) : null));
    const skipped = (value) => value === LOOKAHEAD_CANCELLED;
    const refreshJob = lookaheadJob.then(
      (value) => (skipped(value) ? LOOKAHEAD_CANCELLED : schedulePostResponseProfileRefresh(pending)),
      () => schedulePostResponseProfileRefresh(pending),
    );
    // 점진 분석 후속(2026-10-31, Erosync.Progressive-Followup.Work-Plan.md): 자동 재분석 자리 다음에 첫 분석 또는 등장 인물 한 명 분석
    const followUpJob = refreshJob.then((value) => (skipped(value) ? LOOKAHEAD_CANCELLED : scheduleProgressiveFollowUp(pending)), () => scheduleProgressiveFollowUp(pending));
    const scheduleBehindNow = () => queueBehindScene(pending, content).catch((error) => warn('behind-scene generation skipped:', error?.message || error));
    const scheduleBehind = (value) => (skipped(value) ? null : scheduleBehindNow());
    if (!pending.profileRefresh?.needed) followUpJob.then(scheduleBehind, scheduleBehind);
    else {
      Promise.resolve(loadConfig()).then((config) => {
        const profileProviderId = resolveRoleProfile(config, 'profile').providerId;
        const behindRole = config.behindUseSeparateModel ? 'behind' : 'director';
        const behindProviderId = resolveRoleProfile(config, behindRole).providerId;
        if (profileProviderId === behindProviderId) return followUpJob.then(scheduleBehind, scheduleBehind);
        return lookaheadJob.then(scheduleBehind, scheduleBehind);
      }).catch((error) => warn('behind-scene scheduling skipped:', error?.message || error));
    }
  }


  async function loadBehindScenes(scope, options = {}) {
    const key = behindStorageKey(scope);
    const read = await pluginStorageReadState(key);
    if (read.status === 'read_failed' || read.status === 'malformed' || (read.status === 'ok' && (!isPlainObject(read.value) || (read.value.entries !== undefined && !Array.isArray(read.value.entries))))) {
      const invalid = read.status === 'ok' ? { ...read, status: 'malformed' } : read;
      if (options.strict === true) throw storageReadError(key, invalid, read.status === 'ok' ? 'unexpected stored value shape' : '');
      warn('behind-scene storage read failed; existing records were not overwritten:', key, invalid.error?.message || invalid.status);
      return { schemaVersion: 1, entries: [], updatedAt: null, storageFault: invalid.status };
    }
    const value = read.status === 'ok' ? read.value : null;
    return {
      schemaVersion: 1,
      entries: (Array.isArray(value?.entries) ? value.entries : []).filter(isPlainObject).slice(-30),
      updatedAt: value?.updatedAt || null,
    };
  }

  async function removeBehindScenesForCommits(scope, commitIds) {
    const ids = new Set((commitIds || []).filter(Boolean));
    if (ids.size === 0) return;
    bumpBehindGeneration('chat', scope?.sourceBundleKey || '', scope?.scopeKey || '');
    const fence = captureBehindFence(scope);
    await enqueueBehindWrite(scope, async () => {
      assertBehindFence(fence, 'Behind rollback cleanup start');
      const store = await loadBehindScenes(scope, { strict: true });
      assertBehindFence(fence, 'Behind rollback cleanup read');
      const next = store.entries.filter((entry) => !ids.has(entry.commitId));
      if (next.length === store.entries.length) return;
      store.entries = next;
      store.updatedAt = new Date().toISOString();
      assertBehindFence(fence, 'Behind rollback cleanup write');
      await pluginStorageSet(behindStorageKey(scope), store);
      assertBehindFence(fence, 'Behind rollback cleanup completion');
    });
  }

  function enqueueBehindWrite(scope, task) {
    const key = behindStorageKey(scope);
    const previous = behindWriteQueues.get(key) || Promise.resolve();
    const run = previous.catch(() => {}).then(task);
    const settled = run.finally(() => {
      if (behindWriteQueues.get(key) === settled) behindWriteQueues.delete(key);
    });
    behindWriteQueues.set(key, settled);
    settled.catch(() => {});
    return run;
  }

  async function queueBehindScene(pending, finalContent) {
    if (!pending?.commitId || !pending?.scope) return;
    const fence = isPlainObject(pending.behindFence) ? pending.behindFence : captureBehindFence(pending.scope);
    if (Number.isInteger(pending.lifecycleEpoch) && pending.lifecycleEpoch !== lifecycleEpoch) throw staleLifecycleError('Behind scheduling');
    assertBehindFence(fence, 'Behind scheduling');
    const config = await loadConfig();
    assertBehindFence(fence, 'Behind configuration');
    if (!config.behindEnabled) return;
    await ensureBehindOwnership(pending.scope, pending.scope.variantKey || 'default');
    assertBehindFence(fence, 'Behind ownership registration');
    const jobKey = `${pending.scope.scopeKey}:${pending.commitId}`;
    if (behindPromises.has(jobKey)) return await behindPromises.get(jobKey);
    let job = null;
    job = (async () => {
      assertBehindFence(fence, 'Behind model start');
      const prompt = JSON.stringify({
        userInput: truncate(pending.userInputText, 3000),
        erosyncPlan: {
          type: pending.decision?.type,
          reason: pending.decision?.reason,
          actions: pending.decision?.actions || [],
        },
        finalCommittedResponse: truncate(stripTechnicalArtifacts(finalContent), 6000),
      }, null, 2);
      const raw = await runJsonTask(
        buildBehindSystemPrompt(config.behindLanguage),
        prompt,
        config,
        config.behindUseSeparateModel ? 'behind' : 'director',
        'behind scene',
        { executionRole: 'behind' },
      );
      assertBehindFence(fence, 'Behind model return');
      const text = truncate(raw?.text, 600).trim();
      if (!text || text.toLowerCase() === 'null') return;
      await enqueueBehindWrite(pending.scope, async () => {
        assertBehindFence(fence, 'Behind durable apply start');
        const session = await loadExistingSession(pending.scope);
        assertBehindFence(fence, 'Behind session read');
        if (!session) return;
        const commit = (session.commitJournal || []).find((entry) => entry?.commitId === pending.commitId);
        if (!commit || commit.contentHash !== commitContentHash(finalContent)) return;
        const store = await loadBehindScenes(pending.scope, { strict: true });
        assertBehindFence(fence, 'Behind record read');
        const record = {
          id: `behind_${fnv1a(`${pending.scope.scopeKey}:${pending.commitId}`)}`,
          commitId: pending.commitId,
          contentHash: commit.contentHash,
          turn: commit.turnIndex,
          text,
          createdAt: new Date().toISOString(),
        };
        store.entries = [...store.entries.filter((entry) => entry.commitId !== pending.commitId), record].slice(-30);
        store.updatedAt = new Date().toISOString();
        assertBehindFence(fence, 'Behind record write');
        await pluginStorageSet(behindStorageKey(pending.scope), store);
        if (!behindFenceIsCurrent(fence)) {
          if (backgroundFenceResetInvalidated(fence)) await pluginStorageRemove(behindStorageKey(pending.scope));
          throw staleLifecycleError('Behind record completion');
        }
        scheduleUiRefresh();
      });
    })().finally(() => {
      if (behindPromises.get(jobKey) === job) behindPromises.delete(jobKey);
    });
    behindPromises.set(jobKey, job);
    return await job;
  }

  function pruneDecisionCache() {
    if (decisionCache.size <= 8) return;
    const keys = [...decisionCache.keys()];
    for (let index = 0; index < keys.length - 4; index += 1) decisionCache.delete(keys[index]);
  }

  function currentScopeEpoch(scope) {
    return clampInt(scopeDecisionEpochs.get(scope?.scopeKey) || 0, 0, 0, 100000000);
  }

  function invalidateAllPreparedDecisionState(reason = 'planning inputs changed', options = {}) {
    queuePreparedPlanInvalidation();
    if (replanTimer) clearTimeout(replanTimer);
    replanTimer = null;
    const code = /backup|import/i.test(reason) ? 'BACKUP_IMPORT_CANCELLED' : /reset/i.test(reason) ? 'DATA_RESET'
      : /configuration/i.test(reason) ? 'CONFIG_CHANGED' : /bot settings/i.test(reason) ? 'BOT_SETTINGS_CHANGED' : 'PLANNING_INPUT_CHANGED';
    cancelDirectorAttempts(code);
    preparedDecisionGeneration += 1;
    for (const guard of lookaheadGuards.values()) guard?.abort(Object.assign(new Error(reason), { code: 'EROSYNC_STALE_LOOKAHEAD', directorCode: code }));
    lookaheadGuards.clear();
    decisionPromises.clear();
    decisionCache.clear();
    if (/reset|backup|restore|recovery/i.test(reason)) lookaheadContexts.clear();
    if (options.replan === true) scheduleLiveLookahead();
  }

  function invalidateDecisionStateForScope(scope, extraTurnKeys = [], keepRequestId = '') {
    queuePreparedPlanInvalidation(scope);
    cancelDirectorAttempts('CHAT_CHANGED', scope?.scopeKey || '');
    const prefix = `${scope?.scopeKey || ''}:`;
    const keys = new Set(normalizeStringList(extraTurnKeys, 100, 300));
    for (const key of decisionCache.keys()) if ((prefix && key.startsWith(prefix)) || keys.has(key)) decisionCache.delete(key);
    for (const key of decisionPromises.keys()) {
      if (!((prefix && key.startsWith(prefix)) || keys.has(key))) continue;
      lookaheadGuards.get(key)?.abort(Object.assign(new Error('post-commit look-ahead invalidated by chat state change'), { code: 'EROSYNC_STALE_LOOKAHEAD', directorCode: 'CHAT_CHANGED' }));
      lookaheadGuards.delete(key);
      decisionPromises.delete(key);
    }
    const { queue } = pendingQueueForCoordinates(scope);
    for (const pending of [...queue]) if (pending?.requestId !== keepRequestId) removePendingContext(pending);
    scopeDecisionEpochs.set(scope.scopeKey, currentScopeEpoch(scope) + 1);
  }

  function resyncFenceIsCurrent(scope, token) {
    return !unloaded
      && token?.lifecycleEpoch === lifecycleEpoch
      && token?.scopeEpoch === currentScopeEpoch(scope)
      && backgroundFenceIsCurrent(token?.backgroundFence);
  }

  function assertResyncFence(scope, token, stage = 'chat resync') {
    if (resyncFenceIsCurrent(scope, token)) return;
    const error = new Error(`stale ${stage} discarded`);
    error.code = 'EROSYNC_STALE_RESYNC';
    throw error;
  }

  function scheduleChatResync(scope, chatMessages, turnKey, requestSlotKey, preview = null) {
    const scopeSnapshot = safeClone({ ...scope, chat: null }) || { ...scope, chat: null };
    const scopeKey = String(scopeSnapshot?.scopeKey || '');
    if (!scopeKey) return Promise.resolve(null);
    const chatSnapshot = (Array.isArray(chatMessages) ? chatMessages : []).map((message) => ({
      role: message?.role,
      data: chatMessageText(message),
      id: message?.id, messageId: message?.messageId, chatId: message?.chatId,
      swipeId: message?.swipeId,
    }));
    const editOnly = preview?.reason === 'postprocess';
    const activeResync = resyncPromises.get(scopeKey);
    if (activeResync && (editOnly || activeResync.erosyncKind !== 'postprocess')) return activeResync;

    if (!editOnly) invalidateDecisionStateForScope(scopeSnapshot, [turnKey, ...(preview?.removedTurnKeys || [])]);
    const token = {
      lifecycleEpoch,
      scopeEpoch: currentScopeEpoch(scopeSnapshot),
      backgroundFence: captureBackgroundFence(scopeSnapshot),
    };

    const coordinated = enqueueCoordinatedStateWrite(scopeSnapshot, async () => {
      assertResyncFence(scopeSnapshot, token, 'chat resync start');
      const config = await loadConfig();
      assertResyncFence(scopeSnapshot, token, 'chat resync configuration');
      const [originalProfileStore, originalRegistry, originalState] = await Promise.all([
        loadProfileStore(),
        loadRegistry(),
        loadExistingSession(scopeSnapshot),
      ]);
      assertResyncFence(scopeSnapshot, token, 'chat resync state read');
      if (!originalState) return null;

      const profileStore = safeClone(originalProfileStore) || originalProfileStore;
      const registry = safeClone(originalRegistry) || originalRegistry;
      const state = normalizeSessionState(safeClone(originalState), scopeKey, config);
      const result = syncCommitJournalWithChat(state, registry, profileStore, chatSnapshot, turnKey, requestSlotKey, config);
      if (!result) return null;
      if (editOnly && result.reason !== 'postprocess') return null;
      assertResyncFence(scopeSnapshot, token, 'chat resync recompute');

      try {
        assertResyncFence(scopeSnapshot, token, 'chat resync profile write');
        const durableState = prepareSessionForSave(scopeSnapshot, state);
        const writes = editOnly
          ? [{ key: `${SESSION_KEY_PREFIX}${scopeSnapshot.scopeKey}`, value: durableState }]
          : [
            { key: PROFILE_STORE_KEY, value: normalizeProfileStore(profileStore) },
            { key: REGISTRY_STORE_KEY, value: normalizeRegistryStore(registry) },
            { key: `${SESSION_KEY_PREFIX}${scopeSnapshot.scopeKey}`, value: durableState },
          ];
        await commitStateTransactionWithinLock(editOnly ? 'chat body edit reconcile' : 'chat resync apply', writes, { fence: token.backgroundFence });
        Object.assign(state, safeClone(durableState) || durableState);
        assertResyncFence(scopeSnapshot, token, 'chat resync session write');
        upsertScopeCatalog(scopeSnapshot, state, {
          profileCount: profileStore.sourceBundles?.[scopeSnapshot.sourceBundleKey]?.characterIds?.length || 0,
          mobCount: Object.values(registry.entities || {}).filter((entity) => entity?.scopeKey === scopeSnapshot.scopeKey && ['temporary_mob', 'persistent_mob'].includes(entity.category)).length,
        }, token.backgroundFence).catch((error) => warn('scope catalog update failed:', error?.message || error));
      } catch (error) {
        throw error;
      }
      return result;
    });

    let tracked = null;
    tracked = coordinated.then(async (result) => {
      if (result?.removedCommitIds?.length && resyncFenceIsCurrent(scopeSnapshot, token)) {
        observeCompatibility('invalidate', scopeSnapshot, result.removedCommitIds || []);
        try { await removeBehindScenesForCommits(scopeSnapshot, result.removedCommitIds || []); }
        catch (error) { warn('resync behind-scene cleanup skipped:', error?.message || error); }
      }
      if (result?.reason === 'swipe' && !turnKey && !requestSlotKey && resyncFenceIsCurrent(scopeSnapshot, token)) {
        await observeSelectedSwipe(scopeSnapshot, chatSnapshot, result.selectedReplacement);
      }
      return result;
    }).catch((error) => {
      if (!unloaded && error?.code !== 'EROSYNC_STALE_RESYNC') warn('background chat resync skipped:', error?.message || error);
      return null;
    }).finally(() => {
      if (resyncPromises.get(scopeKey) === tracked) resyncPromises.delete(scopeKey);
    });
    tracked.erosyncKind = editOnly ? 'postprocess' : 'rollback';
    resyncPromises.set(scopeKey, tracked);
    return tracked;
  }

  async function observeSelectedSwipe(scope, chatSnapshot, selected) {
    if (!selected || unloaded) return;
    const character = await R.getCharacter();
    const liveScope = character ? await resolveScope(character) : null;
    if (!liveScope || liveScope.scopeKey !== scope.scopeKey) return;
    const current = latestChatCommit(liveScope.chat?.message);
    if (!current || current.index !== selected.index || current.id !== selected.id
      || current.swipeId !== selected.swipeId) return;
    const config = await loadConfig();
    if (!config.enabled || config.mode === 'off') return;
    const [profileStore, state, botOverride] = await Promise.all([
      loadProfileStore(), loadExistingSession(scope), getBotOverride(scope.sourceBundleKey),
    ]);
    if (!state) return;
    const bundle = bundleVariantRecord(profileStore.sourceBundles?.[scope.sourceBundleKey], scope.variantKey);
    const profileSourceIds = preparedProfileIdsForBundle(bundle, profileStore, scope.variantKey);
    const conversation = recentConversation((liveScope.chat?.message || []).map(message => ({
      role: message?.role, content: chatMessageText(message),
    })), config.recentMessages);
    const pendingScope = { ...scope, chat: liveScope.chat };
    const pending = {
      commitId: `commit_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
      requestId: `swipe_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
      decision: safePassThroughDecision('Selected existing response is observed after the previous swipe was rolled back.'),
      forecast: safeClone(state.scene?.nextCastForecast || {}),
      sceneAssessment: { category: 'other', relationalOpportunity: false, reason: 'selected swipe' },
      injection: '', plannedTurn: state.turnIndex + 1, baseCommitId: '', baseContentHash: '', baseTurnIndex: state.turnIndex,
      profileSourceIds, externalSources: [], epoch: currentScopeEpoch(pendingScope), scope: pendingScope,
      turnKey: buildTurnKey(pendingScope, conversation), requestSlotKey: buildRequestSlotKey(pendingScope, conversation),
      userInputHash: current.userInputHash, userMessageId: current.userMessageId,
      lifecycleEpoch, backgroundFence: captureBackgroundFence(pendingScope), behindFence: captureBehindFence(pendingScope),
      botOverride: safeClone(botOverride), profileRefresh: null,
      lookaheadEligible: ['complete', 'partial'].includes(bundle?.status)
        && String(bundle.sourceHash || '') === String(scope.sourceHash || '')
        && clampInt(bundle.moduleSelectionRevision, 0, 0, 1000000000) === clampInt(scope.moduleSelectionRevision, 0, 0, 1000000000)
        && profileSourceIds.length > 0,
      lookaheadConversation: safeClone(conversation), lookaheadExternalContext: [],
      resyncRebase: true,
    };
    await commitSuccessfulTurn(pending, chatMessageText(liveScope.chat.message[current.index]), current.index, current.id, current.swipeId);
  }

  function prepareDeferredMainRequest(pending) {
    const scope = pending.scope;
    const task = enqueueCoordinatedStateWrite(scope, async () => {
      if (unloaded || pending.lifecycleEpoch !== lifecycleEpoch || pending.epoch !== currentScopeEpoch(scope)
        || !backgroundFenceIsCurrent(pending.backgroundFence)) throw staleLifecycleError('deferred main request');
      const config = await loadConfig();
      const [originalProfileStore, originalRegistry, originalState] = await Promise.all([
        loadProfileStore(), loadRegistry(), loadExistingSession(scope),
      ]);
      const profileStore = safeClone(originalProfileStore) || originalProfileStore;
      const registry = safeClone(originalRegistry) || originalRegistry;
      const state = normalizeSessionState(safeClone(originalState || newSessionState(scope.scopeKey)), scope.scopeKey, config);
      const result = syncCommitJournalWithChat(state, registry, profileStore, scope.chat?.message, pending.turnKey, pending.requestSlotKey, config);
      if (result?.reason !== 'postprocess' && result) {
        invalidateDecisionStateForScope(scope, [pending.turnKey, ...(result.removedTurnKeys || [])], pending.requestId);
        pending.epoch = currentScopeEpoch(scope);
      }
      if (result) {
        const durableState = prepareSessionForSave(scope, state);
        const writes = result.reason === 'postprocess'
          ? [{ key: `${SESSION_KEY_PREFIX}${scope.scopeKey}`, value: durableState }]
          : [
            { key: PROFILE_STORE_KEY, value: normalizeProfileStore(profileStore) },
            { key: REGISTRY_STORE_KEY, value: normalizeRegistryStore(registry) },
            { key: `${SESSION_KEY_PREFIX}${scope.scopeKey}`, value: durableState },
          ];
        await commitStateTransactionWithinLock('deferred main request reconciliation', writes, { fence: pending.backgroundFence });
        Object.assign(state, safeClone(durableState) || durableState);
      }
      const bundle = bundleVariantRecord(profileStore.sourceBundles?.[scope.sourceBundleKey], scope.variantKey);
      const profileSourceIds = preparedProfileIdsForBundle(bundle, profileStore, scope.variantKey);
      pending.profileSourceIds = profileSourceIds;
      pending.lookaheadEligible = pending.variantConflict !== true && ['complete', 'partial'].includes(bundle?.status)
        && String(bundle.sourceHash || '') === String(scope.sourceHash || '')
        && clampInt(bundle.moduleSelectionRevision, 0, 0, 1000000000) === clampInt(scope.moduleSelectionRevision, 0, 0, 1000000000)
        && profileSourceIds.length > 0;
      pending.baseTurnIndex = state.turnIndex;
      pending.plannedTurn = state.turnIndex + 1;
      pending.forecast = safeClone(state.scene?.nextCastForecast || {});
      return result;
    });
    return task.then(async (result) => {
      if (result?.removedCommitIds?.length && !unloaded) {
        observeCompatibility('invalidate', scope, result.removedCommitIds);
        try { await removeBehindScenesForCommits(scope, result.removedCommitIds); }
        catch (error) { warn('deferred reroll behind-scene cleanup skipped:', error?.message || error); }
      }
      return result;
    });
  }

  function beginFallbackMainObservation(scope, config, profileStore, inventory, cleaned) {
    const conversation = recentConversation(cleaned, config.recentMessages);
    if (!conversation.some(message => message.role === 'user')) return null;
    const bundle = bundleVariantRecord(profileStore.sourceBundles?.[scope.sourceBundleKey], scope.variantKey);
    const profileSourceIds = preparedProfileIdsForBundle(bundle, profileStore, scope.variantKey);
    const variantConflict = detectVariantConflict(profileStore, scope.sourceBundleKey, inventory);
    return enqueuePendingContext({
      commitId: `commit_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
      requestId: `request_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
      decision: safePassThroughDecision('The main request is observed after preparation could not finish within its deadline.'),
      forecast: {}, sceneAssessment: { category: 'other', relationalOpportunity: false, reason: 'preparation deadline' },
      injection: '', plannedTurn: 0, baseCommitId: '', baseContentHash: '', baseTurnIndex: 0,
      profileSourceIds, externalSources: [], epoch: currentScopeEpoch(scope), scope,
      turnKey: buildTurnKey(scope, conversation), requestSlotKey: buildRequestSlotKey(scope, conversation),
      userInputHash: latestUserInputHash(scope, conversation), userMessageId: latestUserMessageId(scope),
      userInputText: truncate([...conversation].reverse().find(message => message.role === 'user')?.content || '', 3000),
      lifecycleEpoch, backgroundFence: captureBackgroundFence(scope), behindFence: captureBehindFence(scope),
      botOverride: null, profileRefresh: null, variantConflict,
      lookaheadEligible: !variantConflict && ['complete', 'partial'].includes(bundle?.status)
        && String(bundle.sourceHash || '') === String(inventory.sourceHash || '')
        && clampInt(bundle.moduleSelectionRevision, 0, 0, 1000000000) === clampInt(inventory.moduleSelectionRevision, 0, 0, 1000000000)
        && profileSourceIds.length > 0,
      lookaheadConversation: safeClone(conversation), lookaheadExternalContext: [],
      resyncRebase: true, createdAt: Date.now(), status: 'awaiting_output',
    });
  }

  function activateFallbackMainObservation(pending) {
    if (!pending || !pendingMainOrder.includes(pending)) return false;
    pending.preparationPromise = prepareDeferredMainRequest(pending);
    pending.preparationPromise.catch((error) => {
      pending.status = 'discarded';
      removePendingContext(pending);
      warn('fallback main request reconciliation failed:', error?.message || error);
    });
    return true;
  }

  async function onBeforeRequest(messages, type) {
    if (unloaded || type !== 'model') return messages;
    if (transferBusy || stateRecoveryFault) return removeOwnInjection(messages);
    const autoRefreshPreempted = preemptAutoProfileRefreshForMain();
    observeCoreHook('beforeRequest');
    const cleaned = removeOwnInjection(messages);
    prunePendingContexts();
    if (autoRefreshPreempted) {
      debug(configCache || DEFAULT_CONFIG, 'active automatic profile refresh was preempted; this main request passed through without injection, resync, or auxiliary work');
      return cleaned;
    }
    if (!coreHooksOperational()) {
      debug(configCache || DEFAULT_CONFIG, 'legacy hook bootstrap is incomplete; main request passed through without pending state, injection, or auxiliary work');
      return cleaned;
    }
    const requestGuard = createRequestGuard(MAIN_REQUEST_DEADLINE_MS, 'beforeRequest');
    let earlyPending = null;
    try {
      const work = (async () => {
        const config = await requestGuard.wait(loadConfig(), 'configuration');
        if (!config.enabled || config.mode === 'off') return cleaned;
        const character = await requestGuard.wait(R.getCharacter(), 'current character');
        if (!character) return cleaned;
        const scope = await requestGuard.wait(resolveScope(character), 'chat scope');
        resetSuppressedUiScopes.delete(scope.scopeKey);
        const inventory = await requestGuard.wait(
          collectSourceInventory(character, scope, { maxSourceChars: config.analysisMaxSourceChars, requestGuard }),
          'source inventory',
        );
        const loadedProfileStoreValue = await requestGuard.wait(loadProfileStore(), 'prepared profile store');
        const loadedProfileStore = safeClone(loadedProfileStoreValue) || loadedProfileStoreValue;
        scope.variantKey = resolveInventoryVariantKey(loadedProfileStore, scope.sourceBundleKey, inventory);
        scope.variantSignature = String(inventory.activationSignature || '');
        scope.sourceHash = effectiveSourceHash(config, loadedProfileStore, scope, inventory); // 점진 분석(2026-10-31): 점진 묶음이면 묶음의 해시
        scope.moduleSelectionRevision = clampInt(inventory.moduleSelectionRevision, 0, 0, 1000000000);
        inventory.variantKey = scope.variantKey;
        scope.variantLabel = String(inventory.variantLabel || scope.variantKey);
        ensureSessionIdentityRepair(scope, config).catch(error => warn('session identity correction deferred:', error?.message || error));
        earlyPending = beginFallbackMainObservation(scope, config, loadedProfileStore, inventory, cleaned);
        const loadedBotOverride = await requestGuard.wait(getBotOverride(scope.sourceBundleKey), 'bot settings');
        const botOverride = safeClone(loadedBotOverride) || loadedBotOverride;
        const variantConflict = detectVariantConflict(loadedProfileStore, scope.sourceBundleKey, inventory);
        const profileRefreshRequest = buildProfileRefreshRequest(config, loadedProfileStore, scope, inventory, variantConflict);
        requestGuard.throwIfAborted('beforeRequest');
        if (botOverride.activeVariantKey !== scope.variantKey) {
          botOverride.activeVariantKey = scope.variantKey;
        }
        scope.planningSignature = planningSettingsSignature(
          config,
          botOverride,
          loadedProfileStore,
          scope.sourceBundleKey,
          scope.variantKey,
        );
        const compatibilityTrace = observeCompatibility('start', scope);
        const compatibleContext = buildCompatibleMessageContext(cleaned, config, compatibilityTrace);
        const mainMessages = cleaned.filter((message) => externalMessageSource(message, compatibleContext.dialogue.some((item) => item?.removable === true)) !== 'technical_debug');
        const conversation = recentConversation(compatibleContext.dialogue, config.recentMessages);
        if (!conversation.some((message) => message.role === 'user')) {
          removePendingContext(earlyPending);
          earlyPending = null;
          return mainMessages;
        }
        const turnKey = buildTurnKey(scope, conversation);
        const requestSlotKey = buildRequestSlotKey(scope, conversation);
        const userInputHash = latestUserInputHash(scope, conversation);
        const userMessageId = latestUserMessageId(scope);
        const userInputText = truncate([...conversation].reverse().find((message) => message.role === 'user')?.content || '', 3000);
        const requestLifecycleEpoch = lifecycleEpoch;
        const requestBackgroundFence = captureBackgroundFence(scope);
        const requestBehindFence = captureBehindFence(scope);
        if (isScopeSessionWriteBusy(scope)) {
          removePendingContext(earlyPending);
          earlyPending = null;
          const pending = enqueuePendingContext({
            commitId: `commit_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
            decision: safePassThroughDecision('The preceding Erosync write is settling; this response is observed after reconciliation.'),
            forecast: {}, sceneAssessment: { category: 'other', relationalOpportunity: false, reason: 'deferred session write' },
            injection: '', plannedTurn: 0, baseCommitId: '', baseContentHash: '', baseTurnIndex: 0,
            profileSourceIds: [], externalSources: compatibleContext.detectedSources,
            epoch: currentScopeEpoch(scope), requestId: `request_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
            scope, turnKey, requestSlotKey, userInputHash, userMessageId, userInputText,
            lifecycleEpoch: requestLifecycleEpoch, backgroundFence: requestBackgroundFence, behindFence: requestBehindFence,
            botOverride: safeClone(botOverride), profileRefresh: safeClone(profileRefreshRequest), lookaheadEligible: false,
            lookaheadConversation: safeClone(conversation), lookaheadExternalContext: safeClone(compatibleContext.external),
            compatibilityTrace, resyncRebase: true, createdAt: Date.now(), status: 'awaiting_output',
          });
          if (pending) {
            pending.preparationPromise = prepareDeferredMainRequest(pending);
            pending.preparationPromise.catch((error) => {
              pending.status = 'discarded';
              removePendingContext(pending);
              warn('deferred main request reconciliation failed:', error?.message || error);
            });
          }
          debug(config, 'scope session write is still pending; main response tracking continues without goal injection', { scopeKey: scope.scopeKey });
          return mainMessages;
        }

        // 메인 요청 경로에서는 저장된 상태와 준비된 look-ahead만 읽습니다.
        // Scene Director나 다른 모델/외부 제공자는 이 훅에서 부르지 않습니다. 예외 하나: 새 입력이 준비된 계획과 어긋난 턴의 긴급 판단
        // (runEmergencyReplan — 사용자 결정 2026-10-13, 설정한 시간까지만 기다리고 못 오면 계획 없이 통과).
        const [loadedRegistry, storedState] = await requestGuard.wait(Promise.all([loadRegistry(), loadExistingSession(scope)]), 'prepared scene state');
        const loadedState = storedState || (() => {
          const state = newSessionState(scope.scopeKey);
          state.scopeMeta = scopeCatalogSummary(scope, state);
          state.variantKey = String(scope.variantKey || 'default');
          return state;
        })();
        let profileStore = safeClone(loadedProfileStore) || loadedProfileStore;
        let registry = safeClone(loadedRegistry) || loadedRegistry;
        let state = normalizeSessionState(safeClone(loadedState), scope.scopeKey, config);
        let resync = null;
        try {
          requestGuard.throwIfAborted('chat resync');
          resync = syncCommitJournalWithChat(state, registry, profileStore, scope.chat?.message, turnKey, requestSlotKey, config);
          requestGuard.throwIfAborted('chat resync');
          if (resync?.reason === 'postprocess') {
            scheduleChatResync(scope, scope.chat?.message, turnKey, requestSlotKey, resync);
          } else if (resync) {
            const resyncPreparedBundle = bundleVariantRecord(profileStore.sourceBundles?.[scope.sourceBundleKey], scope.variantKey);
            const resyncProfileSourceIds = preparedProfileIdsForBundle(resyncPreparedBundle, profileStore, scope.variantKey);
            const resyncLookaheadEligible = !variantConflict
              && ['complete', 'partial'].includes(resyncPreparedBundle?.status)
              && String(resyncPreparedBundle?.sourceHash || '') === String(inventory.sourceHash || '')
              && clampInt(resyncPreparedBundle?.moduleSelectionRevision, 0, 0, 1000000000) === clampInt(inventory.moduleSelectionRevision, 0, 0, 1000000000)
              && resyncProfileSourceIds.length > 0;
            scheduleChatResync(scope, scope.chat?.message, turnKey, requestSlotKey, resync);
            lookaheadDelay.cancel(scope.scopeKey);   // Dusk 2.1.4: 되돌린(다시 생성한) 응답 몫의 미뤄 둔 계획은 짜지 않는다
            const resyncEpoch = currentScopeEpoch(scope);
            earlyPending = null;
            enqueuePendingContext({
              commitId: `commit_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
              decision: safePassThroughDecision('Chat history changed; this response is recorded after background resynchronization without an Erosync action.'),
              forecast: safeClone(state.scene?.nextCastForecast || {}),
              sceneAssessment: { category: 'other', relationalOpportunity: false, reason: 'background chat resync' },
              injection: '',
              plannedTurn: state.turnIndex + 1,
              baseCommitId: '',
              baseContentHash: '',
              baseTurnIndex: state.turnIndex,
              profileSourceIds: resyncProfileSourceIds,
              externalSources: compatibleContext.detectedSources,
              epoch: resyncEpoch,
              requestId: `request_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
              scope,
              turnKey,
              requestSlotKey,
              userInputHash,
              userMessageId,
              userInputText,
              lifecycleEpoch: requestLifecycleEpoch,
              backgroundFence: requestBackgroundFence,
              behindFence: requestBehindFence,
              botOverride: safeClone(botOverride),
              profileRefresh: safeClone(profileRefreshRequest),
              lookaheadEligible: resyncLookaheadEligible,
              lookaheadConversation: safeClone(conversation),
              lookaheadExternalContext: safeClone(compatibleContext.external),
              compatibilityTrace,
              resyncRebase: true,
              createdAt: Date.now(),
              status: 'awaiting_output',
            });
            debug(config, 'chat resync scheduled in background; current main request passed through without Erosync injection', { scopeKey: scope.scopeKey, reason: resync.reason });
            return mainMessages;
          }
        } catch (error) {
          requestGuard.throwIfAborted('chat resync');
          warn('chat resync skipped; existing records kept:', error?.message || error);
        }

        // Dusk 2.1.4: 미뤄 둔 계획이 있으면 지금 시작한다(새 입력). 긴급 판단 대기 시간까지만 기다린다(0이거나 리스 제공자면 기다리지 않음).
        {
          const flushed = lookaheadDelay.flush(scope.scopeKey);
          const waitMs = flushed ? emergencyReplanWaitMs(config) : 0;
          if (flushed && waitMs && resolveRoleProfile(config, 'director').providerId !== 'risu') {
            requestGuard.extend(waitMs + EMERGENCY_FINISH_MS);
            let timer = null;
            await Promise.race([flushed.catch(() => null), new Promise((resolve) => { timer = setTimeout(resolve, waitMs); })]);
            clearTimeout(timer);
          }
        }
        // Resync can roll profiles or mobs back. Bind the prepared decision to
        // that post-resync profile state, not the stale pre-resync snapshot.
        scope.planningSignature = planningSettingsSignature(
          config,
          botOverride,
          profileStore,
          scope.sourceBundleKey,
          scope.variantKey,
        );
        const epoch = currentScopeEpoch(scope);
        const preparedBundle = bundleVariantRecord(profileStore.sourceBundles?.[scope.sourceBundleKey], scope.variantKey);
        const preparedProfileIds = preparedProfileIdsForBundle(preparedBundle, profileStore, scope.variantKey);
        const lookaheadEligible = !variantConflict
          && ['complete', 'partial'].includes(preparedBundle?.status)
          && String(preparedBundle?.sourceHash || '') === String(inventory.sourceHash || '')
          && clampInt(preparedBundle?.moduleSelectionRevision, 0, 0, 1000000000) === clampInt(inventory.moduleSelectionRevision, 0, 0, 1000000000)
          && preparedProfileIds.length > 0;
        if (variantConflict) warn('multiple known profile variants are active together; Erosync injection skipped until lore/module selection is resolved');
        else if (!lookaheadEligible) debug(config, 'active variant has no complete prepared profile set; this turn passes through and no look-ahead model will be started', { scopeKey: scope.scopeKey, variantKey: scope.variantKey, status: preparedBundle?.status || 'missing' });

        profileStore = projectProfileStoreVariant(profileStore, scope.sourceBundleKey, scope.variantKey);
        registry = safeClone(registry) || registry;
        state = normalizeSessionState(safeClone(state), scope.scopeKey, config);
        const runtimeIdentity = bindRuntimeIdentity(registry, profileStore, state, scope);
        const baseCommit = latestCommitJournalEntry(state);
        const cacheKey = baseCommit ? lookaheadCacheKey(scope, baseCommit.commitId, baseCommit.contentHash, epoch) : '';
        const candidate = lookaheadEligible && !resync && cacheKey ? decisionCache.get(cacheKey) : null;
        let cached = candidate
          && candidate.scopeKey === scope.scopeKey
          && candidate.variantKey === String(scope.variantKey || 'default')
          && candidate.variantSignature === String(scope.variantSignature || '')
          && candidate.sourceHash === String(scope.sourceHash || '')
          && clampInt(candidate.moduleSelectionRevision, 0, 0, 1000000000) === clampInt(scope.moduleSelectionRevision, 0, 0, 1000000000)
          && candidate.planningSignature === String(scope.planningSignature || '')
          && candidate.baseCommitId === baseCommit?.commitId
          && candidate.baseContentHash === baseCommit?.contentHash
          && candidate.baseTurnIndex === state.turnIndex
          && candidate.epoch === epoch
          && candidate.lifecycleEpoch === requestLifecycleEpoch
          ? candidate
          : null;
        if (candidate && !cached) decisionCache.delete(cacheKey);
        let preparationBlockReason = !lookaheadEligible ? 'PROFILES_OR_SOURCE_UNPREPARED' : candidate && !cached ? 'MEMORY_PLAN_MISMATCH' : 'STORED_PLAN_MISSING';
        if (cached?.schemaVersion === 1) {
          preparationBlockReason = preparedLookaheadBlockReason(cached, scope, state, requestSlotKey, userInputHash);
          if (preparationBlockReason) cached = null;
        }
        if (!cached && lookaheadEligible && !resync && state.preparedLookahead) {
          const storedPlan = normalizePreparedLookahead(state.preparedLookahead);
          preparationBlockReason = storedPlan ? preparedLookaheadBlockReason(storedPlan, scope, state, requestSlotKey, userInputHash) : 'STORED_PLAN_INVALID';
          const belongsHere = id => runtimeIdentity.allowed(id);
          if (!preparationBlockReason && storedPlan.decision.actions.some(action => !belongsHere(action.actor) || !isProfileDirectorEligible(profileStore.profiles?.[action.actor])
            || !registry.entities?.[action.actor] || (action.target !== 'user' && (!belongsHere(action.target) || !registry.entities?.[action.target])))) preparationBlockReason = 'PLAN_CHARACTER_CHANGED';
          if (!preparationBlockReason) {
            cached = { ...storedPlan, variantSignature: String(scope.variantSignature || ''), epoch, lifecycleEpoch: requestLifecycleEpoch,
              injection: composeInjection(storedPlan.decision, registry, profileStore, state, botOverride) };
            decisionCache.set(cacheKey, cached);
          }
        }
        if (cached?.decision?.actions?.some(action => action.kocoRefs?.length)) {
          const snapshot = scanKocoMessages(scope.chat?.message, scope.scopeKey);
          const remaining = cached.decision.actions.filter(action => !action.kocoRefs?.length || snapshot.complete && kocoRefsValid(action.kocoRefs, state, action.actor, snapshot));
          if (remaining.length !== cached.decision.actions.length) {
            if (!remaining.length) { cached = null; preparationBlockReason = 'KOCO_SOURCE_CHANGED'; }
            else {
              const decision = { ...cached.decision, actions: remaining };
              cached = { ...cached, decision, injection: composeInjection(decision, registry, profileStore, state, botOverride) };
            }
          }
        }
        let inputBlockReason = cached?.decision?.type === 'ACT' && cached.emergencyInputHash !== userInputHash
          ? currentInputLookaheadBlockReason(userInputText, plannedCharacterNames(cached.decision, registry)) : '';
        if (inputBlockReason && lookaheadEligible && !resync) {
          // 긴급 판단: 어긋난 계획을 버리고 새 입력까지 보고 계획만 다시 짜 이번 요청에 넣는다(설정한 시간까지만 기다림, 못 오면 지금처럼 보류)
          const replanned = await requestGuard.wait(runEmergencyReplan({
            config, scope, state, registry, profileStore, botOverride, baseCommit, epoch, lifecycleEpoch: requestLifecycleEpoch,
            backgroundFence: requestBackgroundFence, profileSourceIds: preparedProfileIds, conversation, externalContext: compatibleContext.external,
            externalSources: compatibleContext.detectedSources, userInputHash, reason: inputBlockReason, requestGuard,
          }), 'emergency replan');
          if (replanned) { cached = replanned; inputBlockReason = ''; preparationBlockReason = ''; }
        }
        const decision = cached && !inputBlockReason
          ? safeClone(cached.decision)
          : safePassThroughDecision(inputBlockReason
            ? `Prepared look-ahead was withheld because the new user input signals ${inputBlockReason}.`
            : 'No valid post-commit look-ahead was ready; the main request was passed through immediately.');
        const injection = cached && !inputBlockReason ? String(cached.injection || '') : '';
        const forecast = cached && !inputBlockReason ? safeClone(cached.forecast) : safeClone(state.scene?.nextCastForecast || {});
        const sceneAssessment = cached && !inputBlockReason
          ? safeClone(cached.sceneAssessment)
          : { category: 'other', relationalOpportunity: false, reason: inputBlockReason || 'look-ahead unavailable' };
        removePendingContext(earlyPending);
        earlyPending = null;
        const pending = enqueuePendingContext({
          commitId: `commit_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
          decision,
          forecast,
          sceneAssessment,
          injection,
          plannedTurn: state.turnIndex + 1,
          baseCommitId: String(baseCommit?.commitId || ''),
          baseContentHash: String(baseCommit?.contentHash || ''),
          baseTurnIndex: state.turnIndex,
          profileSourceIds: preparedProfileIds,
          externalSources: cached?.externalSources || compatibleContext.detectedSources,
          epoch,
          requestId: `request_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
          scope,
          turnKey,
          requestSlotKey,
          userInputHash,
          userMessageId,
          userInputText,
          lifecycleEpoch: requestLifecycleEpoch,
          backgroundFence: requestBackgroundFence,
          behindFence: requestBehindFence,
          botOverride: safeClone(botOverride),
          profileRefresh: safeClone(profileRefreshRequest),
          lookaheadEligible,
          lookaheadConversation: safeClone(conversation),
          lookaheadExternalContext: safeClone(compatibleContext.external),
          compatibilityTrace,
          createdAt: Date.now(),
          status: 'awaiting_output',
        });
        if (!pending) return mainMessages;
        try { requestGuard.throwIfAborted('prepared request enqueue'); } catch (error) {
          removePendingContext(pending);
          throw error;
        }
        if (decision.type === 'ACT' && injection) {
          const outgoing = injectBeforeLastUser(mainMessages, injection);
          requestGuard.throwIfAborted('prepared goal injection');
          if (outgoing.filter(message => typeof message?.content === 'string' && message.content.startsWith(INJECTION_START)).length !== 1) {
            pending.decision = safePassThroughDecision('Prepared goal block could not be added uniquely.'); pending.injection = '';
            notePreparedDecisionUse(scope, state, pending, null, '', 'INJECTION_BLOCK_INVALID');
            return mainMessages;
          }
          notePreparedDecisionUse(scope, state, pending, cached, inputBlockReason, preparationBlockReason);
          log('goal plan injected', {
            actors: decision.actions.map((action) => action.actor),
            targets: decision.actions.map((action) => action.target),
            modes: decision.actions.map((action) => action.mode),
            turnKey,
            preparedFromCommit: cached?.baseCommitId || '',
          });
          return outgoing;
        }
        log('no injection', { decision: decision.type, reason: decision.reason, turnKey });
        notePreparedDecisionUse(scope, state, pending, cached, inputBlockReason, preparationBlockReason);
        return mainMessages;
      })();
      return await requestGuard.wait(work, 'beforeRequest');
    } catch (error) {
      requestGuard.abort(error);
      warn('beforeRequest failed; original main request preserved:', error?.message || error);
      const observing = activateFallbackMainObservation(earlyPending);
      setUiStatus(observing
        ? '준비 목표 없이 요청을 통과시켰습니다. 완료된 응답의 관측은 계속합니다.'
        : '준비 목표 확인·전달에 실패하여 이번 메인 요청은 목표 없이 통과했습니다. 저장소 또는 요청 시간 제한을 확인해 주세요.', 'warn');
      return cleaned;
    } finally {
      requestGuard.dispose();
    }
  }

  async function onAfterRequest(content, type) {
    if ((transferBusy && !transferReadOnly) || unloaded || type !== 'model') return content;
    observeCoreHook('afterRequest');
    prunePendingContexts();
    if (!coreHooksOperational()) return content;
    const pending = claimPendingForAfterRequest();
    if (!pending?.scope) return content;
    pending.rawAfterResponse = truncate(typeof content === 'string' ? content : '', 7000);
    if (!chatListenerRegistered) {
      pending.status = 'discarded';
      removePendingContext(pending);
      debug(configCache || DEFAULT_CONFIG, 'committed-output listener unavailable; afterRequest state persistence skipped', { requestId: pending.requestId, scopeKey: pending.scope.scopeKey });
    }
    return content;
  }

  function onCommittedOutput(snapshot) {
    if ((transferBusy && !transferReadOnly) || unloaded || !snapshot) return;
    observeCoreHook('output');
    prunePendingContexts();
    if (!coreHooksOperational()) return;
    const messages = snapshot.chat?.message;
    let messageIndex = Number.isInteger(snapshot.messageIndex) ? snapshot.messageIndex : -1;
    lastOutputIndex = messageIndex;
    // 수동 판단(2026-10-31) 2절 2항: 리스가 응답 위치를 못 주면(-1 — 출력 트리거가 메시지를 바꾼 때 등) 마지막 캐릭터 응답으로 맞춘다. 틀리면 다음 요청의 재동기가 되돌린다.
    if (messageIndex < 0 && Array.isArray(messages)) {
      for (let index = messages.length - 1; index >= 0; index -= 1) if (isCommittedChatMessage(messages[index])) { messageIndex = index; break; }
      if (messageIndex >= 0) debug(configCache || DEFAULT_CONFIG, 'committed-output snapshot had no message index; the latest character response was used', { messageIndex });
    }
    const message = Array.isArray(messages) && messageIndex >= 0 && messageIndex < messages.length
      ? messages[messageIndex]
      : null;
    const outputRole = String(message?.role || '');
    const hasCurrentOutput = messageIndex >= 0 && (outputRole === 'char' || outputRole === 'assistant');
    let precedingUserHash = '';
    let precedingUserMessageId = '';
    if (Array.isArray(messages)) {
      const startIndex = hasCurrentOutput
        ? Math.min(messageIndex - 1, messages.length - 1)
        : messages.length - 1;
      for (let index = startIndex; index >= 0; index -= 1) {
        if (String(messages[index]?.role || '') === 'user') {
          precedingUserHash = commitContentHash(chatMessageText(messages[index]));
          precedingUserMessageId = String(messages[index]?.id ?? messages[index]?.messageId ?? messages[index]?.chatId ?? '');
          break;
        }
      }
    }
    if (!hasCurrentOutput) {
      discardPendingForCoordinates(snapshot, precedingUserHash, precedingUserMessageId);
      return;
    }
    const pending = claimPendingForCoordinates(snapshot, precedingUserHash, precedingUserMessageId);
    if (!pending) return;
    pending.userMessageId = precedingUserMessageId;
    const content = typeof message?.data === 'string'
      ? message.data
      : typeof message?.content === 'string'
        ? message.content
        : pending.rawAfterResponse || '';
    Promise.resolve(commitSuccessfulTurn(pending, content, messageIndex, String(message?.id ?? message?.messageId ?? message?.chatId ?? ''), message?.swipeId)).catch((error) => {
      warn('committed-output save failed:', error?.message || error);
    });
  }

