  function selectedLoreUnits(rows, owners, inventory) {
    const index = selectedLoreInventoryIndex(inventory), order = new Map(rows.map((row, position) => [row, position])), groups = new Map();
    for (const row of rows) {
      const signature = index && row.available && row.solo !== true ? selectedLoreKeySignature(row.entry) : '';
      if (!signature) continue;
      if (!groups.has(signature)) groups.set(signature, []);
      groups.get(signature).push(row);
    }
    const unitOf = new Map();
    for (const members of groups.values()) {
      if (members.length < 2) continue;
      const parts = new Map(), free = [], ids = new Set(members.map(row => row.id));
      for (const row of members) {
        const profile = owners.get(row)?.profile;
        if (!profile) { free.push(row); continue; }
        if (!parts.has(profile.id)) parts.set(profile.id, { profile, rows: [] });
        parts.get(profile.id).rows.push(row);
      }
      if (free.length) {
        // A source without an owner joins a profile only when the choice is clear: the one profile that stands
        // for this group, or, among several, the one the source itself names. A profile the user locked is not
        // analysed again, so it is never extended; a source that would join it becomes a person of its own.
        const manual = profile => profile.locked === true && normalizeProfileLockOrigin(profile.lockOrigin, true) === 'manual';
        const stands = part => part.rows.some(row => selectedLoreRowNamesProfile(row, part.profile))
          || (part.profile.selectedLore?.entries || []).every(claim => { const item = claim.hash ? selectedLoreClaimSource(claim, part.profile, index) : null; return !item || ids.has(item.id); });
        const standing = [...parts.values()].filter(stands), loose = [];
        for (const row of free) {
          const named = standing.filter(part => selectedLoreRowNamesProfile(row, part.profile));
          const home = named.length === 1 ? named[0] : standing.length === 1 ? standing[0] : null;
          if (home && !manual(home.profile)) home.rows.push(row); else loose.push(row);
        }
        if (loose.length) parts.set('', { profile: null, rows: loose });
      }
      for (const part of parts.values()) {
        part.rows.sort((left, right) => order.get(left) - order.get(right));
        for (const row of part.rows) unitOf.set(row, part);
      }
    }
    const units = [];
    for (const row of rows) {
      const unit = unitOf.get(row) || { profile: owners.get(row)?.profile || null, rows: [row] };
      if (unit.rows[0] === row) units.push(unit);
    }
    return units;
  }



  // Counted by person: total, complete and pending are people, `lore` is the number of selected sources.
  function selectedLoreProgress(selection, context) {
    const rows = selectedLoreRows(selection, context.inventory), owners = selectedLoreOwnership(context.profiles, context.scope, rows, context.inventory);
    for (const row of rows) {
      const owner = owners.get(row);
      row.duplicates = owner.duplicates;
      if (!context.inventory) { row.available = true; row.hash = row.savedHash || (owner.profile?.selectedLore?.entries || []).find(entry => entry.id === row.id)?.hash || ''; }
    }
    const units = selectedLoreUnits(rows, owners, context.inventory);
    for (const unit of units) {
      unit.complete = selectedLoreUnitComplete(unit, owners);
      for (const row of unit.rows) {
        row.profile = unit.profile;
        row.complete = unit.complete;
        row.manual = unit.profile?.locked === true && normalizeProfileLockOrigin(unit.profile.lockOrigin, true) === 'manual';
      }
    }
    const complete = units.filter(unit => unit.complete).length, unavailable = rows.filter(row => !row.available).length;
    return { rows, units, total: units.length, lore: rows.length, complete, pending: units.length - complete - unavailable, unavailable,
      duplicateProfiles: new Set(rows.flatMap(row => row.duplicates)).size,
      profileCount: new Set(units.filter(unit => unit.complete).map(unit => unit.profile.id)).size };
  }


  function selectedLoreProgressText(selection, context) {
    const progress = selectedLoreProgress(selection, context);
    return `${selectedLoreCountsText(progress)}${progress.unavailable ? ` · 자료 사용 불가 ${progress.unavailable}개` : ''}`;
  }

  function selectedLoreSourceStats(selection, inventory) {
    const rows = selectedLoreRows(selection, inventory).filter(row => row.available), counts = {}, modules = new Set();
    for (const row of rows) {
      const kind = row.entry.sourceKinds?.[0] || 'character_lore'; counts[kind] = (counts[kind] || 0) + 1;
      for (const ref of row.entry.sourceRefs || []) if (ref.moduleName) modules.add(ref.moduleName);
    }
    return { ...counts, totalChars: rows.reduce((sum, row) => sum + row.text.length, 0), documents: rows.length, modules: modules.size };
  }

  function stageSelectedLoreReuse(profile, candidate, variantKey, scope, inventory, token) {
    if (!profile || !(profile.ownerBundleKeys || []).includes(scope.sourceBundleKey) || profile.scopeOwnership?.scopeKey) return false;
    const current = rosterProfileForVariant(profile, variantKey);
    if (current) {
      if (current.selectedLore?.entries?.length || !['ready', 'low_evidence'].includes(current.analysisStatus)
        || current.sourceHash !== inventory.sourceHash || !candidate.sourceDocumentIds.every(id => (current.sourceDocumentIds || []).includes(id))) return false;
      if (profile.variants?.[variantKey]) profile.variants[variantKey].selectedLore = safeClone(candidate.selectedLore);
      if (String(profile.activeVariantKey || 'default') === variantKey) profile.selectedLore = safeClone(candidate.selectedLore);
      return true;
    }
    if (profile.ownerBundleKeys.length !== 1) return false;
    const donors = Object.values(profile.variants || {}).filter(variant => ['ready', 'low_evidence'].includes(variant.analysisStatus)
      && candidate.selectedLore.entries.every(entry => !!entry.hash && (variant.selectedLore?.entries || []).some(saved => saved.hash === entry.hash)));
    if (!donors.length || new Set(donors.map(variant => durableValueHash({ baseProfile: variant.baseProfile, userOverrides: variant.userOverrides, locked: variant.locked, profileConfidence: variant.profileConfidence }))).size !== 1) return false;
    const variant = { ...safeClone(donors[0]), label: inventory.variantLabel || variantKey, activationSignature: inventory.activationSignature || '', sourceHash: inventory.sourceHash,
      selectedLore: safeClone(candidate.selectedLore), sourceDocumentIds: [...candidate.sourceDocumentIds] };
    token.rosterVariantReuses ||= {};
    token.rosterVariantReuses[profile.id] = { beforeHash: durableValueHash(profile), variant: safeClone(variant) };
    profile.variants = { ...profile.variants, [variantKey]: variant };
    Object.assign(profile, materializeProfileVariant(profile, variantKey), { activeVariantKey: variantKey });
    return true;
  }


  // `slotHandleBundle` is the bot key while the notes still name their targets by slot handles (see contentIds).
  function validSelectedLoreDrafts(values, rows, previousSelection = null, inventory = null, slotHandleBundle = '') {
    const usable = rows.filter(row => row.available), exact = new Set(usable.map(row => `${row.id}\n${row.hash}`)), byHash = new Map();
    for (const row of usable) byHash.set(row.hash, [...(byHash.get(row.hash) || []), row.id]);
    // Entry ids are positional. Translate ids recorded by the previous run to the slots that hold the same sources now.
    const previous = new Map((previousSelection && inventory ? selectedLoreRows(previousSelection, inventory) : rows).filter(row => row.available).map(row => [row.savedId, row]));
    const current = entry => !entry?.hash ? '' : exact.has(`${entry.id}\n${entry.hash}`) ? entry.id
      : previous.get(entry.id)?.hash === entry.hash ? previous.get(entry.id).id : byHash.get(entry.hash)?.length === 1 ? byHash.get(entry.hash)[0] : '';
    const output = [];
    for (const draft of Array.isArray(values) ? values : []) {
      if (!isPlainObject(draft) || !isPlainObject(draft.value) || !isPlainObject(draft.fromRef) || !isPlainObject(draft.toRef)
        || !Array.isArray(draft.originEntries) || !draft.originEntries.length) continue;
      // The notes stay valid only while every source they were written from is unchanged.
      const origins = draft.originEntries.map(current);
      if (origins.some(id => !id)) continue;
      const moves = new Map([...[...previous].map(([id, row]) => [id, row.id]), ...draft.originEntries.map((entry, position) => [entry.id, origins[position]])]);
      const remap = ids => [...new Set((Array.isArray(ids) ? ids : []).map(id => moves.get(id)).filter(Boolean))];
      const next = safeClone(draft);
      next.originEntries = draft.originEntries.map((entry, position) => ({ id: origins[position], hash: entry.hash }));
      next.fromRef.entryIds = remap(draft.fromRef.entryIds);
      next.toRef.entryIds = remap(draft.toRef.entryIds);
      // A slot handle names one slot, while the listed ids cover every slot of the profile it stood for then.
      if (slotHandleBundle) for (const [ref, saved] of [[next.fromRef, draft.fromRef], [next.toRef, draft.toRef]]) {
        const meant = [...draft.originEntries.map(entry => entry.id), ...(Array.isArray(saved.entryIds) ? saved.entryIds : [])]
          .find(id => saved.name === `selected_lore_${fnv1a(`${slotHandleBundle}:${id}`)}`);
        if (meant) ref.entryIds = remap([meant]);
      }
      if (Array.isArray(draft.value.sourceDocumentIds)) next.value.sourceDocumentIds = remap(draft.value.sourceDocumentIds);
      output.push(next);
    }
    return output.slice(-MAX_PROFILE_CHARACTERS * 4);
  }

  function rememberSelectedLoreRelations(run, values, group, candidates, idMap) {
    const reference = raw => {
      const name = truncate(raw, 180), lower = name.toLocaleLowerCase();
      if (['user', 'persona'].includes(lower)) return { name: 'user', entryIds: [] };
      const target = candidates.filter(candidate => [candidate.id, idMap.get(candidate.id), ...candidateNames(candidate)].some(value => String(value || '').toLocaleLowerCase() === lower));
      return { name, entryIds: target.length === 1 ? [...target[0].sourceDocumentIds] : [] };
    };
    for (const raw of (Array.isArray(values) ? values : []).slice(0, MAX_PROFILE_CHARACTERS * 4)) {
      if (!isPlainObject(raw) || !raw.from || !raw.to) continue;
      const value = { label: truncate(raw.label, 300), confidence: Math.round(clampNumber(raw.confidence, 0)),
        sourceDocumentIds: normalizeStringList(raw.sourceDocumentIds, 40, 180), evidence: normalizeStringList(raw.evidence, 16, 400), notes: normalizeStringList(raw.notes, 20, 400) };
      for (const key of ['affection', 'eroticAttraction', 'hatred']) if (optionalNumber(raw[key]) !== null) value[key] = Math.round(clampNumber(raw[key], 0));
      const draft = { fromRef: reference(raw.from), toRef: reference(raw.to), value,
        originEntries: group.flatMap(candidate => candidate.selectedLore.entries).map(entry => ({ ...entry })) };
      const key = fnv1a(JSON.stringify(draft));
      if (!run.relationDrafts.some(item => fnv1a(JSON.stringify(item)) === key)) run.relationDrafts.push(draft);
      if (run.relationDrafts.length > MAX_PROFILE_CHARACTERS * 4) throw new Error('선택 분석의 관계 자료 한도를 넘었습니다.');
    }
  }



  // One candidate per person: a single source, or the sources that share their activation keys.
  function buildSelectedLoreCandidates(selection, inventory, scope, store) {
    const rows = selectedLoreRows(selection, inventory).filter(row => row.available), owners = selectedLoreOwnership(store, scope, rows, inventory), used = new Map();
    return selectedLoreUnits(rows, owners, inventory).map(unit => {
      const existing = unit.profile, row = unit.rows[0];
      // The candidate id follows the content and title, never the slot: a new person in an old slot must not
      // inherit that slot's identity. Sources with identical text and title are told apart by their order.
      const base = `selected_lore_${fnv1a(`${scope.sourceBundleKey}:${row.hash}:${selectedLoreTitleKey(row.title)}`)}`;
      used.set(base, (used.get(base) || 0) + 1);
      const candidate = normalizeCandidate({ id: used.get(base) > 1 ? `${base}_${used.get(base)}` : base,
        name: existing?.name || `${truncate(row.title, 140)} #${fnv1a(`${row.hash}:${selectedLoreTitleKey(row.title)}`).slice(0, 6)}`,
        // The opening of up to four sources: 400 characters each for one or two sources, 800 in all beyond that.
        aliases: existing?.aliases || [], sourceKinds: row.entry.sourceKinds, confidence: 100,
        evidence: unit.rows.slice(0, 4).map(source => source.text.slice(0, Math.min(400, Math.floor(800 / Math.min(unit.rows.length, 4))))),
      }, [], scope);
      candidate.isMain = false;
      candidate.sourceKinds = normalizeStringList(unit.rows.flatMap(source => source.entry.sourceKinds || []), 12, 120);
      candidate.sourceDocumentIds = unit.rows.map(source => source.id);
      candidate.selectedLore = { entries: unit.rows.map(source => ({ id: source.id, hash: source.hash })) };
      candidate.selectedLorePrevious = unit.rows.map(source => source.savedHash && source.savedHash !== source.hash ? source.savedHash : '').filter(Boolean);
      candidate.sourceTitle = row.title;
      // Every source keeps its own block; sourceParts are the block lengths, so each can be cut to its share.
      const blocks = unit.rows.map(source => `[SOURCE ${source.id} | TARGET ${candidate.id} | ${source.title}]\n${source.text}`);
      candidate.sourceText = blocks.join('\n\n');
      candidate.sourceParts = blocks.map(block => block.length);
      candidate.entityVerdict = normalizeEntityVerdict({ status: 'verified_person', entityType: 'person', confidence: 100,
        reason: '사용자가 선택한 인물 로어북', source: 'selected_lore' });
      return candidate;
    });
  }

  // Re-saves the selection so each entry names the slot that holds its source now. Stale slots whose
  // content is already selected elsewhere are merged by the resolver.
  async function saveSelectedLoreLinks(scope, inventory, store) {
    const selection = normalizeLoreSelection((await getBotOverride(scope.sourceBundleKey)).loreSelection);
    const rows = selectedLoreRows(selection, inventory), owners = selectedLoreOwnership(store, scope, rows, inventory);
    const selectedEntries = normalizeLoreSelection({ selectedEntries: rows.map(row => selectedLoreSavedEntry(row, owners.get(row).exact)) }).selectedEntries;
    if (JSON.stringify(selectedEntries) === JSON.stringify(selection.selectedEntries)) return selection;
    await updateBotOverride(scope.sourceBundleKey, { loreSelection: { selectedEntries, revision: selection.revision + 1 } });
    return normalizeLoreSelection((await getBotOverride(scope.sourceBundleKey)).loreSelection);
  }

  async function startSelectedLoreAnalysis(context, requestIntent = 'start') {
    assertTransferAdmission();
    if (!context?.isLiveScope || analysisRuntime.running) throw new Error('현재 채팅에서 다른 분석이 끝난 뒤 실행해 주세요.');
    const config = normalizeConfig(uiDraftConfig || context.config);
    if (!normalizeLoreSelection((await getBotOverride(context.scope.sourceBundleKey)).loreSelection).selectedEntries.length) throw new Error('분석할 인물 로어북을 선택해 주세요.');
    const fence = captureBackgroundFence(context.scope);
    try {
      const inventory = await collectSourceInventory(context.character, context.scope, { force: true, maxSourceChars: config.analysisMaxSourceChars });
      const store = await loadProfileStore();
      assertBackgroundFence(fence, 'selected lore start');
      context.scope.variantKey = resolveInventoryVariantKey(store, context.scope.sourceBundleKey, inventory);
      inventory.variantKey = context.scope.variantKey; context.scope.variantLabel = inventory.variantLabel;
      await updateBotOverride(context.scope.sourceBundleKey, { activeVariantKey: context.scope.variantKey });
      const selection = await saveSelectedLoreLinks(context.scope, inventory, store);
      await compileProfilesFromInventory(context.character, context.scope, config, inventory,
        { force: true, analysisWorkflow: 'selected_lore', loreSelection: selection, resume: requestIntent === 'resume', requestIntent });
      assertBackgroundFence(fence, 'selected lore completion');
      await saveSelectedLoreLinks(context.scope, inventory, await loadProfileStore());
      setUiStatus(analysisRuntime.detail, analysisRuntime.phase === 'partial' ? 'warn' : 'ok');
    } catch (error) {
      if (!isStaleLifecycleError(error)) setUiStatus(`인물 로어북 분석: ${error?.message || error}`, 'error');
    }
    await renderSettingsApp(false);
  }

  // Every current source, with saved entries shown at the slot that holds their source now. A saved
  // source that can no longer be found stays listed (and selected) until the user unchecks it.
  

  

  // What the selector shows for the picked sources: the person each one belongs to, and its peers, the
  // other picked sources with the same activation keys (kept apart or not).
  

  

  

  

  // Time one check may spend on trial merges of separately stored people (milliseconds).
  

  // Finds what position-based linking and source-by-source analysis left behind: several people's sources
  // on one profile, two profiles holding one source, one person's sources held by separate profiles, and
  // selections whose source is gone. Stored data and current lore only.
  

  // Merges the profiles of one person. The retired profiles' parallel initial relations are dropped first;
  // when the merge is refused they are put back, so a refused merge leaves the records as they were.
  

  // Two profiles analysed from one source hold parallel initial relations. Keep the representative's
  // and drop the retired profile's copies that would collide when the two are merged.
  

  // Pure transform of the stored records. Sources detached here become pending work and are analysed as
  // their own people by the next selected-lore run, which also writes their initial relations.
  

  

  

  // The repair has to work on a store that is larger than one backup file may be, so it does not use the
  // portable backup codec's size-limited digests. A record is read as canonical JSON (sorted keys) piece by
  // piece and hashed in chunks: no text of a whole record is ever built.
  

  

  

  

  // Recovery copy of one stored record: only what the repair changes in it. For an object the order of its
  // keys and the copies of its changed members are kept; anything else that changed (a list, a text, a member
  // the repair removes) is kept whole, as it was. Applied to what the repair wrote, the copy gives the record
  // back as it was. Null when nothing differs.
  

  

  // Plain wording for the internal codes a check can end with.
  

  

  

  // Puts back the records the last repair wrote, but only while they still hold what that repair wrote.
  // Once anything in them was saved again (an analysis, an edit, another bot's profiles), nothing is undone.
  

  

  

  

  function buildRosterCandidates(selection, inventory, scope, linkedPeople = null) {
    return (linkedPeople || linkRosterPeople(selection.people, inventory, selection)).map(person => {
      if (person.sourceUnavailable) throw new Error(`${person.name}: 현재 명단에서 원문을 찾지 못했습니다. AI 리스트 검사로 명단을 다시 확인해 주세요.`);
      const input = rosterPersonInput(person, inventory);
      const sourceDocumentIds = [person.rosterEntryId, person.matchedLoreId].filter(Boolean);
      const sources = inventory.documents.filter(document => sourceDocumentIds.includes(document.id));
      const candidate = normalizeCandidate({
        id: `roster_${fnv1a(scope.sourceBundleKey + '::' + person.key)}`,
        name: person.name, aliases: person.aliases, confidence: 100, entityType: 'person', isPerson: true,
        evidence: [person.sourceBlock.slice(0, 400)],
      }, sources, scope);
      candidate.sourceDocumentIds = sourceDocumentIds;
      if (!candidate.sourceKinds.length) candidate.sourceKinds = normalizeStringList((inventory.rosterEntries || []).filter(entry => sourceDocumentIds.includes(entry.id)).flatMap(entry => entry.sourceKinds || ['character_lore']), 12, 120);
      candidate.entityVerdict = normalizeEntityVerdict({ status: 'verified_person', entityType: 'person', confidence: 100, reason: '사용자가 확인한 인물 명단', source: 'roster_confirmation' });
      candidate.sourceText = input.sourceText;
      candidate.roster = { personKey: person.key, sourceHash: input.sourceHash, rosterEntryId: person.rosterEntryId, matchedLoreId: person.matchedLoreId };
      return candidate;
    });
  }

  async function startRosterCharacterAnalysis(context, requestIntent = 'start') {
    assertTransferAdmission();
    if (!context.isLiveScope || analysisRuntime.running) throw new Error('현재 채팅에서 다른 분석이 끝난 뒤 실행해 주세요.');
    const config = normalizeConfig(uiDraftConfig || context.config);
    const selection = normalizeRosterDiscovery((await getBotOverride(context.scope.sourceBundleKey)).rosterDiscovery);
    if (!selection.confirmed || !selection.people.length) throw new Error('AI 리스트 검사에서 인물을 먼저 확정해 주세요.');
    const fence = captureBackgroundFence(context.scope);
    try {
      const inventory = await collectSourceInventory(context.character, context.scope, { force: true, maxSourceChars: config.analysisMaxSourceChars });
      const store = await loadProfileStore();
      assertBackgroundFence(fence, 'roster profile start');
      context.scope.variantKey = resolveInventoryVariantKey(store, context.scope.sourceBundleKey, inventory);
      inventory.variantKey = context.scope.variantKey;
      context.scope.variantLabel = inventory.variantLabel;
      await updateBotOverride(context.scope.sourceBundleKey, { activeVariantKey: context.scope.variantKey });
      await compileProfilesFromInventory(context.character, context.scope, config, inventory, { force: true, rosterSelection: selection, requestIntent });
      assertBackgroundFence(fence, 'roster profile completion');
      setUiStatus(analysisRuntime.detail, analysisRuntime.phase === 'partial' ? 'warn' : 'ok');
    } catch (error) {
      if (!isStaleLifecycleError(error)) setUiStatus(`명단 캐릭터 분석: ${error?.message || error}`, 'error');
    }
    await renderSettingsApp(false);
  }

  function rosterEntrySource(entry, selection, inventory) {
    const raw = String(entry?.rawContent ?? entry?.content ?? '');
    if (!selection.rosterDropGlobalToggles) return rosterParser.stripTemplate(raw);
    if (typeof prepareConditionalLoreContent === 'function') {
      return prepareConditionalLoreContent(raw, inventory?.variableContext, { includeGlobalToggles: false }).profileContent;
    }
    return rosterParser.stripTemplate(rosterParser.dropGlobalToggleBlocks(raw));
  }


  function linkRosterPeople(people, inventory, selection) {
    const entries = inventory?.rosterEntries || [];
    const rosterIds = new Set();
    const currentLists = new Map();
    for (const selected of selection.selectedEntries) {
      const entry = resolveSelectedRosterEntry(selected, entries);
      if (!entry) continue;
      rosterIds.add(entry.id);
      const text = rosterEntrySource(entry, selection, inventory);
      const current = { entry, text, members: rosterParser.parseRoster(text) };
      currentLists.set(selected.id, current);
      currentLists.set(entry.id, current);
    }
    for (const hit of rosterParser.detectRosterEntries(inventory?.rosterEntries || [])) rosterIds.add(hit.entry.id);
    const pool = entries.filter(entry => !rosterIds.has(entry.id) && String(entry.profileContent ?? entry.content ?? '').trim());
    return people.map(person => {
      const current = currentLists.get(person.rosterEntryId);
      const member = current?.members.find(item => rosterParser.normalizeName(item.name) === person.key
        || (item.aliases || []).some(alias => rosterParser.normalizeName(alias) === person.key));
      const sourceBlock = member?.sourceBlock || (current?.text.includes(person.sourceBlock) ? person.sourceBlock : '');
      const match = rosterParser.matchLore(person, pool);
      const hit = match.hits[0]; // First match ends this person's lookup, including fallback stages.
      return { ...person, rosterEntryId: current?.entry.id || person.rosterEntryId, sourceBlock, sourceUnavailable: !sourceBlock,
        activationKeys: normalizeStringList([person.name, ...person.aliases, ...(hit ? String(hit.key || '').split(',') : [])], 80, 180),
        matchedLoreId: hit?.id || '', matchHow: hit ? match.how : 'none' };
    });
  }



  function matchRosterProfiles(people, store, bundleKey, variantKey) {
    const profiles = Object.values(store?.profiles || {}).filter(profile => (profile.ownerBundleKeys || []).includes(bundleKey))
      .map(profile => rosterProfileForVariant(profile, variantKey)).filter(Boolean);
    const result = new Map(), used = new Set();
    for (const person of people) {
      const direct = profiles.filter(profile => profile.roster?.personKey === person.key);
      if (direct.length === 1) { result.set(person.key, direct[0]); used.add(direct[0].id); }
    }
    const proposed = new Map(), claims = new Map();
    for (const person of people) {
      if (result.has(person.key)) continue;
      const names = new Set([person.name, ...(person.aliases || [])].map(rosterParser.normalizeName).filter(Boolean));
      const matches = profiles.filter(profile => !used.has(profile.id) && !profile.roster?.personKey
        && [profile.name, ...(profile.aliases || [])].some(name => names.has(rosterParser.normalizeName(name))));
      if (matches.length !== 1) continue;
      proposed.set(person.key, matches[0]);
      claims.set(matches[0].id, (claims.get(matches[0].id) || 0) + 1);
    }
    for (const [key, profile] of proposed) if (claims.get(profile.id) === 1) result.set(key, profile);
    return result;
  }

  

  

  

