  function profileAuditSnapshot(profile, variantKey = 'default') {
    if (!profile) return null;
    const current = materializeProfileVariant(profile, variantKey) || profile;
    const base = normalizeEroticProfile(current.baseProfile || {});
    const confidence = normalizeProfileConfidence(current.profileConfidence || current.confidence, current.confidence ?? 50);
    const verdict = effectiveEntityVerdict(current);
    const compactBehavior = (behavior) => ({
      frequency: Math.round(clampNumber(behavior?.frequency, 50)),
      directness: Math.round(clampNumber(behavior?.directness, 50)),
      styles: normalizeStringList(behavior?.styles, 8, 180),
      typicalSituations: normalizeStringList(behavior?.typicalSituations, 8, 220),
    });
    return {
      genderIdentity: base.genderIdentity,
      eroticInterest: Math.round(clampNumber(base.eroticInterest?.level, 50)),
      targetGenderPreference: {
        malePercent: Math.round(clampNumber(base.targetGenderPreference?.malePercent, 0)),
        femalePercent: Math.round(clampNumber(base.targetGenderPreference?.femalePercent, 0)),
        genderlessPercent: Math.round(clampNumber(base.targetGenderPreference?.genderlessPercent, 0)),
        confidence: base.targetGenderPreference.confidence,
        basis: base.targetGenderPreference.basis,
        status: base.targetGenderPreference.status,
        evidence: normalizeStringList(base.targetGenderPreference.evidence, 8, 400),
        notes: truncate(base.targetGenderPreference.notes, 500),
        migratedFromLegacy: base.targetGenderPreference.migratedFromLegacy,
        needsReanalysis: base.targetGenderPreference.needsReanalysis,
        lastAnalysisStatus: base.targetGenderPreference.lastAnalysisStatus,
        lastAnalysisNote: base.targetGenderPreference.lastAnalysisNote,
      },
      initiative: Number.isFinite(base.initiative) ? base.initiative : null,
      spontaneity: Number.isFinite(base.spontaneity) ? base.spontaneity : null,
      directness: Number.isFinite(base.directness) ? base.directness : null,
      goalPersistence: Number.isFinite(base.goalPersistence) ? base.goalPersistence : null,
      obsessiveness: Number.isFinite(base.obsessiveness) ? base.obsessiveness : null,
      publicOpenness: Number.isFinite(base.publicOpenness) ? base.publicOpenness : null,
      extremity: Number.isFinite(base.extremity) ? base.extremity : null,
      // 성적 축(2026-10-22): 값이 있을 때만(없는 프로필의 감사 모양은 전과 같다). 동기 유형은 "주된+보조" 글자로.
      ...Object.fromEntries(SEX_AXIS_SCALAR_KEYS.filter(axis => Number.isFinite(base[axis])).map(axis => [axis, base[axis]])),
      ...(base.sexualMotive ? { sexualMotive: `${base.sexualMotive.primary}${base.sexualMotive.secondary ? `+${base.sexualMotive.secondary}` : ''}` } : {}),
      sexualPreferences: normalizeStringList(base.sexualPreferences, 10, 220),
      ...(base.positionPreferences ? { positionPreferences: normalizePositionPreferences(base.positionPreferences) } : {}),
      ...(base.menstrualCycle ? { menstrualCycle: normalizeCycleProfile(base.menstrualCycle, base.genderIdentity) } : {}),
      sexualHumor: compactBehavior(base.sexualHumor),
      flirting: compactBehavior(base.flirting),
      seduction: compactBehavior(base.seduction),
      goalPatterns: normalizeStringList(base.goalPatterns, 10, 240),
      voiceNotes: normalizeStringList(base.voiceNotes, 10, 240),
      profileConfidence: confidence.overall,
      analysisStatus: current.analysisStatus || 'ready',
      entityVerdict: {
        status: verdict.status,
        entityType: verdict.entityType,
        confidence: verdict.confidence,
        reason: truncate(verdict.reason, 280),
      },
    };
  }

  function enqueueProfileAuditMutation(mutation) {
    const run = async () => await mutation();
    const task = profileAuditWriteQueue.then(run, run);
    profileAuditWriteQueue = task.catch(() => {});
    return task;
  }

  async function loadProfileAuditStoreForMutation() {
    const read = requireReadableStorageState(PROFILE_AUDIT_KEY, await pluginStorageReadState(PROFILE_AUDIT_KEY), (value) => isPlainObject(value) && (value.entries === undefined || Array.isArray(value.entries)));
    if (read.status === 'missing') return { schemaVersion: 1, entries: [] };
    return {
      ...read.value,
      schemaVersion: 1,
      entries: (Array.isArray(read.value?.entries) ? read.value.entries : []).filter(isPlainObject),
    };
  }


  async function reconcileProfileAuditRetention(value) {
    const limit = clampInt(value, 20, 0, 40);
    profileAuditGeneration += 1;
    return await enqueueProfileAuditMutation(async () => {
      const store = await loadProfileAuditStoreForMutation();
      const retained = retainProfileAuditRows(store.entries || [], limit);
      if (retained.length === 0 && limit <= 0) { await pluginStorageRemove(PROFILE_AUDIT_KEY); return 0; }
      await pluginStorageSet(PROFILE_AUDIT_KEY, { schemaVersion: 1, entries: retained });
      return retained.length;
    });
  }

  

  

  async function appendProfileAuditEntries(context, drafts) {
    const liveConfig = await loadConfig();
    const limit = clampInt(liveConfig.profileAuditLimit, 20, 0, 40);
    const expectedGeneration = profileAuditGeneration;
    const expectedLifecycleEpoch = Number.isInteger(context?.lifecycleEpoch)
      ? context.lifecycleEpoch
      : Number.isInteger(context?.auditLifecycleEpoch)
        ? context.auditLifecycleEpoch
        : lifecycleEpoch;
    if (limit <= 0 || unloaded || expectedLifecycleEpoch !== lifecycleEpoch) return 0;
    const scope = context?.scope || context || {};
    const entries = [];
    for (const draft of Array.isArray(drafts) ? drafts : []) {
      const profile = draft?.profile;
      if (!profile?.id) continue;
      const fieldChanges = Array.isArray(draft.fieldChanges)
        ? draft.fieldChanges.slice(0, 32).map((change) => ({
          path: truncate(change?.path || 'profile', 160),
          before: sanitizeProfileAuditValue(change?.before),
          after: sanitizeProfileAuditValue(change?.after),
        })).filter((change) => JSON.stringify(change.before) !== JSON.stringify(change.after))
        : collectProfileAuditChanges(draft.before, draft.after);
      if (fieldChanges.length === 0) continue;
      const entry = {
        id: `audit_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
        sourceBundleKey: scope.sourceBundleKey || '',
        scopeKey: scope.scopeKey || '',
        variantKey: scope.variantKey || profile.activeVariantKey || 'default',
        profileId: profile.id,
        profileName: profile.name,
        runId: truncate(draft.runId || context?.runId, 180),
        turn: Number(draft.turn ?? context?.session?.turnIndex ?? 0),
        at: draft.at || new Date().toISOString(),
        source: truncate(draft.source || 'change', 80),
        fieldChanges,
        reason: truncate(draft.reason, 400),
        evidenceCount: Math.min(9999, Number(draft.evidenceCount ?? profile.evidence?.length ?? 0)),
      };
      entry.dedupeKey = fnv1a(JSON.stringify({
        sourceBundleKey: entry.sourceBundleKey,
        scopeKey: entry.scopeKey,
        variantKey: entry.variantKey,
        profileId: entry.profileId,
        runId: entry.runId,
        turn: entry.turn,
        source: entry.source,
        fieldChanges: entry.fieldChanges,
        reason: entry.reason,
      }));
      entries.push(entry);
    }
    if (entries.length === 0) return 0;
    return await enqueueProfileAuditMutation(async () => {
      if (unloaded || expectedGeneration !== profileAuditGeneration || expectedLifecycleEpoch !== lifecycleEpoch) return 0;
      const store = await loadProfileAuditStoreForMutation();
      if (unloaded || expectedGeneration !== profileAuditGeneration || expectedLifecycleEpoch !== lifecycleEpoch) return 0;
      store.schemaVersion = 1;
      const previous = Array.isArray(store.entries) ? store.entries : [];
      const known = new Set(previous.map((entry) => entry?.dedupeKey).filter(Boolean));
      const added = entries.filter((entry) => !known.has(entry.dedupeKey));
      if (added.length === 0) return 0;
      store.entries = retainProfileAuditRows([...previous, ...added], limit);
      if (unloaded || expectedGeneration !== profileAuditGeneration || expectedLifecycleEpoch !== lifecycleEpoch) return 0;
      await pluginStorageSet(PROFILE_AUDIT_KEY, store);
      return added.length;
    });
  }

  async function appendProfileAudit(context, profile, source, before, after, reason = '') {
    return await appendProfileAuditEntries(context, [{ profile, source, before, after, reason }]);
  }

  async function saveProfileOverrides(profileId, context, overrides, source = 'user_edit') {
    assertTransferAdmission();
    await preemptAutoProfileRefreshForMutation(context?.scope?.sourceBundleKey || '', 'profile override change');
    const result = await mutateProfileRegistry('profile user override', (store) => {
      const profile = store.profiles?.[profileId];
      if (!profile) return null;
      const variantKey = String(context.scope?.variantKey || profile.activeVariantKey || 'default');
      const current = materializeProfileVariant(profile, variantKey);
      const before = safeClone(current.userOverrides || {});
      profile.userOverrides = isPlainObject(overrides) ? safeClone(overrides) : {};
      profile.updatedAt = new Date().toISOString();
      saveProfileVariant(profile, variantKey, {
        label: current.variantLabel || variantKey,
        activationSignature: profile.variants?.[variantKey]?.activationSignature || '',
        sourceHash: current.sourceHash,
        sourceDocumentIds: current.sourceDocumentIds,
      });
      return { profileId, name: profile.name, before, after: safeClone(profile.userOverrides) };
    }, { writeRegistry: false });
    if (!result.outcome) return;
    invalidateAllPreparedDecisionState('profile override changed');
    try {
      const durableProfile = result.profiles?.profiles?.[profileId];
      if (durableProfile) await appendProfileAudit(context, durableProfile, source, result.outcome.before, result.outcome.after, source === 'user_reset' ? '사용자 수정 전체 초기화' : '사용자 프로필 수정');
    } catch (error) {
      warn('user profile audit save skipped:', error?.message || error);
    }
    setUiStatus(source === 'user_reset' ? `${result.outcome.name} 사용자 수정값을 초기화했습니다.` : `${result.outcome.name} 사용자 수정값을 저장했습니다.`, 'ok');
    await renderSettingsApp(false);
  }

  

  

  


