  async function resolveCoreHookPermission() {
    if (typeof R.requestPluginPermission !== 'function') {
      coreHookPermissionState = 'legacy_unverified';
      warn('replacer permission API is unavailable; legacy hooks will remain inactive until beforeRequest, afterRequest, and output callbacks are all observed');
      return 'legacy';
    }
    try {
      const granted = await R.requestPluginPermission('replacer');
      if (granted === true) {
        coreHookPermissionState = 'granted';
        return 'trusted';
      }
      coreHookPermissionState = 'denied';
      warn('replacer permission was denied; Erosync core request/output hooks remain inactive while settings UI stays available');
      return 'inactive';
    } catch (error) {
      coreHookPermissionState = 'error';
      warn('replacer permission check failed; Erosync core hooks remain inactive:', error?.message || error);
      return 'inactive';
    }
  }

  async function removeRegisteredCoreHooks() {
    const removals = [];
    if (beforeRequestHookRequested && typeof R.removeRisuReplacer === 'function') {
      removals.push(Promise.resolve().then(() => R.removeRisuReplacer('beforeRequest', onBeforeRequest)).catch(() => {}));
    }
    if (afterRequestHookRequested && typeof R.removeRisuReplacer === 'function') {
      removals.push(Promise.resolve().then(() => R.removeRisuReplacer('afterRequest', onAfterRequest)).catch(() => {}));
    }
    if (outputHookRequested && typeof R.removeRisuChatListener === 'function') {
      removals.push(Promise.resolve().then(() => R.removeRisuChatListener('output', onCommittedOutput)).catch(() => {}));
    }
    await Promise.allSettled(removals);
    coreHookRegistrationMode = 'inactive';
    beforeRequestHookRequested = false;
    afterRequestHookRequested = false;
    outputHookRequested = false;
    beforeRequestHookRegistered = false;
    afterRequestHookRegistered = false;
    outputHookRegistered = false;
    beforeRequestHookObserved = false;
    afterRequestHookObserved = false;
    outputHookObserved = false;
    chatListenerRegistered = false;
  }

  async function registerCoreHooks() {
    if (stateRecoveryFault) {
      coreHookPermissionState = 'storage_recovery_required';
      coreHookRegistrationMode = 'inactive';
      warn('core hooks remain inactive until the pending shared-state transaction can be recovered');
      return false;
    }
    const registrationMode = await resolveCoreHookPermission();
    if (registrationMode === 'inactive') return false;
    coreHookRegistrationMode = registrationMode;
    try {
      if (typeof R.addRisuReplacer !== 'function') throw new Error('RisuAI replacer registration API is unavailable');
      beforeRequestHookRequested = true;
      await R.addRisuReplacer('beforeRequest', onBeforeRequest);
      beforeRequestHookRegistered = registrationMode === 'trusted';
      afterRequestHookRequested = true;
      await R.addRisuReplacer('afterRequest', onAfterRequest);
      afterRequestHookRegistered = registrationMode === 'trusted';
      if (typeof R.addRisuChatListener === 'function') {
        outputHookRequested = true;
        await R.addRisuChatListener('output', onCommittedOutput);
        outputHookRegistered = registrationMode === 'trusted';
        chatListenerRegistered = registrationMode === 'trusted';
        if (registrationMode === 'trusted') log('core request/output hooks registered through the trusted permission path');
        else log('legacy core hook registration requested; first complete callback cycle is a pass-through bootstrap');
      } else {
        throw new Error('committed-output listener API is unavailable');
      }
      return true;
    } catch (error) {
      coreHookPermissionState = 'registration_failed';
      warn('core hook registration failed; rolling back already registered hooks:', error?.message || error);
      await removeRegisteredCoreHooks();
      return false;
    }
  }

