        scopeCatalogCache = null;
        botOverrideCache = null;
        pendingByCoordinates.clear();
        pendingMainOrder.length = 0;
        committedOutputKeys.clear();
        scopeDecisionEpochs.clear();
        vertexTokenCache = null;
        if (uiRefreshTimer) clearTimeout(uiRefreshTimer);
